update content_bodies set title = 'Rishiri Island in Winter', description = 'A preview of the winter scenes from the promotional video currently being created for Rishiri Island is being released. For more information, visit the Rishiri Island tourism portal site and the guide information page.' where id = 'PzLhBy40KHAE8bkV32ocO';
update content_bodies set title = 'そらふねの桟橋への車道は全面通行止め', description = 'そらふねの桟橋へ向かう車道は、2022年12月1日より森林作業のため全面通行止めとなっています。この通行止めは当面の間続く予定です。訪問を希望される方には、徒歩でのアクセス方法が動画「そらふねの桟橋への行き方～プチ登山編～」で紹介されています。また、田子山トレッキング駐車場は熊本県阿蘇市三久保387に位置しており、地図リンクも提供されています。' where id = 'MS3ZHvcUuvaL8Rwyv9OAJ';
update content_bodies set title = 'Road to Sorafune Pier Closed', description = 'The road leading to Sorafune Pier has been completely closed since December 1, 2022, due to forest work. Access is restricted for an indefinite period. For those wishing to visit, a walking access method is available, which is detailed in a video titled ''How to Get to Sorafune Pier - Mini Hiking Edition.'' Additionally, the Tagoyama Trekking Parking Lot is located at 387 Mikubo, Aso City, Kumamoto Prefecture, with a Google Maps link provided for directions.' where id = 'wlAyVm52k9zFfJ2jT_6jd';
update content_bodies set title = '利尻山 Mt.Rishiri 〜 小さな島の大きな世界がここにある～', description = '利尻島のPR動画の利尻山パートが完成し、一部が事前公開されました。また、佐々木陽子さんについての修正情報があります。彼女は以前「利尻島沓形ネイチャーガイドオフィス」に所属していましたが、令和6年度より「アイランズ トレック」としてガイドを行うことになりました。利尻島の観光ポータルサイトやガイド情報ページもご覧ください。' where id = 'NCM8DJGv_gdLz5Rq5cMo-';
update content_bodies set title = 'Mt. Rishiri - A Big World on a Small Island', description = 'The promotional video for Rishiri Island featuring Mt. Rishiri has been completed and is now partially available for preview. Additionally, there is an update regarding Yoko Sasaki, who was previously affiliated with the Rishiri Island Kutogata Nature Guide Office. Starting from the fiscal year 2024, she will be guiding under the name ''Islands Trek.'' For more information, you can visit the Rishiri Island tourism portal site and the guide information page.' where id = 'R-JchVjIoKpdnrcZDQ6SD';
update content_bodies set title = '北海道 利尻島・ガイド事業者 紹介', description = '利尻島は、日本の北のてっぺん稚内市から西へ約52kmの位置にあります。島は西側の「利尻町」と東側の「利尻富士町」の2つの町から成り、中央には利尻岳がそびえています。島の人々は海岸線に沿って生活し、春から夏にかけては多様な高山植物が咲き誇ります。また、全国的に有名な「利尻昆布」や「ウニ」などの海の幸に恵まれ、漁業と観光が盛んな島です。紹介されているガイド事業者には、利尻島ガイドセンター、利尻礼文ガイドネット、利尻自然ガイドサービス、利尻はなガイドクラブ、Island Time、利尻島沓形ネイチャーガイドオフィス、RISHIRI ACTIVITY、スペトラがあります。詳しくは「利尻島観光ポータルサイトりしぷら」をご覧ください。' where id = '0afGtIDLCyw9Bl8pctvZN';
update content_bodies set title = 'Introduction to Guide Operators on Rishiri Island, Hokkaido', description = 'Rishiri Island is located approximately 52 km west of Wakkanai City, at the northern tip of Japan. The island consists of two towns: Rishiricho on the west side and Rishirifuji Town on the east side, with the majestic Rishiri Mountain at its center. The local community thrives along the coastline, surrounded by diverse alpine flora that blooms from spring to summer. The island is renowned for its natural resources, including the famous Rishiri kelp and sea urchins, making it a hub for fishing and tourism. The guide operators listed include Rishiri Island Guide Center, Rishiri Rebun Guide Network, Rishiri Nature Guide Service, Rishiri Hana Guide Club, Island Time, Rishiri Kutsugata Nature Guide Office, RISHIRI ACTIVITY, and Spetra. For more details, visit the Rishiri Island tourism portal site.' where id = 'ow2FbEtonUBmOicNeVLwq';
update content_bodies set title = '利尻島ガイド事業者紹介：Island Time', description = 'Island Timeは、利尻島でのガイドサービスを提供する事業者で、黒川由希氏が運営しています。予約は、提供されたリンクから行えます。' where id = 'UqOi1S5kqvdqQDSZsgyLG';
update content_bodies set title = 'Introduction to Rishiri Island Guide Operator: Island Time', description = 'Island Time is a guide service on Rishiri Island, operated by Yuki Kurokawa. For reservations, please visit the provided link.' where id = 'HfgAhUyG_34W9IJ8lfrH5';
update content_bodies set title = '利尻島ガイド事業者紹介：スペトラ（スペース・トラベル）', description = 'スペトラ（スペース・トラベル）は、利尻島のガイド事業者で、佐々木慎吾氏が運営しています。利尻島の観光やアクティビティを楽しむためのガイドサービスを提供しており、予約は公式ウェブサイト（https://www.supetora.com/）から行えます。' where id = 'zgoITE8SAKBne343igrFR';
update content_bodies set title = 'Introduction of Rishiri Island Guide Operator: Supetora (Space Travel)', description = 'Supetora, also known as Space Travel, is a guide operator on Rishiri Island, led by Shingo Sasaki. For reservations, please visit their website at https://www.supetora.com/' where id = 'a8JVhchqIcuDc6-BQS_gb';
update content_bodies set title = '【利尻島ガイド事業者紹介】利尻島沓形ネイチャーガイドオフィス', description = '利尻島沓形ネイチャーガイドオフィスは、佐藤和久氏が運営しています。予約は、こちらのウェブサイト（http://www.kukiru.com/index.html）から行えます。' where id = 'dmFMb5SXpGQESvJBsT1_G';
update content_bodies set title = 'Introduction to Rishiri Island Guide Operators: Rishiri Island Kutugata Nature Guide Office', description = 'The Rishiri Island Kutugata Nature Guide Office is operated by Kazuhisa Sato. For reservations, please visit their website at http://www.kukiru.com/index.html.' where id = 'KxZKIKMKgjKSbvwVUiQaN';
update content_bodies set title = '利尻島ガイド事業者紹介：利尻礼文ガイドネット', description = '利尻礼文ガイドネットが紹介されており、山澤玉木氏が主要なガイドとして登場します。予約は、公式ウェブサイト https://www.rirenet.com/ から行えます。' where id = 'gHNKYSCsyH5kLGb3oN8eX';
update content_bodies set title = 'Introduction to Rishiri Island Guide Operators: Rishiri Rebun Guide Network', description = 'The Rishiri Rebun Guide Network is introduced, featuring Tamaki Yamasawa as a key guide. For reservations, please visit their website at https://www.rirenet.com/' where id = '10uCE087TEn4bnCbuoLOh';
update content_bodies set title = '利尻島ガイド事業者紹介：利尻･島ガイドセンター', description = '利尻･島ガイドセンターは西島徹氏が代表を務めています。予約は、こちらのウェブサイト https://www.rishiri-shimaguide.com/ から行えます。' where id = 'eLFXzObszTiRsfduYFtke';
update content_bodies set title = 'Introduction to Rishiri Island Guide Operators: Rishiri Island Guide Center', description = 'The Rishiri Island Guide Center is represented by Mr. Toru Nishijima. For reservations, please visit their website at https://www.rishiri-shimaguide.com/' where id = 'X7fStJ445goQP8W8_NIag';
update content_bodies set title = '地域PR　仙小CM完成版', description = '仙法志小学校の5・6年生が制作した地域のPR動画です。この動画は、地域の魅力や特長を伝えることを目的としており、子どもたちの視点から地域の良さを紹介しています。彼らの創造力や表現力が活かされており、地域の人々や訪れる人々にとって、興味深い内容となっています。' where id = 'Z6Z0igM2EVoHv-8Ctg27Z';
update content_bodies set title = 'Local PR: Completed CM from Senhoji Elementary School', description = 'This is a local PR video created by the 5th and 6th graders of Senhoji Elementary School.' where id = 'EVFaSB7CeGwteUa4TDSko';
update content_bodies set title = '【利尻島ガイド事業者紹介】利尻はなガイドクラブ', description = '利尻はなガイドクラブは、利尻島でのガイドサービスを提供する事業者です。代表者は平沢芳史氏と村岡すずか氏です。予約は、公式ウェブサイト https://www.rishiri-hanaguide.com/ から行えます。' where id = 'zueSA4G701HwdwD_Wtpmi';
update content_bodies set title = 'Introduction to Rishiri Island Guide Operators: Rishiri Hana Guide Club', description = 'Rishiri Hana Guide Club is introduced as a guide service on Rishiri Island. The club is represented by Yoshifumi Hirasawa and Suzuka Muraoka. For reservations, please visit their website at https://www.rishiri-hanaguide.com/' where id = 'DmzyLfqrMWcKJcjsAmh8C';
update content_bodies set title = '令和3年 阿蘇市の桜 その２', description = '令和3年に撮影された阿蘇市の桜を紹介する動画です。乙姫子安河原観音、極楽寺、明行寺の3つの場所が取り上げられており、3月31日に撮影されました。美しい桜が満開の様子を映し出し、各スポットの魅力を伝える内容となっています。' where id = 'JOJmPfG8F1jfq-LXDuoeU';
update content_bodies set title = 'Sakura in Aso City, 2021 - Part 2', description = 'This video showcases the cherry blossoms in Aso City, captured in 2021. It features various locations including Otokihime Koyasu River Kannon, Gokurakuji Temple, and Myokyoji Temple, all filmed on March 31. The video provides a visual tour of these beautiful sites, highlighting the stunning cherry blossoms in full bloom.' where id = 'ugO5bs9u_W0TaQq9mrnPh';
update content_bodies set title = '高菜の花が満開', description = '阿蘇市永草の国道57号沿いで、高菜が満開の花を咲かせています。美しい黄色い花をつけた高菜畑は、道行く人や昆虫たちに春の訪れを伝えているようです。3月20日には、ここで高菜の収穫と漬込みが体験できる''たかな祭り''が開催されました。高菜畑は、阿蘇市永草のうま牧場の向かいに位置しています。' where id = 'kyJl8sesRPFObhrjevfWA';
update content_bodies set title = 'Full Bloom of Takana Flowers', description = 'In Nagakusa, Aso City, along National Route 57, fields of takana (Japanese mustard spinach) are in full bloom, showcasing beautiful yellow flowers. This sight signals the arrival of spring to passersby and insects alike. On March 20, the area hosted the ''Takana Festival,'' where visitors could experience the harvesting and pickling of takana. The fields are located across from Uma Farm in Aso City.' where id = 'g_AD0jv37xZnxn2mhPFpB';
update content_bodies set title = '利尻で会いましょう。', description = 'この動画は、利尻島産のウニをPRするためのものです。利尻島の観光情報は「りしぷら」で確認できます。詳細は https://www.rishiri-plus.jp/ をご覧ください。また、ウニっこ図鑑の特設サイトも https://www.rishiri-plus.jp/unikko/ でご覧いただけます。' where id = 'qHaMWVBHMQtzxJkKNrK-e';
update content_bodies set title = 'Let''s meet in Rishiri', description = 'This is a promotional video for Rishiri Island''s sea urchin. For more information about tourism in Rishiri Island, please visit ''Rishipura'' at https://www.rishiri-plus.jp/. Additionally, you can explore the special site for the Uni-kko Encyclopedia at https://www.rishiri-plus.jp/unikko/.' where id = 'ZIrSOgjTL6Snd4h10Z69M';
update content_bodies set title = '春の赤目四十八滝参り　入山安全祈願法要', description = '三重県名張市に位置する赤目四十八滝にて、入山安全祈願法要が開催されます。この法要では、修験道者による護摩焚き行が行われ、千手滝での水行による身の清めや、火のついた薪の上を裸足で渡る火渡り行も行われます。自然豊かな環境の中で、日本の伝統的な精神文化を体験できる貴重な機会です。' where id = 'IW3-n3kL-rgMCREJOdsqN';
update content_bodies set title = 'Spring Safety Prayer Ceremony at Akame Shijuhachi Falls', description = 'A safety prayer ceremony will be held at Akame Shijuhachi Falls in Nabari City, Mie Prefecture. The event will include goma fire rituals performed by ascetic practitioners, a water purification ritual at Senju Falls, and a fire-walking ceremony where participants walk barefoot over burning wood. This event is a unique opportunity to experience traditional Japanese spiritual practices in a beautiful natural setting.' where id = 'MxY8L6zzjQJi4sSVyz9wW';
update content_bodies set title = '利尻観光商事', description = '利尻島にあるお店を紹介しています。利尻島の観光情報や体験について詳しく知りたい方は、ポータルサイト「りしぷら RISHIRI PLUS」をご覧ください。' where id = '8FnBBRW913PUqafD-Si_v';
update content_bodies set title = 'Rishiri Island (Hokkaido, Japan) Shop Introduction', description = 'This text introduces a shop located on Rishiri Island. For more details, visit the Rishiri Island Experience Tourism Information Portal ''RISHIRI PLUS'' at https://www.rishiri-plus.jp/' where id = '_n29S9jIbPCpM8GQLE0aZ';
update content_bodies set title = '利尻島ガイド事業者紹介', description = '利尻自然ガイドサービスは、渡辺敏哉氏が運営しています。利尻島の自然を楽しむためのガイドサービスを提供しており、予約はウェブサイト（http://www.maruzen.com/tic/guide/）から行えます。' where id = 'Nhpw0Nis2SgK0xj5YLicG';
update content_bodies set title = 'Introduction to Rishiri Island Guide Service', description = 'Rishiri Nature Guide Service is led by Toshiya Watanabe. For reservations, please visit http://www.maruzen.com/tic/guide/' where id = '-CqO4OviMGglXCnoTXPDS';
update content_bodies set title = '利尻島お店紹介', description = 'この文章では、北海道の利尻島にあるさまざまなお店を紹介しています。取り上げられている店舗には、利尻観光商事 高橋漁業部というお土産店や、利尻ふるさと食堂という飲食店、御崎物産という漁師のお店などがあります。また、まつや食堂や津田商店、畑宮食品などの飲食店やお土産店も含まれています。さらに、利尻 島の駅というお土産、カフェ、ギャラリーを兼ね備えたユニークな場所も紹介されています。詳細な情報は、利尻島の体験観光情報ポータルサイト「りしぷら RISHIRI PLUS」を訪れてください。' where id = 'H_XcZkD2URu0QFOuBDF0Y';
update content_bodies set title = 'Rishiri Island Shop Introduction', description = 'This text introduces various shops located on Rishiri Island, Hokkaido, Japan. The featured establishments include Takahashi Fisheries Department, a souvenir shop; Rishiri Furusato Shokudo, a dining establishment; Misaki Bussan, a fisherman''s shop; and several other shops and eateries such as Matsuya Shokudo, Tsuda Shoten, Hatakemiya Foods, and more. Additionally, there are unique places like the Rishiri Island Station, which offers souvenirs, a café, and a gallery. For more detailed information, visit the Rishiri Island experience tourism portal site ''RISHIRI PLUS''.' where id = 'Fn2efYFDVk6PVQJmdGNkj';
update content_bodies set title = '令和３年 仙酔峡の「ミヤマキリシマ」', description = '阿蘇市一の宮町宮地にある仙酔峡では、約５万本のミヤマキリシマが見頃を迎えています。ミヤマキリシマの見頃は、例年５月上旬から中旬にかけてとなっており、多くの観光客が訪れる阿蘇の美しい風景の一部を形成しています。仙酔峡は、阿蘇の観光スポットとしても知られ、自然の美しさを楽しむことができる場所です。' where id = 'l6nY8qzpu90kBqyELpo7b';
update content_bodies set title = 'Miyama Kirishima in Sensuikyo, 2021', description = 'In Sensuikyo, located in Ichinomiya Town, Aso City, approximately 50,000 Miyama Kirishima flowers are in full bloom. The best viewing period for these flowers is from early to mid-May.' where id = 'mMu12h3xk-P4sQYNvxAWX';
update content_bodies set title = '利尻島観光情報', description = 'この文章では、北海道利尻島の観光情報を紹介しています。利尻島の観光情報は「りしぷら」で確認できます。詳細は https://www.rishiri-plus.jp/ をご覧ください。' where id = 'Thx_3S4hwZYvSaiVDn6HR';
update content_bodies set title = 'Rishiri Island Tourism', description = 'This text provides tourism information about Rishiri Island, located in Hokkaido, Japan. For more details, please visit ''りしぷら'' at https://www.rishiri-plus.jp/.' where id = 'GzICklrOUDiS_fcEecwWf';
update content_bodies set title = '阿蘇の野の花 春から初夏', description = '阿蘇の草原には多様な野の花が自生しています。今回は、現在開花している野の花を紹介します。具体的には、ハナウド、レンリソウ、マイヅルソウの3種類です。これらの花々は春から初夏にかけて美しい景観を作り出し、訪れる人々に自然の魅力を伝えています。' where id = 'U4N1vmYRSG2giIxDcsXxW';
update content_bodies set title = 'Wildflowers of Aso: Spring to Early Summer', description = 'The grasslands of Aso are home to a variety of wildflowers. This time, we introduce the wildflowers that are currently in bloom, including Hanaundo, Renrisou, and Maizurusou.' where id = 'Lbef601Jwl_U2LMC0PF66';
update content_bodies set title = '利尻島 利尻 島の駅 海藻の里 利尻', description = 'この文章は、北海道利尻島の観光情報を提供しています。詳細については、リンク先の「りしぷら」をご覧ください。' where id = 'mnBU5ErpEjQAsz4L2Rpc-';
update content_bodies set title = 'Rishiri Island (Hokkaido, Japan) Tourism', description = 'This text provides tourism information about Rishiri Island, located in Hokkaido, Japan. For more details, please visit ''りしぷら'' at the provided link.' where id = 'Q4irXi59_VPLhWwaPdu4a';
update content_bodies set title = '利尻島 仙法志御崎公園 アザラシ餌やり', description = 'この文章は、北海道利尻島の観光情報を提供しています。利尻島の観光やアクティビティに関する詳細は、提供されたリンクの「りしぷら」をご覧ください。' where id = 'n5_EbyeRK3hJQPdH1rrTP';
update content_bodies set title = 'Rishiri Island: Senpohshi Misaki Park Seal Feeding', description = 'This text provides tourism information about Rishiri Island, located in Hokkaido, Japan. For more details on sightseeing and activities on Rishiri Island, please visit ''Rishiri Plus'' at the provided link.' where id = '7ZG8OlIGmlqFzz8VJdW5C';
update content_bodies set title = 'ウニのむき方', description = '利尻島のスタンダードな「ウニのむき方」を紹介します。ウニ殻割り器を使ったむき方は、神居海岸パークの「うにとり体験」で実際に挑戦できます。必要な道具は利尻漁業協同組合ストアーで購入可能です。殻付きウニを手に入れて、ぜひ試してみてください！利尻島の観光情報は「りしぷら」でご確認ください。' where id = 'RK1b0T8l9yfwYNyjvybU9';
update content_bodies set title = 'How to Open Sea Urchins', description = 'This guide introduces the standard method for opening sea urchins, specifically the Kitamurasaki variety. You can try using the sea urchin shell cutter at the ''Uni Gathering Experience'' at Kamui Coast Park. The necessary tools are available for purchase at the Rishiri Fisheries Cooperative Store. Get your hands on some whole sea urchins and give it a try! For more information on tourism in Rishiri Island, please visit ''Rishipura''.' where id = 'WaRcB54HuJf5wfK4dDfB4';
update content_bodies set title = 'ウニのむき方', description = '利尻島での「ウニのむき方」、特にエゾバフンウニの標準的な方法を紹介します。神居海岸パークでの「うにとり体験」では、ウニ殻割り器を使って実際に挑戦できます。必要な道具は利尻漁業協同組合ストアーで購入可能です。新鮮なウニを手に入れて、ぜひ試してみてください！利尻島の観光情報は「りしぷら」でご確認ください。' where id = 'mRpolaEmDXzEDafIw-2na';
update content_bodies set title = 'How to Cut Sea Urchin', description = 'This guide introduces the standard method for cutting sea urchin, specifically the Ezo Bafun Uni, as practiced on Rishiri Island. You can try using the sea urchin shell cutter at the Kamei Coast Park during the ''sea urchin gathering experience.'' The necessary tools are available for purchase at the Rishiri Fisheries Cooperative Store. Get your hands on some fresh sea urchins and give it a try! For more information on tourism in Rishiri Island, please visit ''Rishipura'' at https://www.rishiri-plus.jp/' where id = 'Rql8wgp5_64pdrFQTKstR';
update content_bodies set title = '利尻島 利尻町森林公園 トレッキング', description = 'この文章は、北海道利尻島の観光情報を提供しています。利尻島の詳細な観光情報は「りしぷら」で確認できます。ウェブサイトは https://www.rishiri-plus.jp/ です。' where id = '565YxJ5Rv9J21_sfvQ__W';
update content_bodies set title = 'Rishiri Island Tourism - Rishiri Town Forest Park Trekking', description = 'This text provides tourism information about Rishiri Island, located in Hokkaido, Japan. For more details, please visit ''りしぷら'' (Rishiri Plus) at https://www.rishiri-plus.jp/.' where id = 'sH5msbkR_Y078DmMj7Kv2';
update content_bodies set title = '加太春日神社', description = '加太春日神社の創建年代は不明だが、紀伊国造家の記録によれば、神武天皇の時代に天道根命が加太浦に上陸し、天照大御神を祀るために頓宮を造営したことが始まりとされる。漁業が盛んな地域であるため、後に航海安全と大漁を祈願する住吉神社が合祀された。社名は、日野左衛門藤原光福が春日三神を祀ったことに由来し、嘉吉2年の記録も残っている。社地は天正年間に現在地に移転され、慶長元年には社殿の造作が行われた。明治時代までは神職が不在で、宮座形式で運営されていたため、記録は乏しいが、神名帳に「正一位春日大神」と記されており、神格の高さが示されている。毎年4月には聖護院門跡が参拝し、昭和56年には環境庁主催の自然公園大会で採火神社に指定された。現在の社名は、戦後に宗教法人として再編された際に用いられたものである。' where id = 'cY5X-QCxalV4MqpOf9DhN';
update content_bodies set title = 'Kada Kasuga Shrine', description = 'The exact founding date of Kada Kasuga Shrine is unclear, but according to the ancient records of the Kii Province, it began when the deity Tendo-no-kami landed at Kadaura during the reign of Emperor Jimmu and built a temporary shrine to enshrine Amaterasu. The area, known for its fishing industry, later incorporated the Sumiyoshi Shrine to pray for safe voyages and abundant catches. Historical documents indicate that the shrine was named ''Kasuga Shrine'' during the Kagan era (1303-1317) by Hino Saemon Fujiwara Mitsukatsu, who enshrined the Kasuga deities. The shrine was relocated to its current site during the Tensho era (1573-1592) by a retainer of Hashiba Hide-naga. Until the Meiji period, the shrine was managed by a community-based system without priests, leading to a lack of records. However, its significance is noted in the Kii Province''s deity register, and it is recognized as a sacred site where Yamabushi monks continue to visit annually. In 1981, it was designated as a fire-gathering shrine during a national park event.' where id = 'WX0aA4YCkuJ_LTkhUyO2y';
update content_bodies set title = '法然上人二十五霊場　報恩講寺', description = 'この動画では、法然上人に関連する二十五霊場の一つである報恩講寺について紹介しています。' where id = 'hf7UMKGv3vLAqlLJ3iDws';
update content_bodies set title = 'Honen Shonin''s Twenty-Five Sacred Sites: Ho''onko-ji Temple', description = 'This video introduces Ho''onko-ji Temple, one of the twenty-five sacred sites associated with Honen Shonin.' where id = '9zJ0HntfzUjfWb2ZFmpsW';
update content_bodies set title = '大川八幡神社', description = '大川八幡神社は和歌山県に位置し、応神天皇、仲哀天皇、神功皇后の三神を祀っています。創立年代は不詳ですが、『紀伊続風土記』によると、元々は現在地の西にあった住吉神社に鎮座しており、寛永年間に村民と共に現在地に移されたとされています。社殿は壮麗で、4基の高さ4mの石灯籠や、江戸中期の重要な廻船基地としての面影を残す5.5mの菱垣廻船の模型が保存されています。祭りの際にはこの船が飾られ、村の若者たちが練り歩いたと伝えられていますが、現在は過疎化が進み、模型は絵馬殿に保存されています。また、境内社の住吉神社は1885年に現在地に遷座され、華麗な社殿が残っています。鳴神神社は1922年に改築され、地域住民の信仰心が強まったとされています。' where id = '93FOBZ02n03aiBsfJAhHo';
update content_bodies set title = 'Okawa Hachiman Shrine', description = 'The Okawa Hachiman Shrine, located in Wakayama Prefecture, is dedicated to three deities: Emperor Ojin, Emperor Chūai, and Empress Jingu. Although the exact founding date is unknown, historical records indicate that it was originally situated west of its current location at the Sumiyoshi Shrine. During the Kan''ei era (1624-1644), it was relocated to its present site with the help of local villagers. The shrine is noted for its grandeur, evidenced by four large stone lanterns and a preserved model of a Hishigaki ship, indicating its historical significance as a vital shipping base during the Edo period. The model was traditionally decorated during festivals, but due to depopulation, it remains stored. The Sumiyoshi Shrine, originally part of the Okawa Hachiman Shrine, was moved in 1885 and retains some of its former splendor. Additionally, the Narukami Shrine, established in 1922, arose from local concerns about strange sounds from a nearby house, leading to a renewed commitment to faith among the villagers.' where id = '2_wC3MZzWuNm6N3SUhhcc';
update content_bodies set title = '千年の草原', description = '九州熊本県阿蘇地方に位置するこの独特な地域は、27万年前からの度重なる大噴火によって形成されたカルデラで、約5万人が暮らしています。カルデラの中央には、今も噴煙を上げる活火山の阿蘇山がそびえ、その周辺には日本最大の草原地帯が広がっています。この唯一無二の空間は、国立公園、ユネスコ世界ジオパーク、世界農業遺産にも認定されています。' where id = 'cPBQkCk5ZQL-RDdFMRjpR';
update content_bodies set title = 'Thousand-Year Grassland', description = 'Located in the Aso region of Kumamoto Prefecture, Kyushu, this unique area has been shaped by repeated massive eruptions over the past 270,000 years, resulting in a caldera that houses around 50,000 residents. At the center of the caldera stands Mount Aso, an active volcano that continues to emit smoke. Surrounding it is Japan''s largest grassland area. This exceptional space has been recognized as a national park, a UNESCO Global Geopark, and a World Agricultural Heritage site.' where id = '-KMIMHkE2jQ-nPdh3nzjs';
update content_bodies set title = '葛城修行一行', description = '友ケ島は、修験道の代表的な聖地であり、修験道は日本古来の山岳信仰と仏教が融合した独特の宗教です。山伏と呼ばれる修行者たちは、霊山で厳しい修行を行い、超自然的な能力を身につけます。友ケ島から和泉葛城山、金剛山、二上山に至る尾根には、修験道の開祖・役行者が法華経を納めた28か所の経塚が存在し、これを葛城修験二十八宿と呼びます。友ケ島の虎島には第一番経塚があり、葛城修験の修行の重要な拠点となっています。修験道は当山派と本山派の二派に分かれ、本山派では春の葛城修行が重要な行事とされ、友ケ島で厳しい修行が行われます。' where id = 'kh5n15x5VMW629UYxaG7p';
update content_bodies set title = 'Katsuragi Shugyo Group', description = 'Tomogashima is a representative sacred site of Shugendo, a unique Japanese religion that combines ancient mountain worship and Buddhism, particularly esoteric practices. Practitioners known as Yamabushi engage in rigorous training in remote mountains to acquire supernatural abilities, with Tomogashima serving as one of these training grounds. Along the ridges from Tomogashima to the Izumi Katsuragi Mountains, there are 28 sites called ''Kyozuka'' where En no Gyoja, the founder of Shugendo, is said to have deposited the Lotus Sutra. These sites are collectively known as Katsuragi Shugendo''s 28 lodges, marking them as significant training locations. One of the islands, Torajima, houses the first Kyozuka, making it a crucial starting point for Katsuragi Shugendo training. Shugendo is divided into two main factions: the Tozan and the Honzan. The Honzan faction, based in Kyoto''s Shogo-in, considers the spring Katsuragi training and the summer Ominesan training as vital events, during which practitioners travel to Tomogashima for rigorous training.' where id = 'zMrAqBvt0EdV7yfgXmnZt';
update content_bodies set title = '加太ビーチ', description = '加太ビーチは、水がキレイで穏やかなビーチです。美味しい魚や温泉も楽しめます。また、夕日も非常に美しいです。' where id = 'jr7flw7KUvr9Q5Rjxxmja';
update content_bodies set title = 'Kada Beach', description = 'Kada Beach is known for its clear and calm waters. Visitors can enjoy delicious fish and hot springs in the area. The sunset views are also beautiful.' where id = '1ur_Mkvhx1-fbB7Y0gVeY';
update content_bodies set title = '【山上の絶景】ミヤマキリシマ - 阿蘇の春の花2022 -', description = '令和4年5月18日に撮影された烏帽子岳の登山道と5月17日に撮影された仙酔峡の様子が紹介されています。阿蘇の大自然の中で一斉に咲き誇るミヤマキリシマの美しさは圧巻で、訪れる人々に感動を与えます。今週末にはこの風景を楽しむことができるため、まだ予定がない方はぜひ足を運んでみてください。' where id = 'RT17XuRRH3ec5V3ag8SxW';
update content_bodies set title = 'Stunning Views from the Mountain: Miyama Kirishima - Spring Flowers in Aso 2022 -', description = 'This text describes the breathtaking scenery of the Miyama Kirishima flowers blooming in the Aso region, captured on May 18, 2022, along the Eboshidake hiking trail, and the Senzuikyo area photographed on May 17. The vibrant display of these flowers amidst the vast natural beauty of Aso is truly impressive. Visitors are encouraged to enjoy this stunning landscape over the upcoming weekend, especially those who have not yet made plans.' where id = 'DBWEpIcnJ9rJElCC0zBHJ';
update content_bodies set title = '一本釣りサワラの調理', description = '春を告げる魚の代表である鰆は、上品な味わいが特徴で、旅館の料理にもよく使われます。加太では、このサワラを一本釣りで漁獲しています。サワラの身は柔らかく、傷みやすいため、一本釣りのサワラは特に価値があります。加太観光協会青年部長の稲野雅則氏（活き魚料理いなさ）の美技をぜひご覧ください。' where id = 'D5bwDRCrop3MF8aB-AN2b';
update content_bodies set title = 'Cooking Wild-Caught Spanish Mackerel', description = 'Spanish mackerel, a representative fish that heralds spring, is known for its refined flavor and is often used in ryokan cuisine. In Kada, this fish is caught using the pole-and-line method. Due to its tender flesh, which is prone to spoilage, wild-caught Spanish mackerel is particularly valuable. Witness the culinary skills of Masanori Inano, the head of the Kada Tourism Association''s Youth Division, at his restaurant, Ikigai Ryori Inasa.' where id = 'Ek5JwH9F8Q5FCVyUC-__k';
update content_bodies set title = 'たこつぼ漁', description = '和歌山加太のタコツボ漁についての紹介です。日本の消費の半分が外国産である中、本物の味を絶やさぬよう努力しています。ぜひ加太で鮮度の良いタコを味わってください。' where id = '7q436qDCYobOApXVeTVIW';
update content_bodies set title = 'Tako Tsubo Fishing', description = 'This is Tako Tsubo fishing in Kada, Wakayama. Despite half of Japan''s consumption being sourced from abroad, we strive to maintain the authentic taste. Be sure to enjoy fresh octopus in Kada!' where id = 'bFTVCxvxA_xxrliY3jl7D';
update content_bodies set title = '真鯛一本釣漁', description = '和歌山加太名物の真鯛の一本釣り漁は、小型漁船で潮の速い紀淡海峡に出て、糸と針を使って鯛と勝負します。網で群れごと獲るのではなく、一匹一匹を漁師の技術と海の成果で捕まえるため、漁の過程が重要です。もちろん、味も抜群で、加太に訪れれば手頃な価格で新鮮な活き魚を楽しむことができます。活き魚の販売も行っています。' where id = 'KU7C4hhidNd8fE91zv7AN';
update content_bodies set title = 'Single Hook Fishing for Sea Bream', description = 'In Kada, Wakayama, the local specialty is single hook fishing for sea bream. Fishermen venture into the fast currents of the Kitan Strait using small boats, competing with the fish using line and hook. Unlike net fishing, this method emphasizes the skill of the fisherman and the bounty of the sea, as each fish is caught individually. The taste is exceptional, and visitors to Kada can enjoy the freshest live fish at reasonable prices. Live fish sales are also available.' where id = '-PyIs8FD42cASuVghBkT6';
update content_bodies set title = '活きタコの調理', description = '日本で消費されるタコの半分は輸入品であり、その多くはモロッコやモーリタニアなどのアフリカから来ています。輸入品は2万キロ以上の距離を移動しているのに対し、加太のタコは調理の直前まで生きており、鮮度が抜群です。活きタコをより美味しく食べるために、加太観光協会青年部長の稲野雅則氏（活き魚料理いなさ）が、活きタコの調理方法について教えてくれました。' where id = 'YEr1R5VrUm4BmUi-_6SAv';
update content_bodies set title = 'Cooking Live Octopus', description = 'In Japan, half of the octopus consumed is imported, primarily from African countries like Morocco and Mauritania. While these imports have traveled over 20,000 kilometers, the octopus from Kada is fresh and alive just moments before preparation. To enhance the taste of live octopus, Masanori Inano, the head of the Kada Tourism Association''s Youth Division and owner of Ikigai Cuisine Inasa, shares his insights on how to properly cook live octopus.' where id = 'xzaT8VOMO9rwOXnJ5tCMO';
update content_bodies set title = '加太活き魚市場', description = '漁師が一本釣りで獲った活き魚は、加太の蓄養施設に運ばれ、各地に流通します。加太産の魚は一本釣りで捕られているため、阪神地域では高値で取引されています。都会では高額ですが、加太で食べるとお手頃価格です。魚の本当の美味しさを確かめに来ませんか？一般の方にも販売するイベントもありますので、お問い合わせください。' where id = '9Hg25BYE2_0-RqlWxu9Xn';
update content_bodies set title = 'Kada Live Fish Market', description = 'The live fish caught by fishermen using pole-and-line methods are transported to the Kada aquaculture facility and distributed to various regions. Due to their origin from Kada and the method of capture, these fish are traded at high prices in the Hanshin area. While they are expensive in urban areas, they are reasonably priced in Kada. Why not come and experience the true taste of fish? There are also events where the fish are sold to the general public, so please inquire for more information.' where id = '6B0dHXShSIXgqQJRZVpbb';
update content_bodies set title = '和歌山加太のサンセット', description = '美しい和歌山加太の夕日が広がります。目の前には友ヶ島が浮かび、その奥には淡路島が見えます。雲と島のシルエットが幻想的な美しさを演出しています。また、観光協会では不定期にサンセットクルージングを企画しているため、興味のある方はぜひお問い合わせください。' where id = 'iiE6s8fQOlUXSUAJtrHQ7';
update content_bodies set title = 'Sunset in Kada, Wakayama', description = 'This is a beautiful sunset in Kada, Wakayama. In the foreground, you can see the islands of Tomogashima, with Awaji Island in the background. The silhouettes of the clouds and islands create a fantastical beauty. The local tourism association occasionally organizes sunset cruises, so please feel free to inquire for more information.' where id = '5_Pzjnn9cp2gwp_F7gCru';
update content_bodies set title = '令和３年 波野高原の「スズラン」', description = '毎年5月中旬、阿蘇市波野地区ではスズランの花が見頃を迎えます。今年も波野のスズラン自生地には、スズラン特有の甘い香りが漂い、可憐な白い花を探して野原を散策する人々で賑わいました。自然の中で楽しむスズランの美しさは、多くの人々に愛されています。' where id = 'VxESp74oM5HfCyNXbxpxL';
update content_bodies set title = 'Lily of the Valley in the Wave Field of 2021', description = 'In mid-May, the Lily of the Valley flowers reach their peak in the Wave area of Aso City. This year, the natural habitat of the lilies was filled with their characteristic sweet fragrance, attracting many visitors who strolled through the fields in search of the delicate white flowers.' where id = '4gNqf5weUUUC-nczpbyOE';
update content_bodies set title = '【大自然4K】「春の草原」高画質 癒し映像', description = '『SCENE of the ASO』シリーズの一環として、自然豊かな阿蘇の風景を4Kカメラで撮影した映像です。第8巻では、阿蘇の「春の草原」をテーマに、野焼き後の真っ黒な草原から新しい野草が芽吹き、徐々に緑に変わっていく様子を捉えています。撮影場所は、町古閑牧野（許可を得て撮影）、烏帽子岳、杵島岳、大観峰、キスミレ、米塚などです。' where id = '2_-j1GlFG7knfcbw-u76J';
update content_bodies set title = 'Nature in 4K: ''Spring Grassland'' High-Quality Healing Video', description = 'This video is part of the ''SCENE of the ASO'' series, showcasing the rich natural landscapes of Aso, captured in 4K. Volume 8 features the ''Spring Grassland'' of Aso, depicting the transformation of the blackened grassland after a controlled burn as new wild grasses begin to sprout, gradually turning green. The filming locations include Machikoga Pasture (with permission), Eboshidake, Kineshima Dake, Daikanbo, Kissumire, and Kometsuka.' where id = '9jFWpyHCf2H3NuNUN5EZT';
update content_bodies set title = '伝統漁法CM', description = '加太観光協会が紹介するのは、和歌山県最西端、淡路島の東側に位置する「おさかなリゾート」です。この地域は一本釣りの鯛や淡嶋神社、温泉、釣り、夏の海水浴が有名です。最近では、目の前にある友ヶ島が注目を集めています。関西国際空港から車で50分、大阪からのアクセスも良好で、南海加太線の加太駅からも訪れることができます。' where id = 'zY17HpMpl-3IH6SKnOY-C';
update content_bodies set title = 'Traditional Fishing Method CM', description = 'Kada Tourism Association presents a unique fishing resort located on the eastern side of Awaji Island, at the westernmost point of Wakayama Prefecture. The area is famous for its single-line caught sea bream, the Awashima Shrine, hot springs, fishing, and summer beach activities. Recently, the nearby Tomogashima Islands have gained attention. The resort is conveniently located just 50 minutes by car from Kansai International Airport and is easily accessible from Osaka. Visitors can also reach the area by taking the Nankai Kada Line to Kada Station.' where id = 'M4Ew4FexJW9-GaQbiqG-G';
update content_bodies set title = '兵庫県加東市の神結酒造', description = 'この動画では、兵庫県加東市にある神結酒造について紹介しています。' where id = 'Lwv0O-xAhD2fIgpr8Hc49';
update content_bodies set title = 'Kamyuu Sake Brewery in Kato City, Hyogo Prefecture', description = 'This video introduces Kamyuu Sake Brewery located in Kato City, Hyogo Prefecture.' where id = 'ZQQ1TZYajpOS-S3qS06y0';
update content_bodies set title = '【兵庫県】日帰り天然温泉　滝野温泉ぽかぽ【加東市】', description = 'この動画では、兵庫県加東市に位置する日帰り天然温泉、滝野温泉ぽかぽについて紹介しています。温泉の特徴や魅力を伝え、訪れる価値があることを示しています。' where id = '3Tk7rUNt2jeWWcYTWOEBj';
update content_bodies set title = 'Takinoyu Onsen Poka-Po in Hyogo Prefecture', description = 'This video introduces Takinoyu Onsen Poka-Po, a day-use natural hot spring located in Kato City, Hyogo Prefecture.' where id = 'g2dIT4HV6D8yc6zBk5dFJ';
update content_bodies set title = '【兵庫県】加古川　名勝　闘竜灘', description = '清流加古川の川底には奇岩や怪岩が点在し、豪快な水の流れと四季折々の水模様が魅力を放っています。また、竜の躍動に似た飛び鮎の名所としても知られています。毎年5月1日には鮎漁が解禁され、多くの人々が訪れます。' where id = 'ZfI-lqW4xb4gL7nWj-fM7';
update content_bodies set title = 'Kakogawa, Hyogo Prefecture - Scenic Spot: Tōryū-nada', description = 'The Kakogawa River features a riverbed filled with strange and unique rocks, creating a captivating landscape with the powerful rhythm of cascading water and the changing patterns of water throughout the seasons. It is also famous as a prime location for flying sweetfish, named for its resemblance to a dragon''s movement. The sweetfish fishing season opens every year on May 1st.' where id = 'W4e5ildDmM2QPaeC5jbM2';
update content_bodies set title = '【兵庫県】鹿野山　朝光寺【加東市】', description = '清閑にたたずむ国宝朝光寺は、法道仙人によって孝徳天皇白雉二年（西紀651）頃に開基されたと伝えられています。本尊は十一面千手観世音菩薩であり、昭和29年に国宝に指定されました。朝光寺は高野山真言宗に属しています。' where id = 'OHzLFqmWzyItO_vB9sK-m';
update content_bodies set title = 'Shokoji Temple, Kanno Mountain, Hyogo Prefecture', description = 'Shokoji Temple, a national treasure, stands in serene surroundings. It is said to have been founded by the hermit Hodō around the second year of the Hakuchi era (651 AD) during the reign of Emperor Kōtoku. The main deity enshrined here is the Eleven-faced Kannon (Avalokiteshvara). The temple was designated as a national treasure in 1954 and belongs to the Shingon sect of Mount Kōya.' where id = 'lRqK_OTI2GftLXCip0B9g';
update content_bodies set title = '和歌山加太・天然鯛一本釣り漁法ロングバージョン', description = '一本釣りは、針にえさや擬似餌を付けて一匹の魚を釣る漁法で、網で群れを捕るのではなく、元気な魚と漁師の一対一の勝負です。魚が元気であることが美味しさの理由の一つで、活きの良さは網獲りの魚とは異なります。また、紀淡海峡の速い潮がたくましい魚を育てます。活きたまま大阪などの料亭に運ばれ、グルメの食膳にのぼります。加太の漁師たちは、効率は悪いものの江戸時代から続く伝統漁法を守っています。ぜひ産地で美味しい魚を味わってください。' where id = 'mtouRyLnx0gIUeSehsrXR';
update content_bodies set title = 'Wakayama Kada: Long Version of Natural Sea Bream Fishing Method', description = 'The one-by-one fishing method involves using a hook with bait or a lure to catch a single fish. Unlike net fishing, this method creates a one-on-one challenge between the fisherman and a lively fish. One reason for the deliciousness of the fish is its vitality; the fish actively bites the bait, which is different from net-caught fish. Additionally, the swift currents of the Kitan Strait contribute to the robust growth of the fish, similar to the famous ''Kansaba.'' The live fish are transported to restaurants in Osaka, ensuring freshness for gourmet dining. The fishermen of Kada adhere to this traditional fishing method, which has been passed down since the Edo period, despite its inefficiency. Visitors are encouraged to taste the delicious fish at the source.' where id = 'xsxWhyaPVqR59FFN-rdN_';
update content_bodies set title = 'ぼのぼのと暮らす町', description = 'この動画は、世界的に人気の漫画「ぼのぼの」の作者いがらしみきおさんの故郷である加美町を紹介するものです。加美町には、ぼのぼのに登場しそうな場所がたくさんあり、キャラクターと気軽に触れ合える施設も多く存在します。これらの魅力を知ってもらうための動画を制作しました。' where id = 'k_YTibQw3R3J4vwSi1gRW';
update content_bodies set title = 'Living in the Town of Bonobono', description = 'This video promotes the hometown of Mikio Igarashi, the creator of the globally popular manga ''Bonobono.'' In Kamimachi, there are many places that seem to have come straight out of the manga, as well as numerous facilities where visitors can easily interact with the characters. The video aims to showcase these attractions.' where id = 'zD9gO67EY-r2dJls2ZxF5';
update content_bodies set title = '1分でわかる加美町の魅力！', description = 'この動画では、加美町の魅力を紹介していますが、あえて「薬莱山」を内容から外しています。' where id = 'lcWS97glYFXAgwyoKRTa6';
update content_bodies set title = 'Discover the Charm of Kamimachi in One Minute!', description = 'This video highlights the attractions of Kamimachi, intentionally excluding ''Yakurai Mountain'' from the content.' where id = 'xcoYjF4oKT9qAQo7JNmY2';
update content_bodies set title = '15伝統・文化を次世代へ', description = 'この動画は、広大な自然から生まれる食文化や衰退している伝統・文化を次世代に継承していく重要性を伝えることを目的としています。その思いを込めて制作されました。加美町は「薬莱山」で知られ、県民なら誰もが耳にしたことのある有名な観光名所です。' where id = 'n4ovumBdm3I73YyedRZRf';
update content_bodies set title = 'Passing Down Traditions and Culture to the Next Generation', description = 'This video aims to convey the importance of preserving the rich food culture that arises from vast natural landscapes, as well as the declining traditions and customs, to future generations. The video was created with this intention in mind. Kamimachi is known for ''Yakurai Mountain,'' a famous tourist spot that every resident of the prefecture has likely heard of.' where id = 'lkOSreM0e2xE7P-UhXzer';
update content_bodies set title = '14美味しい加美町', description = 'この動画では、加美町で楽しめるグルメを全面的に紹介しています。地元の美味しい料理をアピールしています。' where id = '4ETfWuVks5R5B4a7qD5xU';
update content_bodies set title = '14 Delicious Foods in Kamimachi', description = 'This video highlights the gourmet foods available in Kamimachi, showcasing the local culinary delights.' where id = 'UevtMnGDMdaFwJy60Zl7j';
update content_bodies set title = '11加美冬', description = '加美町の冬を30秒の動画で紹介しています。加美町では冬でも楽しめるイベントやアクティビティが豊富にあります。動画を見た方が興味を持っていただければ嬉しいです。' where id = '2DZg_9py-NzeE1XhlCdxo';
update content_bodies set title = '11 Kami Winter', description = 'This 30-second video showcases winter in Kami Town. The town offers various events and activities that can be enjoyed even during the winter season. We hope that viewers will find it interesting.' where id = 'Dwod9nioxSvnrKQOZvIQi';
update content_bodies set title = '08加美町のお酒とお肉でしゃぶしゃぶ作ってみた！', description = 'この動画では、加美町の地酒「天上夢幻」を贅沢にしゃぶしゃぶのつゆに使用し、ブランドポーク「おだしまポーク」でしゃぶしゃぶを作りました。お酒の旨みが引き出されたつゆに柔らかいお肉をくぐらせることで、旨さが倍増し、美味しさに思わず笑みがこぼれます。ぜひお試しください！' where id = 'NLBUxUDhl360f5TxU91Hg';
update content_bodies set title = 'Shabu-Shabu with Sake and Meat from Kamimachi!', description = 'In this video, we used Kamimachi''s local sake ''Tenjo Mugen'' as a luxurious shabu-shabu broth and paired it with the brand pork ''Odashima Pork''. Dipping the tender meat into the flavorful broth enhances the taste, making it even more delicious! It''s sure to bring a smile to your face. Give it a try!' where id = 'hoPPBimwFW2WvrLwscG2j';
update content_bodies set title = '07加美町のひととき', description = 'この1分間の動画は、加美町の魅力を凝縮し、住民が自分の町の良さを再認識できるように作られています。また、訪れる人々には加美町への憧れや、訪れて良かった、また来たいという幸せな気持ちを感じてもらうことを目的としています。' where id = '6sIO6EcJ34POqvbg_VUlU';
update content_bodies set title = 'Moments in Kamimachi', description = 'This one-minute video encapsulates the essence of Kamimachi, aiming to help both residents and visitors appreciate the town''s charm. It seeks to evoke feelings of admiration and happiness, making residents rediscover the allure of their hometown while inspiring visitors to feel a sense of longing and satisfaction, encouraging them to return.' where id = 'Nyo3kMgLySFhD5W4GqFVy';
update content_bodies set title = '【兵庫県】やしろ鴨川の郷【加東市】', description = 'やしろ鴨川の郷は、加東神山の麓に位置する宿泊施設です。雄大な山々と静かな風に囲まれ、四季折々の自然の美しさを楽しむことができます。春には桜、夏にはブルーベリー狩り、秋には色鮮やかな紅葉、冬には一面の銀世界が広がります。また、広大な敷地内にはグラウンドゴルフ場やテニスコートがあり、さまざまなアクティビティを楽しむことができます。美しい自然の中で、ゆったりとしたひとときを過ごせる場所です。' where id = 'T_3W3xqH0l43MJ68pZsw3';
update content_bodies set title = 'Yashiro Kamogawa no Sato, Hyogo Prefecture', description = 'Yashiro Kamogawa no Sato is a lodging facility located at the foot of Mount Kato in Kato City. Surrounded by majestic mountains and tranquil winds, the area changes its appearance with the seasons. In spring, visitors can enjoy cherry blossoms; in summer, blueberry picking; in autumn, vibrant foliage; and in winter, a world covered in snow. The expansive grounds feature a ground golf course and tennis courts, offering various activities for guests. Experience a relaxing time in the beautiful natural surroundings.' where id = '2vrclexbbATe8hDl3GLr6';
update content_bodies set title = 'あさりんのワッフルは最高です！', description = 'この動画では、幼少期から高校まで中新田（加美町）で過ごし、現在は東京で「えんそく」というバンドで音楽活動をしている私が、今でも帰る度に楽しむ「あさりんのワッフル」を紹介しています。このワッフルは何十年も続く味で、私にとって特別な存在です。東京に住んでいても、この味を広めたいという思いが強く、全ての方にこのワッフルをぜひ味わってほしいと願っています。' where id = 'n8AbNIBYGmBMxnKgRmnTR';
update content_bodies set title = 'Asarin''s Waffles are the Best!', description = 'The video promotes Asarin''s Waffles, a beloved treat that the speaker has enjoyed since childhood in Nakaniida, Kamimachi, and continues to savor even after moving to Tokyo. The speaker is currently active in a band called ''Ensoku,'' with a concert scheduled at Nakano Sunplaza in Tokyo on March 29. Despite living in the city, the speaker''s fondness for Asarin''s Waffles remains strong, and they express a desire to share this long-standing taste with everyone. The message emphasizes the importance of this waffle and encourages others to try it.' where id = 'gc3tJhVkeZ6wqfoI0nQnT';
update content_bodies set title = '加美町の自然　春から夏', description = 'このスライドビデオは、加美町西部の自然を春夏の季節にわたって足早に紹介しています。' where id = 'JWB7nmSSMrQqTtNlHanfs';
update content_bodies set title = 'Nature of Kamimachi: Spring to Summer', description = 'This slide video quickly introduces the natural scenery of the western part of Kamimachi during the spring and summer seasons.' where id = 'OLvzQ9z1gt0gPt9-JLX0O';
update content_bodies set title = 'ストレスフリーな遊び場', description = 'この動画は、天候に左右されない加美町の多くの施設を紹介しています。これにより、遊びの計画がストレスフリーになり、てるてる坊主に頼る必要がなくなります。加美町の魅力を伝えるCMとなっています。' where id = 'AC-tCxFyfhQnTh2jqLRAA';
update content_bodies set title = 'Stress-Free Playgrounds', description = 'The promotional video highlights the advantages of having numerous facilities in Kamimachi that are not affected by weather conditions. This allows for stress-free planning of activities, eliminating the need to rely on good weather or traditional methods like teru teru bozu (a Japanese doll used to wish for good weather).' where id = 'vc6i8D1kdpslc9yRJX6K7';
update content_bodies set title = 'ワクワク足りてる？', description = '豊かな自然が魅力の加美町の中で、特に「荒沢湿原」が代表的なスポットです。冬の積雪量が想像を超えるため、子供だけでなく大人も楽しめる場所として、私の一番のオススメです。この魅力あふれる場所を多くの方に体験していただきたく、今回動画を作成しました。' where id = 'fnLaZ_vLds4t4xKyrvI1j';
update content_bodies set title = 'Are You Excited Enough?', description = 'This video promotes the beautiful natural scenery of Kamimachi, particularly highlighting the renowned Arasawa Wetland. The area is especially known for its extraordinary snowfall during winter, making it a fun spot not just for children but also for adults. It is my top recommendation for anyone looking to enjoy the winter landscape. We created this video to encourage more people to experience this captivating location.' where id = 'RpFHMcphIb9MmmAqXSeHe';
update content_bodies set title = '感じてみよう、加美町。', description = 'この動画PRは、加美町をあまり知らない女性が訪れ、1日を過ごす中で加美町の魅力に気づくストーリーを描いています。加美町を単に映し出すのではなく、映像にストーリー性を持たせることで、その魅力をより伝えられると考えました。また、自然景観、食、多様なアクティビティ、伝統文化の4つの観光資源・テーマを1分という短い時間で感じられる映像に仕上げています。' where id = 'Bgep-2hpG282H4X2_Eu1_';
update content_bodies set title = 'Experience the Charm of Kamimachi', description = 'This video PR features a story about a woman who, unfamiliar with Kamimachi, visits the town and gradually discovers its charm throughout her day. The aim is to convey the appeal of Kamimachi not just by showcasing the town, but by incorporating a narrative into the visuals. The video highlights four key tourism resources and themes—natural scenery, food, diverse activities, and traditional culture—within a concise one-minute format.' where id = 'B5CMcbKRLaEwtPDYJo2_M';
update content_bodies set title = 'はじめてのかみたび', description = 'この動画は、初めて加美町を訪れた家族の様子を収めています。PR動画特有の押し付けがましさがなく、家族が純粋に加美町を楽しんでいる姿を映し出しています。撮影は丸一日行われ、家族の素直な感情が表現されています。加美町が「家族とゆったりと過ごせる」「気張らずにフラっと立ち寄れる」場所であることを伝えられれば幸いです。また、動画にはオリジナル楽曲「life line」が使用されており、アーティストのunnunも映像に登場しています。' where id = 'KNZc1xO4pKty788kCayvD';
update content_bodies set title = 'First Trip to Kamitabi', description = 'This video features a family visiting Kamitabi for the first time. Unlike typical promotional videos, it captures the family''s genuine enjoyment of the town without being pushy. The footage was taken over a full day, showcasing their honest emotions as they explore the area. The aim is to highlight Kamitabi as a place where families can relax and enjoy their time together without the pressure of a typical tourist experience. The video features an original song titled ''life line'' by unnun, with the artist appearing in the footage.' where id = 'Y0fiix3QXJS7JLFBpYeXG';
update content_bodies set title = '宮城・山形「絆」tour de 347 2022', description = '宮城・山形「絆」tour de 347 2022の動画です。このイベントは、宮城と山形の県境を跨いだ地域間交流を目的とし、国道347号沿いの豊かな自然を体験できるサイクルイベントです。第4回目となる今大会では、宮城県加美町から山形県尾花沢市、大石田町を結ぶ全長約120kmの峠越ルートが実現しました。緑に囲まれた347号線は、上級者も楽しめる難易度と自然を満喫できるコースです。初心者向けのショートコースも用意されており、加美町内を折り返します。各地のエイドステーションでは、特産品や名物が提供されました。' where id = 'bGGrlM7fgHrdMD-3rf0Qp';
update content_bodies set title = 'Miyagi-Yamagata ''Kizuna'' Tour de 347 2022', description = 'This video showcases the Miyagi-Yamagata ''Kizuna'' Tour de 347 2022 event. The event aims to promote regional exchange across the border of Miyagi and Yamagata, featuring a cycling route along National Route 347 that allows participants to experience the rich nature of the area. In its fourth edition, the event successfully established a challenging 120 km mountain route connecting Kamimachi in Miyagi Prefecture with Obanazawa City and Oishida Town in Yamagata Prefecture. The course along Route 347, surrounded by greenery, offers a level of difficulty that can be enjoyed by advanced cyclists, while a shorter course is available for beginners, turning back within Kamimachi. Aid stations in Kamimachi, Obanazawa City, and Oishida Town provided a variety of local specialties and delicacies this year.' where id = 'c3-e7URnTbE0bCY5fo5XH';
update content_bodies set title = 'ナガシマスパーランドに新登場の「白鯨（HAKUGEI）」を体験！(桑名市)｜観光三重｜三重県の観光・旅行情報', description = '2019年3月28日、日本初のハイブリッドコースター「白鯨（HAKUGEI）」がナガシマスパーランドに登場しました。この最新のアトラクションは、木製とスチールが融合したもので、高さ55m、傾斜80度のほぼ直角の落下を体験できます。最高速度107km/hのスリル満点のスピードと、360度のゼロGロールを楽しむことができ、衝撃的な体験が待っています！' where id = 'afyK-f3REb50AsBGlbRLn';
update content_bodies set title = 'Experience the New ''HAKUGEI'' at Nagashima Spa Land! (Kuwana City) | Tourism Mie | Mie Prefecture Travel Information', description = 'On March 28, 2019, Japan''s first hybrid coaster, ''HAKUGEI,'' debuted at Nagashima Spa Land. This cutting-edge ride combines wood and steel, reaching a height of 55 meters and an almost vertical drop of 80 degrees. Riders experience a thrilling speed of 107 km/h and a 360-degree zero-G roll, providing an exhilarating experience!' where id = 'AiRNYXcwA8cdHLFURxsaF';
update content_bodies set title = '加美町冬のスノーシュートレッキング', description = '加美町は「加美富士」として親しまれる標高553mの薬萊山を中心に、トレッキングや自転車、キャンプなど、初心者から上級者まで自然とふれあえる環境が整っています。今回は薬萊山でスノートレッキングを行いました。冬のアクティビティとしておすすめのスノーシューは、静けさの中で新雪を踏みしめる非日常的な体験を提供します。低山でありながら雪深い登山道は、初心者でも冬山の楽しみを十分に味わうことができます。' where id = '9coScjPLrPn4SbqAxSnOL';
update content_bodies set title = 'Winter Snowshoe Trekking in Kamimachi', description = 'Kamimachi, known for its beloved ''Kamifuji'' or Mount Yakurai, stands at 553 meters and offers a rich environment for trekking, cycling, and camping suitable for all skill levels. This winter, we explored snowshoe trekking on Mount Yakurai. Snowshoeing is a recommended winter activity that allows participants to enjoy the tranquility of nature while stepping on fresh snow, providing a unique experience. Despite being a low mountain, the snowy trails offer enough depth for beginners to fully enjoy the winter mountain experience.' where id = 'vLNKkeJm_baVdtajB8zR6';
update content_bodies set title = '宮城加美町 桜の名所2019', description = '宮城県加美町は県北部に位置し、毎年4月上旬から中旬にかけて桜が満開を迎えます。加美町の桜観光に役立つ情報として、以下の名所を紹介します。1) ふれあいの森公園パークゴルフ場、2) 薬萊桜並木、3) 町指定天然記念物の内海家の種まき桜、4) 町指定天然記念物の廣原神社シダレヒガン桜、5) 美代川屋敷公園、6) 中新田城跡の長興寺です。来春の訪問をぜひ検討してください。' where id = 'gwF9YsBPyQ4-0tTEZOeBS';
update content_bodies set title = 'Cherry Blossom Spots in Kamimachi, Miyagi 2019', description = 'This text introduces the cherry blossom spots in Kamimachi, located in the northern part of Miyagi Prefecture. The cherry blossoms typically reach full bloom from early to mid-April each year. The following locations are recommended for cherry blossom viewing in Kamimachi next spring: 1) Fureai no Mori Park Golf Course, 2) Yakurai Cherry Blossom Avenue, 3) Utsumi Family''s Seedling Cherry Tree (designated natural monument), 4) Shidare Higan Cherry Tree at Hirohara Shrine (designated natural monument), 5) Miyogawa Yashiki Park, and 6) Nakashinden Castle Ruins at Chokoji.' where id = 'U4EKc42CcN6bKP9UyVeoA';
update content_bodies set title = 'SEA TO SUMMIT®︎2018宮城加美町 動画', description = '2018年に開催された「SEA TO SUMMIT®︎2018宮城加美町」のイベント全体動画です。本大会は二日間にわたり、初日に環境シンポジウム、二日目にアクティビティが行われました。この動画は二日間の行程をまとめたものです。また、SEA TO SUMMIT®︎2019宮城加美町大会が10月5日と6日に開催される予定で、現在申し込みを受け付けています。ぜひご応募ください。' where id = 'FFW0Ihk_tOEPQzKmOc-Vy';
update content_bodies set title = 'SEA TO SUMMIT®︎2018 Miyagi Kamimachi Video', description = 'This is the overall video of the ''SEA TO SUMMIT®︎2018 Miyagi Kamimachi'' event held in 2018. The event took place over two days, featuring an environmental symposium on the first day and various activities on the second day. This video summarizes the itinerary of both days. Additionally, the SEA TO SUMMIT®︎2019 Miyagi Kamimachi event is scheduled for October 5th and 6th, and applications are currently being accepted. We encourage everyone to apply!' where id = 'OPXRf54z2aF9EX9aHfRt-';
update content_bodies set title = 'イベント告知：天空のロマン～星空と音楽の夕べ～', description = '環境庁が認定する「星の美しいまち」で全国２位に選ばれた由利本荘市の花立牧場公園で、星空と音楽を楽しむイベントが開催されます。ぜひお越しください。イベントの詳細は由利本荘市観光協会のHPでも紹介されています。' where id = 'yObHrqnxOU-gJZvMPEUEc';
update content_bodies set title = 'Event Announcement: Evening of Stars and Music', description = 'An event celebrating the beauty of the night sky and music will be held at Hanatate Ranch Park in Yurihonjo City, which has been recognized as the second-best ''starry town'' in Japan by the Ministry of the Environment. We invite everyone to come and enjoy this unique experience. For more information about the event, please visit the Yurihonjo City Tourism Association''s website.' where id = '8PJlV-nn080DtXygfpoZX';
update content_bodies set title = '【秋田県由利本荘市】初夏の観光名所「桑ノ木台湿原」へのアクセス方法をご紹介します！！', description = '由利本荘市の魅力を発信するPR動画シリーズの一環として、今回は「桑ノ木台湿原」のアクセス方法について紹介します。詳細は由利本荘市観光協会のHPをご確認ください。' where id = '5IZR3d2GjbaCATWndWjD_';
update content_bodies set title = 'Access Guide to Kuwanokidai Wetland, a Summer Tourist Spot in Yurihonjo City, Akita Prefecture', description = 'This is a promotional video series showcasing the attractions of Yurihonjo City. In this episode, we focus on the access information for Kuwanokidai Wetland. For more details, please visit the Yurihonjo City Tourism Association website.' where id = 'o4Icfr5w-2qoVDHiUvXaV';
update content_bodies set title = '宮城・山形「絆」tour de 347 2019', description = '宮城・山形「絆」tour de 347 2019の動画です。このイベントは、国道347号線の通年通行の実現を記念して開催され、宮城県加美町と山形県尾花沢市の地域間交流を目的としています。約40kmのショートコースと100kmのロングコースの2つがあり、どちらも国道347号線の自然を楽しむことができます。本動画は、平成31年5月26日に行われた第3回のロングコースの様子を収めています。' where id = 'iVH_pZhqT-F8BAR3qa8kb';
update content_bodies set title = 'Miyagi and Yamagata ''Bond'' Tour de 347 2019', description = 'This video showcases the ''Bond'' Tour de 347 2019, which commemorates the year-round accessibility of National Route 347. The event was held to promote regional exchange between Kamimachi in Miyagi Prefecture and Obanazawa City in Yamagata Prefecture. It features two courses: a short course of approximately 40 km and a long course of 100 km, both designed to allow participants to fully experience the natural beauty along National Route 347. The video captures the long course event that took place on May 26, 2019.' where id = 'xxU22F-IqT-28rsJ_ri1Z';
update content_bodies set title = '【大自然4K】「阿蘇 野焼き」高画質 癒し映像', description = '自然豊かな阿蘇の風景を4Kカメラで撮影するシリーズ『SCENE of the ASO』の第6巻は、阿蘇の春の風物詩「野焼き」を特集しています。阿蘇の広大な草原は、牛馬の放牧や冬の飼料の供給だけでなく、降った雨を大地に吸収し、九州の水がめとなる6つの一級河川の水源にもなっています。また、草原特有の希少な動植物が生息しており、野焼きによって千年以上も維持されています。今回は、阿蘇市町古閑牧野で行われた「あそたんガイドツアーズ」による『野焼き体験イベント』の様子を中心にお届けします。長回しの映像は倍速で見ると、より野焼きの様子を楽しむことができます。' where id = '_ESifHT-UVhGOIZHExto1';
update content_bodies set title = 'Aso Wildfire: High-Quality Healing Video in 4K', description = 'The series ''SCENE of the ASO'' captures the rich landscapes of Aso in 4K. Volume 6 features the spring tradition of ''wildfire'' in Aso. The expansive grasslands of Aso serve as a source of water for six major rivers in Kyushu, absorbing large amounts of rain and supporting livestock grazing and winter feed. These grasslands are also home to rare flora and fauna, maintained for over a thousand years through the practice of wildfires. This video focuses on the ''wildfire experience event'' organized by ''Asotan Guide Tours,'' showcasing the fire-starting experience held in the ancient pasture of Aso City, Kochi. The long takes can be enjoyed at higher speeds for a more engaging view of the wildfires.' where id = 'uxPMiawlzeufncdIIqqik';
update content_bodies set title = '【大自然4K】「阿蘇 手野の水車」 高画質 癒し映像', description = '『SCENE of the ASO』シリーズの一環として、阿蘇の自然豊かな風景を4Kカメラで撮影した映像です。第1巻では、阿蘇外輪山の裾野に位置する手野集落の『手野の水車』が紹介されています。この地域は名水の里として知られ、集落の至る所から湧き出る水があります。水車の背後には清流宮川が流れています。また、地域おこしグループ「手野名水会」が水車や名水スポットの環境整備を行っています。' where id = 'pcuutWYSTywK70gWTm7br';
update content_bodies set title = 'Aso Tenno Waterwheel - 4K Nature Healing Video', description = 'This video is part of the ''SCENE of the ASO'' series, showcasing the rich natural landscapes of Aso captured in 4K. Volume 1 features the ''Tenno Waterwheel'' located in the Tenno village at the foot of the Aso outer rim. This area is known for its abundant spring water, and a clear stream, Miyagawa, flows behind the waterwheel. Additionally, the local group ''Tenno Meisui Kai'' is involved in environmental maintenance, focusing on the waterwheel and other famous water spots in the region.' where id = 'Y5EzJFJreK8S_yUr0J6n1';
update content_bodies set title = '第54回全国ごてんまりコンクール入賞作品', description = '2023年10月21日と22日に開催される全国ごてんまりコンクールの入賞作品を紹介します。ぜひ会場でご覧ください。' where id = '4RUmdszDAL6RCz6z7kfm1';
update content_bodies set title = '54th National Gotemari Competition Award-winning Works', description = 'The award-winning works of the National Gotemari Competition, held on October 21 and 22, 2023, are introduced. Please be sure to see them at the venue.' where id = 'E6OosJAeBWpZUOZ6B0uzQ';
update content_bodies set title = '秋田県由利本荘市「ワーケーションモニターツアー」参加者コメント', description = '秋田県由利本荘市でリモートワークの促進と関係人口の創出を目指し、自然・食・歴史・文化・SDGsなどをテーマにした「ワーケーションモニターツアー」が実施されました。このツアーでは、参加者のコメントも紹介されており、楽しむことができます。由利本荘市でしか体験できないユニークな「ワーケーション」を提案しています。詳細は由利本荘市のワーケーション特設サイトをご覧ください。' where id = 't6UJz6nwuKjAwEKNFB47T';
update content_bodies set title = 'Participant Comments on the ''Workation Monitor Tour'' in Yurihonjo City, Akita Prefecture', description = 'The ''Workation Monitor Tour'' was conducted in Yurihonjo City, Akita Prefecture, aiming to promote remote work and create a community of relationships. The tour focused on themes such as nature, food, history, culture, and SDGs. Participants'' comments are included for your enjoyment. Experience a unique ''workation'' that can only be found in Yurihonjo City. For more information, visit the Yurihonjo City Workation Special Site.' where id = '7n95k65ZgHNutdooTRofc';
update content_bodies set title = '秋田県由利本荘市ワーケーションモニター', description = '秋田県由利本荘市でリモートワークの促進と関係人口の創出を目指し、自然や食、歴史、文化、SDGsなどをテーマにした「ワーケーションモニターツアー」が実施されました。このツアーでは、由利本荘市ならではのユニークなワーケーション体験が提供され、参加者は特別な活動を楽しむことができました。参加者のコメントはYouTubeリンクで確認できます。詳細は由利本荘市のワーケーション特設サイトをご覧ください。' where id = 'NZlOCcw-nM2-8C2lgnanO';
update content_bodies set title = 'Workation Monitor in Yurihonjo City, Akita Prefecture', description = 'A ''workation monitor tour'' was conducted in Yurihonjo City, Akita Prefecture, aimed at promoting remote work and creating a community of relationships. The tour focused on themes such as nature, food, history, culture, and SDGs. Participants had the opportunity to experience unique workation activities that can only be found in Yurihonjo City. For participant comments, visit the provided YouTube link. More information can be found on the Yurihonjo City workation special site.' where id = '1Q0KF3x8SNEaBzAkYC_n2';
update content_bodies set title = '【秋田県由利本荘市】雄大すぎる自然を楽しむ「鳥海山・飛島ジオパーク編」', description = '由利本荘市の魅力を発信するPR動画シリーズです。鳥海山・飛島ジオパークの魅力を紹介し、ジオガイドの早川恵さんと佐々木英樹さんが出演しています。ガイドの依頼は、協議会のホームページから予約可能です。' where id = '9zP7UTSdzsbTTMODyp6Gp';
update content_bodies set title = 'Enjoying the Magnificent Nature of Yurihonjo City: Chokai Mountain and Tobishima Geopark Edition', description = 'This is a promotional video series showcasing the attractions of Yurihonjo City. It highlights the charm of the Chokai Mountain and Tobishima Geopark, featuring the insights of geo-guides Megumi Hayakawa and Hideki Sasaki. Reservations for guided tours can be made through the council''s website.' where id = 'tuObgcHBN6Af1_JyrPveV';
update content_bodies set title = '佐藤義弘写真展「桃源郷百宅」織田羽衣子先生トークセッション', description = '2023年4月16日に開催された佐藤義弘の写真展「桃源郷百宅」内で、織田羽衣子先生が百宅赴任時代の思い出を語るトークセッションの内容を収録しています。このイベントでは、織田先生の貴重な体験や思い出が語られ、参加者にとっても感慨深い時間となりました。写真展自体は、佐藤義弘氏の作品を通じて、桃源郷の美しさや文化を再発見する機会を提供しています。' where id = 'spOCpfkUC_9RmKP6Y9xhb';
update content_bodies set title = 'Yoshihiro Sato Photography Exhibition ''Togakushi Hundred Houses'' Talk Session with Professor Uiko Oda', description = 'This is a recording of Professor Uiko Oda''s memories from her time at the Hundred Houses during the Yoshihiro Sato photography exhibition ''Togakushi Hundred Houses,'' held on April 16, 2023.' where id = 'lvyLz0e-ehNI2HgZchd07';
update content_bodies set title = '【大自然4K】「阿蘇 中岳火口」高画質 癒し映像', description = '自然豊かな阿蘇の風景を4Kカメラで撮影するシリーズ『SCENE of the ASO』の第2弾です。力強い大地の鼓動が感じられる「中岳火口」は、阿蘇の人々が千年以上前から共に生きてきた場所です。中岳の火山活動は、広大な草原や温泉、地下水といった恵みをもたらし、時には自然の驚異を教えてくれます。2021年10月20日に噴火した中岳は、現在噴火警戒レベル3のため入山規制があり火口見学ができませんが、2021年8月と9月に撮影された中岳山頂（標高1,506メートル）、東峰展望所、そして中岳第1火口の火口縁からの映像をお楽しみください。' where id = 'WU7j3z7tycp0FPws5LiOe';
update content_bodies set title = 'Aso Nakadake Crater - High-Quality Healing Video in 4K', description = 'This is the second volume of the series ''SCENE of the ASO,'' showcasing the rich natural landscapes of Aso captured with a 4K camera. The Nakadake crater, where the powerful heartbeat of the earth can be felt, has been a part of the lives of the people of Aso for over a thousand years. The volcanic activity of Nakadake provides us with the blessings of vast grasslands, hot springs, and underground water, while also teaching us the wonders of nature. Although the Nakadake crater is currently under eruption alert level 3, restricting access for viewing due to the eruption on October 20, 2021, you can enjoy footage taken from the summit of Nakadake at 1,506 meters, the Higashiho viewpoint, and the crater rim of Nakadake No. 1, filmed in August and September 2021.' where id = 'P5EbyP3_xh5yXixtP9w9b';
update content_bodies set title = '【大自然4K】「阿蘇 雲海」高画質 癒し映像', description = '『SCENE of the ASO』シリーズの第3巻で、阿蘇の幻想的な雲海を4Kカメラで撮影した映像です。阿蘇谷では秋から冬にかけて雲海のシーズンを迎え、湿度が高く、放射冷却により地表が冷え、風がないといった気象条件が重なった時に、夜明け前から早朝にかけて雲海が発生します。2021年11月、阿蘇市の田子山にある人気スポット『そらふねの桟橋』で撮影されました。倍速で見ると、雲の流れをより楽しむことができます。' where id = 'Tp8EbKvO6rO1oF2x8b_Bd';
update content_bodies set title = 'Aso Sea of Clouds in 4K - Healing Nature Video', description = 'This is the third volume of the series ''SCENE of the ASO,'' showcasing the breathtaking sea of clouds in Aso, captured in 4K. The sea of clouds typically occurs in the Aso valley from autumn to winter, under specific weather conditions such as high humidity, radiative cooling of the surface, and calm winds. These conditions lead to the formation of clouds during the early morning hours before dawn. The footage was filmed in November 2021 at the popular spot ''Sorafune no Sanbashi'' in Aso City, Takeyama. Watching the clouds flow in fast motion enhances the viewing experience.' where id = '9j9ar57c0cUMpatkTJGhK';
update content_bodies set title = '第５２回　全国ごてんまりコンクール　会場レポート', description = '令和３年１０月３０日と３１日に開催された「全国ごてんまりコンクール」の様子をお届けします。このコンクールは、全国から集まった参加者が自慢のごてんまりを披露し、技術や創造性を競い合う場となっています。多くの来場者が訪れ、賑やかな雰囲気の中で、参加者たちの熱意が感じられました。' where id = 'f8f6pZ3rO_uFmUKhg0R5j';
update content_bodies set title = '52nd National Gotemari Competition Venue Report', description = 'This report covers the events of the ''National Gotemari Competition'' held on October 30 and 31, 2021.' where id = 'Zil-UQkqGo4mPEqxr7tXU';
update content_bodies set title = 'チョイぶらまち歩き　北前船寄港地「石脇湊」コース', description = 'ガイドと共に本荘市街地を歩くツアーです。市内のホテルから歩いて行ける範囲で、1,000円で依頼できます。すきま時間を利用して、素敵な場所を見つけましょう！' where id = 'iAPcRJw9wtdjE8W-IuFJM';
update content_bodies set title = 'Choi-bura City Walk: Kitamaebune Port Town ''Ishiwaki Minato'' Course', description = 'Join a guided walking tour through Honjo city. The tour is available for 1,000 yen and can be accessed within walking distance from local hotels. Discover great spots during your free time!' where id = 'qjv3pCUsPXsI-iZU4ekrZ';
update content_bodies set title = '鳥海山の雪上車パトロールに同行してみた', description = '秋田県南部に位置する鳥海山は、山形県との県境にある重要な自然のランドマークです。由利本荘市は鳥海山の北麓に広がり、秋田県で最も面積の大きい自治体です。この地域は、豊かな自然に育まれた文化や歴史、山から海に至るまでの多彩なレジャーが自慢です。この記事では、まだ雪に覆われている3月の鳥海山を雪上車に乗ってパトロールした様子を紹介します。' where id = '_Zq28i-KOqzcT0gPq8Gx7';
update content_bodies set title = 'Exploring Chokai Mountain on a Snowcat Patrol', description = 'Chokai Mountain, located on the border between Akita and Yamagata Prefectures, is a prominent natural landmark. The city of Yurihonjo, situated at the northern foot of Chokai Mountain, is the largest municipality in Akita Prefecture. This region boasts a rich culture and history nurtured by its abundant nature, along with a variety of leisure activities from the mountains to the sea. This article shares the experience of patrolling Chokai Mountain in March, when it is still covered in snow, aboard a snowcat.' where id = '2FFABkwVW4jGFmV8jtoGI';
update content_bodies set title = '由利本荘市観光ＰＲ動画パート１（自然編）', description = '由利本荘市の観光PR動画シリーズの自然編です。この動画では、市内の見どころを紹介しています。皆さん、ぜひ訪れてください！' where id = 'RfxGiAMSzJuQ3aI36qTLC';
update content_bodies set title = 'Yurihonjo City Tourism PR Video Part 1 (Nature Edition)', description = 'This is the nature edition of the tourism PR video series for Yurihonjo City. It showcases the attractions within the city. Everyone, please come and visit!' where id = 'Es5PzZDM0QHeD7wKFesXp';
update content_bodies set title = '東京で試すべき4つの伝統的な体験 - 相撲、日本酒など！', description = '東京はネオンの光や先進的な技術で知られる現代的な大都市ですが、伝統的な体験も豊富にあります。このガイドでは、試すべき4つのアクティビティを紹介します。まずは、辰浪部屋での相撲ツアーで、相撲の文化やスポーツについて学ぶことができます。次に、長谷川英雅の日本酒体験では、本格的な日本酒の試飲が楽しめます。さらに、金継ぎ体験では、金を使って陶器を修復する技術を学ぶことができます。そして、屋形船体験では、東京の水上からの景色を楽しむユニークなボートライドが待っています。これらの体験は、日本の文化遺産を垣間見ることができ、東京を訪れる際には欠かせないものです。' where id = 'Yb_3arB-VGVvCnxApGtSq';
update content_bodies set title = '4 Traditional Experiences You Need to Try in Tokyo - Sumo, Sake & more!', description = 'Tokyo is often seen as a modern metropolis with its neon lights and advanced technology, but it also offers rich traditional experiences. This guide highlights four must-try activities: the Sumo Tour at Tatsunami Stable, where visitors can learn about the sport and its culture; the Hasegawa Eiga Sake Experience, which provides a tasting of authentic Japanese sake; the Kintsugi Experience, where participants can learn the art of repairing pottery with gold; and the Yakatabune Experience, a unique boat ride that showcases Tokyo from the water. Each of these experiences offers a glimpse into Japan''s cultural heritage, making them essential for anyone visiting Tokyo.' where id = 'fDT4XJJ2g3Hl-HiQnFMXd';
update content_bodies set title = '今週の東京でのトップ5アクティビティ！(2025年12月8日)', description = '今週の東京では、光や祭り、クリスマスの魅力に満ちた楽しい雰囲気が広がります。この記事では、今週東京で楽しむべきトップ5のアクティビティを紹介しており、地元の人々や訪問者にとってワクワクする時間となっています。東京でのイベントの詳細については、提供されたイベントリストのリンクをチェックしてください。' where id = 'OIlWu_sYAIUvQwHa3H_vk';
update content_bodies set title = 'Top 5 things to do in Tokyo this week! (Dec 8th 2025)', description = 'This week in Tokyo, get ready for a festive atmosphere filled with lights, celebrations, and the magic of Christmas. The article highlights the top five activities to enjoy in the city during this week, making it an exciting time for both locals and visitors. For more details on events happening in Tokyo, you can check the provided events listing link.' where id = 'cCQgQQNAhv8L42oYt7w7T';
update content_bodies set title = '代官山と恵比寿を発見 - あなたが知らない渋谷！', description = 'この動画では、渋谷のあまり知られていないエリア、特にファッショナブルな代官山と中目黒に焦点を当てています。これらの地域には多くの有名人やスタイリッシュな住民が住んでおり、賑やかな渋谷とは異なり、より高級でブティックな雰囲気を提供しています。一方、恵比寿は落ち着いた住宅街で、居心地の良いレストランやパブ、立ち飲み屋が有名で、地元の人々や外国人にも人気のスポットです。動画では、旧朝倉邸や代官山Tサイト、恵比寿横丁など、訪れるべき場所のさまざまなおすすめが紹介されており、これらのユニークな地域を楽しむための包括的なガイドを提供しています。' where id = '9aLudIxC19uMze2utbhWw';
update content_bodies set title = 'Discover Daikanyama & Ebisu - The Shibuya That You Don''t Know!', description = 'This video explores the lesser-known areas of Shibuya, focusing on the fashionable neighborhoods of Daikanyama and Nakameguro. These areas are home to many celebrities and stylish residents, offering a more upscale and boutique atmosphere compared to the bustling Shibuya. Ebisu, in contrast, is a laid-back residential area known for its cozy restaurants, pubs, and standing bars, making it a popular spot for both locals and expats. The video includes various recommendations for places to visit, such as Kyu Asakura House, Daikanyama T-Site, and Ebisu Yokocho, providing viewers with a comprehensive guide to enjoying these unique neighborhoods.' where id = 'yjbs3I73YwklSvA0ryn4w';
update content_bodies set title = '渋谷に行くのをやめよう：地元の人が愛する東京の隠れた2つのエリア（自由が丘と大井町）', description = 'この記事では、東京の隠れた魅力的なエリアである自由が丘と大井町を紹介しています。自由が丘は目黒区の南端に位置し、住宅と商業が混在する地域で、高級レストランやファッション店が多く、石畳の道が特徴的で「リトル・ヨーロッパ」と呼ばれています。一方、大井町は居酒屋の雰囲気が楽しめるエリアで、大井町横丁では地元の夜の雰囲気を味わうことができます。記事には、両エリアの観光スポットやアクティビティを紹介する章があり、観光地の渋谷ではなく、これらの隠れた宝石を探索することを勧めています。' where id = 'dgORCvCe4mv1MMjWclNDc';
update content_bodies set title = 'Stop Going to Shibuya: 2 Hidden Tokyo Neighborhoods Locals Love (Jiyugaoka & Oimachi)', description = 'This article introduces two lesser-known neighborhoods in Tokyo, Jiyugaoka and Oimachi, which are favored by locals. Jiyugaoka, located in the southern part of Meguro Ward, is a blend of residential and commercial areas, featuring upscale restaurants and boutiques, earning it the nickname ''Little Europe'' due to its charming cobblestone streets. Oimachi, on the other hand, is known for its vibrant izakaya scene and local nightlife, particularly in Oimachi Yokocho, where visitors can enjoy authentic dining experiences. The article also includes various chapters highlighting attractions and activities in both neighborhoods, encouraging readers to explore these hidden gems instead of the more touristy Shibuya.' where id = 'vRAPTsOX7zQEJjF73bqe8';
update content_bodies set title = '横浜の15のトップヒント - 日本の第二の都市！', description = '横浜は日本の第二の都市で、東京からの理想的な日帰り旅行先です。美しい庭園や活気ある中華街、素晴らしい夕日を楽しむことができます。19世紀半ばから港町として栄え、歴史的な魅力と現代的なアトラクションが融合しています。訪問者は、山下公園や三溪園、有名な赤レンガ倉庫など、さまざまなスポットを探索できます。また、中華街では美味しい中華料理を楽しむことができるのも特徴です。提案された旅程は柔軟で、旅行者は自分の好みに応じて体験をカスタマイズできます。豊かな歴史と現代アートのシーンを持つ横浜は、充実した探索の日を約束します。' where id = 'O9iPx-_CgzsVLP9nOB_Ep';
update content_bodies set title = '15 TOP TIPS for Yokohama - Japan’s second-largest city!', description = 'Yokohama, Japan''s second-largest city, is an ideal day trip from Tokyo, offering a blend of beautiful gardens, a vibrant Chinatown, and stunning sunset views. Since the mid-19th century, it has thrived as a port town, showcasing a mix of historical and modern attractions. Visitors can explore various sites, including Yamashita Park, Sankeien Garden, and the famous Red Brick Warehouse. The city is also known for its unique culinary offerings, particularly in Chinatown, where one can enjoy delicious Chinese food. The itinerary provided is flexible, allowing travelers to customize their experience based on personal preferences. With its rich history and contemporary art scene, Yokohama promises a fulfilling day of exploration.' where id = 'RMvN9WMKteFNI1aYh5SRm';
update content_bodies set title = '池袋での21のおすすめアクティビティ', description = '池袋は、東京の商業地区で、新宿の賑やかな雰囲気と秋葉原のポップカルチャーを融合させた場所です。アニメ、ファッション、エレクトロニクスに興味を持つ観光客に最適で、さまざまなアクティビティが楽しめます。美味しいラーメンやシェイキーズピザを味わったり、数多くのアーケードを探索したりできます。主な観光スポットには、サンシャインシティ、世界最大のアニメグッズ店アニメイト、歴史ある岸神神社があります。また、バクダン焼きの巨大たこ焼きやワーナーブラザーズスタジオツアーなど、ユニークな体験も楽しめます。便利な交通手段と多様な料理が揃う池袋は、東京の魅力を体験するための必訪スポットです。' where id = 'WNDzUax9ClQd65v1_2fHC';
update content_bodies set title = 'TOP 21 Things to Do in Ikebukuro, Tokyo', description = 'Ikebukuro is a vibrant commercial district in Tokyo that merges the bustling atmosphere of Shinjuku with the pop culture vibe of Akihabara. It caters to diverse interests, making it an ideal destination for tourists interested in anime, fashion, and electronics. The area offers a plethora of activities, including dining on delicious ramen, enjoying Shakey''s Pizza, and exploring numerous arcades. Key attractions include Sunshine City, the world''s largest anime goods store Animate, and the historic Kishimojin Temple. Visitors can also enjoy unique experiences like the Warner Bros. Studio Tour and the giant takoyaki at Bakudan-yaki. With convenient transport options and a variety of cuisines, Ikebukuro is a must-visit for anyone looking to experience the best of Tokyo.' where id = 'JDhbpRTytlG7UE-gERXIj';
update content_bodies set title = '2025年の新宿に関する20の新しいヒント', description = '新宿は観光、ショッピング、食事、飲みなど多様な楽しみ方ができる東京の活気あるエリアです。この動画では、新宿を探索するための20の新しいヒントを紹介し、人気の観光スポットや隠れた名所を強調しています。主なおすすめには、新宿中央公園、熊野神社、明治神宮外苑が含まれ、デパートでのショッピングやゲームセンターの訪問も提案されています。また、新宿駅の利用方法や、富士山や空港への交通手段についての実用的なアドバイスも提供されています。賑やかなエネルギーと静かなスポットが共存する新宿は、東京の本質を捉えた必見の目的地です。' where id = 'WHl3qo80dHYEDwVUzVCXA';
update content_bodies set title = '20 NEW TIPS for Shinjuku, Tokyo - 2025', description = 'Shinjuku is a vibrant area in Tokyo known for its diverse offerings, including sightseeing, shopping, dining, and nightlife. The video presents 20 new tips for exploring Shinjuku, highlighting both popular attractions and hidden gems. Key recommendations include Shinjuku Central Park, Kumano Shrine, and Meiji Jingu Gaien, as well as shopping at department stores and visiting game centers. The video also provides practical advice on navigating Shinjuku Station and accessing transportation to Mount Fuji and the airport. With a mix of bustling energy and serene spots, Shinjuku captures the essence of Tokyo, making it a must-visit destination for both tourists and locals.' where id = 's0wVg9RMUUgdaXr0UvZPY';
update content_bodies set title = 'HAKONE日帰り旅行 🇯🇵 - 伝統的な日本の探求：神社、火山谷、富士山の眺め', description = 'HAKONE日帰り旅行ガイドでは、日本の箱根でのアクティビティを包括的に紹介しています。温泉に浸かり、美しい湖の景色や富士山の絶景を楽しむことができます。移動の便利さから、レンタカーの利用が推奨されています。箱根には火山の風景、ハイキングコース、美術館、歴史的な名所が点在しています。また、エヴァンゲリオンファンには嬉しいスポットも多くあります。このガイドでは、日帰りでも長期滞在でも楽しむためのヒントが紹介されています。主要な立ち寄りスポットには、箱根湯本駅、箱根神社、富士山の眺めが楽しめる芦ノ湖パス、大涌谷、箱根彫刻の森美術館、地元の飲食店である強羅ビールなどがあります。' where id = 'sXnW8LSnsgnppR6GIFvxj';
update content_bodies set title = 'HAKONE Day Trip 🇯🇵 - Exploring Traditional Japan: Shrines, Volcanic Valleys & Mount Fuji Views', description = 'The Hakone Day Trip Guide offers a comprehensive overview of activities in Hakone, Japan. Visitors can enjoy hot springs, stunning lake views, and breathtaking sights of Mount Fuji. Renting a car is recommended for convenience. The area features volcanic landscapes, hiking trails, art museums, and historical sites. Anime fans, particularly those of Evangelion, will find many references throughout the region. The guide includes tips for maximizing your experience, whether you''re visiting for a day or longer. Key stops include Hakone Yumoto Station, Hakone Shrine, Shakushi Pass for Mount Fuji views, Owakudani, and the Hakone Open Air Museum, along with local dining options like Gora Brewery.' where id = '1Pwn46jM8PPHNvOLs9jQV';
update content_bodies set title = '東京・銀座での18のおすすめアクティビティ', description = '銀座は東京の高級ショッピングエリアで、豪華なブランドと華やかな雰囲気で知られています。もともとは江戸の一部であり、銀貨鋳造所にちなんで名付けられたこの地域は、歴史的な魅力を少し残しています。この動画では、2025年の銀座で楽しむべき18のアクティビティを紹介しています。銀座シックスの屋上テラスや歌舞伎の観賞、銀座ソニーパークの探索、アート展の鑑賞などが含まれています。他にも、文房具好きにはたまらない伊東屋や、東京初の立ち飲みバー300bar、松屋カメラフェアでのカメラショッピング、浜離宮恩賜庭園でのリラックス、銀座天丼いつきでの美味しい天ぷらを楽しむことができます。訪れるのに最適な時期は歩行者天国の日で、資生堂や無印良品のグローバルフラッグシップストア、ユニクロのフラッグシップストアも必見です。動画の最後には新橋のバーやレストランのおすすめも紹介されています。' where id = 'mOu0lsnbsWJ_EajfB1LZW';
update content_bodies set title = 'TOP 18 Things to do in Ginza, Tokyo', description = 'Ginza is Tokyo''s upscale shopping district, known for its luxury brands and glamorous atmosphere. Originally part of Edo, it retains some historical charm, having been named after a former silver mint. The video presents the top 18 activities to enjoy in Ginza in 2025, including visiting the rooftop terrace at Ginza Six, watching Kabuki performances, exploring Ginza Sony Park, and enjoying art exhibitions. Other highlights include Itoya, a paradise for stationery lovers, and the first standing bar in Tokyo, 300bar. Visitors can also shop for cameras at Matsuya Camera Fair, relax at Hama-rikyu Gardens, and savor delicious tempura at Ginza Tendon Itsuki. The best time to visit is during pedestrian zone days, and essential stops include the Shiseido store, Muji Global Flagship Store, and Uniqlo Flagship Store. The video concludes with recommendations for bars and restaurants in Shimbashi.' where id = '6OmC2SmOTqaQiGV06wfM7';
update content_bodies set title = '原宿の16のトップヒント - ファッション以上の魅力！', description = '原宿は、ユニークなファッション、ストリートフード、文化体験で知られる東京の活気ある地区です。このガイドは、初めて訪れる人のために、主要な観光スポットやアクティビティを強調した包括的な旅程を提供します。静かな明治神宮から始まり、流行のショップやプリクラ（写真ブース）が楽しめる竹下通りなどの人気スポットを含んでいます。また、アートギャラリーを探索したり、地元のスナックを試したり、代々木公園でリラックスすることも提案しています。ショッピングやキャラクターグッズ、屋上でのドリンクに関するヒントもあり、原宿の多様な魅力を楽しむための便利なガイドとなっています。' where id = 'kaxxR8FbiuRL0pVCYAjCp';
update content_bodies set title = '16 TOP TIPS for Harajuku, Tokyo - More Than Just Fashion!', description = 'Harajuku is a vibrant district in Tokyo known for its unique fashion, street food, and cultural experiences. This guide provides a comprehensive itinerary for first-time visitors, highlighting key attractions and activities. Starting with the serene Meiji Jingu Shrine, the itinerary includes popular spots like Takeshita Street, where visitors can enjoy trendy shops and purikura (photo booths). The guide also suggests exploring art galleries, trying local snacks, and visiting Yoyogi Park for relaxation. With tips on shopping, character goods, and rooftop drinks, this guide ensures a well-rounded experience in Harajuku, making it easy to navigate and enjoy the diverse offerings of this iconic area.' where id = 'PoXgVXrMjNtacpnojfNUX';
update content_bodies set title = '上野、東京のための15のトップヒント - 上野公園、谷中銀座、蔵前など！', description = '上野は東京の活気あるエリアで、訪問者はあまりお金を使わずにさまざまなアトラクションを楽しむことができます。このガイドでは、賑やかな雰囲気とストリートフードで知られるアメ横や、美しい景色と博物館で有名な上野公園などの主要な場所を紹介しています。他にも、歴史と現代のコーヒー文化が融合する蔵前や、地元のショッピングが楽しめる谷中銀座、そして美味しい肉料理が楽しめる肉の鈴木などが挙げられています。文化、食、歴史が融合した上野は、旅行者にとって豊かな体験を提供します。' where id = 'ZE4dcNqvolnB-rcrDiysH';
update content_bodies set title = '15 TOP TIPS for Ueno, Tokyo - Ueno Park, Yanaka Ginza, Kuramae & More!', description = 'Ueno is a vibrant area in Tokyo where visitors can enjoy a variety of attractions without spending too much. The guide highlights key locations such as Ameyoko Street, known for its lively atmosphere and street food, and Ueno Park, famous for its museums and beautiful scenery. Other notable spots include Hanazono Inari Shrine, Aki-Oka Artisan for crafts, and Kuramae, which blends history with modern coffee culture. The guide also suggests exploring Yanaka Ginza for local shopping and Niku no Suzuki for delicious meat dishes. With a mix of culture, food, and history, Ueno offers an enriching experience for travelers.' where id = 'bvXiVZvOKZuIjWgCfgLPy';
update content_bodies set title = '日本訪問に最適なポケットWi-Fi - テストと比較。eSIMよりも優れている？', description = 'この記事では、日本を旅行する際にポケットWi-Fiルーターを使用する利点について説明しています。ポケットWi-Fiは、観光用SIMカードやローミングよりも実用的で、特にグループ旅行や複数のデバイスを持つ場合に便利です。内容は、ポケットWi-Fiが誰に向いているか、デバイスの受け取りと返却方法、さまざまなポケットWi-Fiオプションのテスト結果についての章で構成されています。この記事は、旅行者が日本滞在中に効率的に接続を維持する手助けをすることを目的としています。' where id = 'OlRjntSxOasm_AirfPi7F';
update content_bodies set title = 'The Best Pocket WiFi for Visiting Japan - Testing & Comparing. Better Than an eSIM?', description = 'This article discusses the advantages of using a pocket Wi-Fi router while traveling in Japan. It highlights that pocket Wi-Fi is often more practical than tourist SIM cards or roaming, especially for groups or multiple devices. The content includes chapters on who benefits from pocket Wi-Fi, how to receive and return the device, and results from testing various pocket Wi-Fi options. The article aims to help travelers stay connected efficiently during their visit to Japan.' where id = 'H54MNAJGL6arcjYrersJZ';
update content_bodies set title = '中野、東京のための15のトップヒント - アニメグッズ以上の魅力！', description = '中野は、手頃な価格のショッピング、飲食、宿泊施設が揃った活気あるエリアです。中野駅の北にあるアーケード街には、チェーン店や地元の店舗が並び、350店舗が入る独特の13階建て商業施設「中野ブロードウェイ」へと続いています。訪れる人々は、中古の漫画やアニメ商品から裁縫用品まで、さまざまなアイテムを見つけることができます。このガイドでは、中野サンモールの探索や隠れた路地の発見、地元の手頃な価格の土産物を楽しむ方法が紹介されています。また、デイリー・チコでの巨大アイスクリームの挑戦や、ガチャストアのハビコロトイ、アニメコレクションのためのまんだらけの訪問もハイライトです。さらに、富士屋カメラでの新旧カメラ商品や、地元の公園や飲食店も楽しめます。中野は夜も賑やかで、さまざまなバーを探索することができます。' where id = 'I7XuKnbUWU2WMbTAGhUrt';
update content_bodies set title = '15 TOP TIPS for Nakano, Tokyo - More Than Just Anime Goods!', description = 'Nakano, Tokyo, is a vibrant area known for its affordable shopping, dining, and accommodation options. The covered shopping street north of Nakano Station is lined with both chain stores and local shops, leading to Nakano Broadway, a unique 13-level complex filled with 350 shops. Visitors can find a wide range of items, from secondhand manga and anime merchandise to sewing supplies. The guide includes tips on exploring Nakano Sun Mall, discovering hidden side streets, and enjoying local souvenirs at reasonable prices. Highlights also include trying the largest ice cream at Daily Chico, visiting gacha stores like Havikoro Toy, and exploring Mandarake for anime collectibles. The area offers a mix of new and used camera goods at Fujiya Camera, as well as local parks and dining options. Nakano is also lively at night, with various bars to explore.' where id = 'U2_LWDaFXTwOt6VAJD6u4';
update content_bodies set title = '鎌倉の魔法を発見：東京からの完璧な日帰り旅行', description = '鎌倉は東京近郊の魅力的な海辺の町で、古代の神社や寺院、象徴的な大仏像で知られています。美しいハイキングコースでつながれたこの地域は、美味しい食べ物、アートなブティック、トレンディなカフェが揃い、活気ある雰囲気を楽しめます。砂浜や夏の花火、ビーチの小屋も魅力的です。ガイドには、報国寺や銭洗弁天、食べ物やお土産が揃う小町通りなどの見どころが含まれています。また、鎌倉の移動手段や、江ノ電の利用法、天ぷらディナーのおすすめも紹介されています。鎌倉と近くの江ノ島は素晴らしい景色を提供し、東京からの日帰り旅行に人気のスポットとなっています。' where id = 'MIXfSeu2ob9xCNfEDg79Z';
update content_bodies set title = 'Discover the Magic of Kamakura: The Perfect Day Trip From Tokyo', description = 'Kamakura is a charming seaside town near Tokyo, known for its ancient shrines, temples, and the iconic giant Buddha statue. The area is connected by scenic hiking trails and offers a vibrant atmosphere with delicious food, artsy boutiques, and trendy cafes. Visitors can enjoy sandy beaches, summer fireworks, and beach shacks. The guide includes highlights such as Hokokuji Temple, Zeniarai Benten Shrine, and Komachi Street, where one can find food and souvenirs. The video also covers practical tips for getting around Kamakura, including the Enoden train and recommendations for dining, such as a tasty tempura dinner. Kamakura and nearby Enoshima provide stunning views, making it a popular destination for day trips from Tokyo.' where id = 'pasAzgCMzp1pIzujSAh2g';
update content_bodies set title = '東京・六本木でのおすすめアクティビティTOP10：アート、ナイトライフなど！', description = '六本木は、ナイトライフ、ブランドショッピング、アートが融合する活気あるエリアです。このガイドでは、森タワーや東京シティビュー、森美術館などの主要な観光スポットを紹介しています。また、ミッドタウンガーデンや青山霊園などの屋外スペースも楽しめます。東京タワーからの眺めや国立新美術館の探索もおすすめです。文化体験とエンターテインメントが融合したこのエリアは、地元の人々や観光客に人気のスポットです。動画では、訪問時期や食事の選択肢に関する質問にも答えています。日本での快適なモバイルインターネット接続を提供するUbigiも紹介されています。' where id = 'GzBOF4s4KoUhkBH0rsWOs';
update content_bodies set title = 'TOP 10 Things to Do in Roppongi, Tokyo: Art, Nightlife & More!', description = 'Roppongi is a vibrant neighborhood in Tokyo known for its nightlife, shopping, and art. This guide highlights the top attractions, including the Mori Tower, Tokyo City View, and Mori Art Museum, as well as outdoor spaces like Midtown Garden and Aoyama Cemetery. Visitors can also enjoy views from Tokyo Tower and explore the National Art Center. The area offers a mix of cultural experiences and entertainment, making it a popular destination for both locals and tourists. The video includes answers to common questions about visiting Roppongi, such as the best time to visit and dining options. For those looking to stay connected, Ubigi offers fast mobile internet in Japan.' where id = 'OQoZKdlmPd2TBgFw3P-eB';
update content_bodies set title = '私たちは#浅草のスポットを評価します。', description = 'この動画では、浅草のさまざまなスポットの評価を紹介しています。それぞれの場所の特徴や魅力をお伝えします。' where id = 'rZt3pR3tc63X-vzp5HJOB';
update content_bodies set title = 'We rate these spots in #asakusa.', description = 'This video presents a rating of various locations in Asakusa, showcasing the highlights and features of each spot.' where id = 'Ssqq0ZZSEcwFFGK8-yaWs';
update content_bodies set title = '東京・浅草での14のおすすめアクティビティ', description = '浅草は東京の歴史的な地区で、象徴的な浅草寺や活気ある雰囲気で知られています。このガイドでは、着物レンタルや仲見世通りでの伝統的なスナックの探索、東京スカイツリーからの眺めを楽しむなど、浅草で楽しめる14のアクティビティを紹介しています。おみくじで運試しをしたり、スズキエンで抹茶ジェラートを味わったり、ホッピーストリートで地元文化を体験することもできます。他にも、厨房用品のカッパ橋やメロンパンのカゲツドウ、無料の展望デッキがある観光案内所など、浅草は歴史と現代が融合した必見のスポットです。' where id = 'z8O8RCZ22ZdvqeH7j-FjG';
update content_bodies set title = 'TOP 14 Things to Do in Asakusa, Tokyo', description = 'Asakusa is a historic district in Tokyo, known for its iconic Sensōji Temple and vibrant atmosphere. This guide highlights 14 activities to enjoy in Asakusa, including renting a kimono, exploring Nakamise Dori for traditional snacks, and enjoying views from the Tokyo Skytree. Visitors can also check their fortunes with Omikuji, savor matcha gelato at Suzukien, and experience local culture at Hoppy Street. Other attractions include Kappabashi for kitchenware, Kagetsudo for melon bread, and a tourist information center with a free observation deck. Asakusa offers a unique blend of history and modernity, making it a must-visit destination.' where id = 'WPVWDc4ljEZsDQAtZPUT8';
update content_bodies set title = '日本の桜の名所6選', description = 'この動画では、日本の桜の名所6カ所を紹介しています。桜の季節におけるこれらのスポットの美しさと文化的な重要性が強調されています。' where id = 'vXLplPDYM5KV-79O1Ko1Y';
update content_bodies set title = '6 Best Cherry Blossom Spots in Japan', description = 'This video showcases six of the best locations in Japan to view cherry blossoms. It highlights the beauty and cultural significance of these spots during the cherry blossom season.' where id = 'rnz4X3f4BiNOdAEmTJsaR';
update content_bodies set title = '渋谷での23のおすすめアクティビティ', description = '渋谷は東京の若者文化の中心地で、ショッピング、バー、アート、音楽などが豊富に揃っています。このガイドでは、渋谷の象徴的なハチ公像や賑やかなスクランブル交差点、素晴らしい眺望を楽しめる渋谷スカイなど、23の必見スポットを紹介しています。無料のビュースポットやポケモンセンター、任天堂ストアでのショッピング、地元の料理を楽しむことができます。また、カラオケやバー、クラブなどのナイトライフも充実しており、スケートパークやボルダリング、タトゥーに優しい銭湯などユニークな体験も提供しています。この包括的なリストは、初めての訪問者や地元の人々が渋谷での時間を最大限に楽しむためのものです。' where id = 'uUuiDvkj-tMFnlSwTXKBV';
update content_bodies set title = 'TOP 23 Things to Do in Shibuya, Tokyo', description = 'Shibuya is a vibrant hub in Tokyo, known for its shopping, nightlife, and cultural experiences. This guide highlights 23 must-see attractions, including the iconic Hachiko statue, the bustling Scramble Crossing, and the stunning Shibuya Sky observation deck. Visitors can explore free viewing spots, enjoy shopping at the Pokémon Center and Nintendo Store, and indulge in local cuisine. The nightlife scene is rich, with recommendations for karaoke, bars, and clubs. Shibuya also offers unique experiences like skate parks, bouldering, and even a tattoo-friendly sento. This comprehensive list ensures that both first-time visitors and locals can make the most of their time in this dynamic district.' where id = '2HFXMX9abgxbeeKotVjJm';
update content_bodies set title = '川越で見逃せないお菓子、東京からの簡単な日帰り旅行', description = 'この動画では、東京からの簡単な日帰り旅行先である川越で見逃せないお菓子を紹介しています。' where id = '8z_D4pOJi-e06hWxaSxRH';
update content_bodies set title = 'Not to miss treats while you''re in Kawagoe, easy day trip from #tokyo', description = 'This video highlights must-try treats in Kawagoe, which is a convenient day trip destination from Tokyo.' where id = 'gTVq7DIAX7gJA8OmTOxTR';
update content_bodies set title = '東京日帰り旅行：群馬 - 自然、温泉、達磨 🇯🇵', description = '群馬県は高品質な温泉で知られ、訪れる価値のある場所です。美しい自然景観が広がり、山々と水路が特徴で、アウトドア活動に最適です。冬にはスキー、暖かい季節にはラフティングやキャニオニングが楽しめます。このガイドでは、少林山達磨寺、嶋温泉、関善館旅館、吾妻峡、伊香保温泉などの見どころや、地元の食事として親子天うどんも紹介されています。東京とその周辺を手頃に探索したい人に向けた内容です。' where id = 'e7c_Q3ZlvjPJ3f0UzVaRT';
update content_bodies set title = 'Tokyo Day Trip: Gunma - Nature, Hot Springs and Daruma 🇯🇵', description = 'Gunma is renowned for its high-quality onsen (hot springs), making it a must-visit destination. The prefecture boasts stunning natural scenery, characterized by mountains and waterways, which are ideal for various outdoor activities. In winter, visitors can enjoy skiing, while warmer months offer opportunities for rafting and canyoning. The video guide includes highlights such as the Shorinzan Daruma Temple, Shima Onsen, Sekizenkan Ryokan, Agatsuma Gorge, and Ikaho Onsen, along with local dining options like Oyako-ten Udon. The content is designed for those looking to explore Tokyo and its surroundings affordably.' where id = 'FCqw0ZpvUEX3N-of2wvOH';
update content_bodies set title = '川越を発見：『古い東京』への日帰り旅行', description = '川越は「小江戸」として知られ、江戸時代（17世紀から19世紀）の雰囲気をよく保存しています。この日帰り旅行ガイドでは、氷川神社や新河岸川、象徴的な時の鐘などの主要な観光スポットを紹介しています。訪問者は、菓子屋横丁や蔵造りの街並みなどの伝統的な商店街を散策し、地元の美味しい料理や工芸品を体験できます。自分で箸を作ることもできるこのガイドは、エリアを効率的に移動するための実用的なヒントも提供し、歴史的な日本の本質を捉えた魅力的な町での充実した体験を保証します。' where id = 'hlzaKRpEjrN-K-em5ZQ0e';
update content_bodies set title = 'Discover Kawagoe: Day Trip to ‘Old Tokyo’', description = 'Kawagoe, known as ''Little Edo'', offers a glimpse into Japan''s Edo period (17th-19th century) with its well-preserved streets and buildings. This day trip guide highlights key attractions such as Hikawa Shrine, Shingashi River, and the iconic Toki no Kane bell tower. Visitors can explore traditional shopping streets like Kashiya Yokocho and Kurazukuri Street, where they can experience local delicacies and crafts, including making their own chopsticks. The guide also provides practical tips for navigating the area, ensuring a fulfilling experience in this charming town that captures the essence of historical Japan.' where id = 'P5618WqSwWpx2m2LumIpY';
update content_bodies set title = '東京・渋谷のおすすめカフェ8選', description = 'この記事では、東京・渋谷にあるおすすめのカフェ8軒を紹介しています。カフェは、リラックスした午後を過ごすのに最適な場所であり、小説を書いたり、人間観察をしたり、日本語を練習したりするのに適しています。内容は、各カフェを紹介する章立てがあり、日本での注意点についてのアドバイスも含まれています。また、東京をお得に楽しむための情報や、YouTubeチャンネルやSNSへのリンクも提供されています。' where id = 'W0vVvdjTUVgPv53sraelI';
update content_bodies set title = '8 Of The Best Cafes in Shibuya, Tokyo', description = 'This article highlights eight of the best cafes in Shibuya, Tokyo, perfect for enjoying a relaxing afternoon. Cafes are ideal for writing, people-watching, and practicing Japanese in a low-pressure setting. The content includes a detailed introduction and chapters that cover each cafe, along with tips for being cautious while in Japan. The article encourages readers to explore Tokyo on a budget and provides links to additional resources, including a YouTube channel and social media for more insights into Tokyo''s food and drink scene.' where id = 'QUZofXUULsqc0UOB0KTOw';
update content_bodies set title = '東京で無料の餃子はいかが？餃子処たちばなを訪問', description = 'この動画では、東京で無料の餃子を楽しむ機会を紹介し、餃子好きに人気のある餃子処たちばなを訪れる様子を特集しています。' where id = '56E0j9zYJv8MUq-Q7cEzF';
update content_bodies set title = 'Free gyoza in Tokyo anyone?', description = 'This video showcases a unique opportunity to enjoy free gyoza in Tokyo, specifically highlighting a visit to Gyoza Dokoro Tachibana, a popular spot for gyoza lovers.' where id = 'jv6XO3qM70NdyWvhk6ieh';
update content_bodies set title = 'なぜ東京の地元民が表参道を愛するのか - 地元の隠れた宝石', description = '表参道は東京の高級エリアであり、西洋と日本のデザイナーの高級店が立ち並んでいます。しかし、表参道はショッピングだけではありません。原宿のすぐ隣に位置し、素晴らしい建築、魅力的なブランチスポット、無料のアートギャラリーが揃っています。訪問者はこのエリアを散策し、隠れた宝石を見つけることを勧められています。隠れた抹茶スポットや神社、屋上庭園、ビーガンカフェなど、観光名所を超えた楽しみ方を提案するガイドが提供されており、東京でユニークな体験を求める地元民や観光客にとって必見の場所です。' where id = 'vL4_Sl3NlcpYkOGUUCF-A';
update content_bodies set title = 'Why Tokyo Locals Love Omotesando - A Local''s Hidden Gems', description = 'Omotesando is a luxurious area in Tokyo, known for its high-end Western and Japanese designer stores. However, it offers much more than just shopping. Located next to Harajuku, Omotesando features stunning architecture, delightful brunch spots, and free art galleries. Visitors are encouraged to explore the area and discover its hidden gems, including a secret matcha spot, a hidden shrine, rooftop gardens, and vegan cafes. The guide provides tips on how to enjoy Omotesando beyond the typical tourist attractions, making it a must-visit for both locals and tourists looking for a unique experience in Tokyo.' where id = 'w0Bw6BWTp0wAgkknQrdCO';
update content_bodies set title = 'はい、実際に高尾山から富士山を見ることができます', description = 'この動画では、高尾山から富士山を見ることができるという事実を紹介しています。高尾山からの眺望は美しく、富士山を望む特別な景観を楽しむことができます。' where id = 'dG1bEmHO6dbY94dIpj5zS';
update content_bodies set title = 'Yes, you can actually see Fuji from Mt. Takao', description = 'This video highlights the fact that Mount Fuji is visible from Mount Takao, showcasing the scenic beauty and the unique perspective offered by this location.' where id = 'Pu7SPosEmlw69_VC_t8Fe';
update content_bodies set title = '東京からの最高の日帰り旅行：高尾山ガイド', description = '高尾山は599メートルの高さを誇り、東京からの日帰り旅行に最適なスポットです。美しい景色、美味しい食べ物、賑やかな祭りが楽しめます。新宿駅から約1時間の距離にあり、カップルや家族、高齢者に人気です。登山を楽しむこともできますが、ロープウェイを利用すれば楽に山頂まで行けます。エリア内には薬王院や富士山の展望台などの観光名所があり、まんじゅうや団子などの地元のスナックを楽しむことができます。また、お土産や近くの温泉でのリラックスも可能です。このガイドでは、高尾山を訪れる際のポイントを紹介しています。' where id = 'zysEdkfKWP6WQuQPDrlIx';
update content_bodies set title = 'The Best Day Trip From Tokyo: Your Guide to Mount Takao', description = 'Mount Takao, standing at 599 meters, is a popular destination for day trips from Tokyo, offering breathtaking views, delicious food, and vibrant festivals. Located about an hour from Shinjuku Station, it is easily accessible for couples, families, and seniors. Visitors can hike to the summit or take a ropeway for a more leisurely ascent. The area features various attractions, including the Yakuoin Temple and viewpoints of Mount Fuji. The trip includes opportunities to enjoy local snacks like manju and dango, as well as options for souvenirs and relaxation at nearby onsens. This guide provides insights into making the most of your visit to this beloved mountain.' where id = 'h5dTCc6dj8GzanYwCCVcl';
update content_bodies set title = '東京の隠れたスポット、高円寺でできることは？', description = 'この動画では、東京の隠れたスポットである高円寺でのアクティビティや観光名所を紹介しています。高円寺の独特な文化や地元のショップ、活気ある雰囲気が、訪れる人々にとって特別な目的地となる理由を強調しています。' where id = 'WB5gL2pPYZ4gFWVkyGuJj';
