update content_bodies set title = '東京で行くべきでない場所はどこか？', description = 'この動画では、東京で訪れるべきでない場所について紹介しています。観光客にとって安全でない、興味がない、またはその他の理由で望ましくないエリアを強調し、視聴者が旅行の計画を立てる際に参考になる情報を提供しています。' where id = 'Va67qgBtoI6AviqEQJsR8';
