update content_bodies set title = '新千歳空港ガイド：交通、設備、宿泊', description = '新千歳空港は北海道最大の空港で、日本国内外からの旅行者が最も利用する空港です。札幌市の中心部からは直通の電車やバスで1時間以内、人気のスキーリゾート・ニセコからは2〜3時間の距離に位置しています。このガイドでは、空港の概要、国際線ターミナルと国内線ターミナルの詳細、ターミナル間の移動方法、チェックイン手続き、荷物配送、温泉や映画館などのユニークな設備について説明しています。また、プライベートタクシーや共有タクシー、公共交通機関、空港近くの宿泊施設についても触れています。' where id = '_fwLFze-1fkvjQiIfwn9F';
update content_bodies set title = 'New Chitose Airport Guide: Transport, Amenities & Accommodation', description = 'New Chitose Airport is the largest airport in Hokkaido, serving as a primary entry point for travelers from Japan and abroad. Located less than an hour from Sapporo, the capital of Hokkaido, and a few hours from the popular ski resort of Niseko, it offers convenient access to various destinations. The guide covers essential information, including an overview of the airport, details about the international and domestic terminals, transfer options between terminals, check-in procedures, baggage delivery, and unique amenities like an onsen and cinema. Additionally, it discusses transportation options such as private and shared taxis, public transport, and accommodation near the airport.' where id = 'UIPWGeLP8VTmfeFoyqnfQ';
update content_bodies set title = '日本旅行の危険 - 恐れを解きほぐす', description = 'この動画では、日本を訪れる旅行者が抱く一般的な恐れについて取り上げています。安全性、文化の違い、交通機関の利用に関する懸念など、10の具体的な恐れを紹介しています。動画では、情報を得て準備をすることが、安全で楽しい旅行を実現するために重要であると強調しています。また、日本での安全を確保するための旅行保険やヒントも提供しています。視聴者には、旅行のヒントや洞察を得るためにTokyo Cheapoを購読するよう促しています。' where id = 'GtfsM6eqLL9GA4ZL0R7et';
update content_bodies set title = 'The Dangers of Travelling in Japan - Unpacking Your Fears', description = 'This video addresses common fears travelers may have when visiting Japan. It covers ten specific fears, including concerns about safety, cultural differences, and navigating the transportation system. The video emphasizes the importance of being informed and prepared to ensure a safe and enjoyable trip. It also provides resources for travel insurance and tips for staying safe while exploring Japan. Viewers are encouraged to subscribe to Tokyo Cheapo for more travel tips and insights.' where id = 'dRRKp_7ick9JExeKNsbZi';
