update content_bodies set title = '東京のフリーマーケットで見つけられるもの', description = 'この動画では、東京のフリーマーケットで見つけられるさまざまなアイテムを紹介しています。ユニークで多様な商品が揃っている様子を強調し、視聴者に活気ある雰囲気とエクレクティックな商品群を垣間見せています。' where id = 'FohbDzLpdDyH6K1NSzy46';
update content_bodies set title = 'What You Can Find at a Tokyo Flea Market', description = 'This video showcases the various items available at a flea market in Tokyo. It highlights the unique and diverse offerings that can be discovered, providing viewers with a glimpse into the vibrant atmosphere and eclectic mix of goods.' where id = 'dhq4s-SOwRkjDsqAR0Djy';
update content_bodies set title = '2024年の富士山登山に役立つヒント', description = 'この動画では、2024年に富士山を登る予定の人々に向けて役立つヒントを紹介しています。登山体験を向上させるための重要な情報が含まれています。' where id = 'HorieXn8pYmxM-RfvEb_R';
