update content_bodies set title = 'Try this dagashi bar while you''re in #tokyo #japan #bars', description = 'This video showcases a dagashi bar that you should visit during your time in Tokyo, Japan.' where id = 'crjkkdWK90rcZrtLE6Moo';
update content_bodies set title = '隠れた名店：東京で絶対に試すべき4つのユニークなバー！', description = '東京には、地元の居酒屋からテーマ性のあるバーまで、さまざまな雰囲気や人々に合ったバーがあります。この動画では、東京の隠れた名店4軒を訪れ、オーナーと話しながら日本のスナックを楽しみ、飲みながら楽しいひとときを過ごします。紹介されるバーは、Not Suspicious Bar、Tokyo Video Gamers Bar、Tokyo Toy Cafe、Shinjuku Dagashi Barです。それぞれの場所はユニークな体験を提供し、東京の活気あるナイトライフを体感できます。視聴者は、詳細情報のためにリンクをチェックし、ホストのチャンネルをフォローすることが奨励されています。' where id = 'cOdpVGgPVX3vQMs60AFkY';
update content_bodies set title = 'Hidden Gems: 4 Unique Tokyo Bars You MUST Try!', description = 'Tokyo offers a diverse bar scene, catering to various tastes and atmospheres, from local izakayas to themed bars. This video explores four hidden gems in the city, featuring conversations with the bar owners and enjoying Japanese snacks and drinks. The bars highlighted include Not Suspicious Bar, Tokyo Video Gamers Bar, Tokyo Toy Cafe, and Shinjuku Dagashi Bar. Each location provides a unique experience, showcasing the vibrant nightlife of Tokyo. Viewers are encouraged to check out the links for more information and to follow the hosts on their respective channels.' where id = '_gsazXQkgQE67cHVAl2VH';
update content_bodies set title = 'マヨネーズファンはいませんか？ #日本 #キューピー #マヨ', description = 'この動画では、マヨネーズファンを紹介し、日本で人気のキューピーマヨネーズに焦点を当てています。' where id = 'm3K8d5DEasthV62jLEZdH';
update content_bodies set title = 'Mayo fan anyone? #japan #kewpie #mayo', description = 'This video showcases the enthusiasm of mayo fans and highlights Kewpie mayo, a popular brand in Japan.' where id = '3_RHe8fpBBy_YAP-V1cmJ';
update content_bodies set title = 'ジブリファン必見！リストに追加しよう。', description = 'この動画では、ジブリファンにおすすめのスポットを紹介しています。ジブリ作品を愛する人々にとって、訪れる価値のある場所や体験を提案しており、ファンにとっては見逃せない内容となっています。' where id = 'exoKuaMy8iwdaSDOxHcak';
update content_bodies set title = 'Ghibli fan? Add this to your list.', description = 'This video presents a recommendation specifically for fans of Studio Ghibli, suggesting an addition to their travel list. It highlights a location or experience that Ghibli enthusiasts would appreciate, making it a must-see for those who admire the studio''s work.' where id = 'E3wNufXwNfm5DYdMhNsoh';
update content_bodies set title = '東京ディズニーシー ハロウィンフードツアー 2024！', description = '2024年の東京ディズニーシーでのハロウィンフードとドリンクを楽しむツアーに参加しませんか？このツアーでは、ニューヨークデリのサンドイッチやデザート、ウォーターフロントフードトラックのフルーツドリンクやニョッキスナック、リバティランディングダイナーのハロウィンサンデー、カフェポルトフィーノのコーヒー風味のローストビーフなど、パーク内のさまざまな場所からの特別なメニューを紹介します。また、お気に入りの料理や東京ディズニーリゾートへの旅行計画のヒントもお伝えします。この動画は、ハロウィン期間中に楽しめる季節限定の美味しい食べ物を探しているファンにとって、貴重なリソースとなるでしょう。' where id = 'Ies-7FgQYyX5pElywqw65';
update content_bodies set title = 'Tokyo DisneySea Halloween Food Tour 2024!', description = 'Join me on a culinary adventure as I explore the Halloween-themed food and drinks at Tokyo DisneySea for 2024. The tour includes a variety of offerings from different locations within the park, such as sandwiches and desserts from New York Deli, fruit drinks and gnocchi snacks from Waterfront Food Trucks, and unique items like Halloween sundaes and coffee-scented roast beef. I will also highlight my favorite dishes and provide tips for planning your trip to Tokyo Disney Resort. This video is a great resource for fans looking to enjoy the seasonal treats available during Halloween at the park.' where id = '49VAajBzd69IvXqJmfRUt';
update content_bodies set title = '東京ディズニーランド：訪問前に知っておくべきこと', description = '東京ディズニーランドは、ディズニーファンにとって必見のスポットで、アクセスも簡単です。東京ディズニーリゾートの2つのパークのうちの1つで、もう1つは世界で唯一の東京ディズニーシーです。この動画では、訪問者に必要な情報を提供しており、交通手段、チケット購入、宿泊オプションなどをカバーし、魔法のような体験を確実にするための準備を手助けします。' where id = 'JyST-O6fs0jM6_uHvcPBb';
update content_bodies set title = 'Tokyo Disneyland: Everything to Know Before Visiting', description = 'Tokyo Disneyland is a must-visit for Disney fans and is easily accessible. It is one of two parks in the Tokyo Disney Resort, the other being Tokyo DisneySea, which is unique in the world. This video provides essential information for visitors, including transportation options, ticket purchasing, and accommodation choices, ensuring a magical experience at this iconic destination.' where id = 'cJV0C9plAHCWAX70aJMhH';
update content_bodies set title = '東京で好きな空港はどこですか？', description = 'この動画では、東京の好きな空港について紹介しています。視聴者に自分の好みを共有するよう促しています。' where id = '9VfHZsRgPx6h8xMwFzZCd';
