update content_bodies set title = 'GEO MIRACLE KOBE～FOOD～', description = 'この動画では、GEO MIRACLE KOBEの食に関する情報を紹介しています。具体的な料理やメニューの内容については触れられていませんが、GEO MIRACLE KOBEの食文化や特色を知ることができる内容となっています。食に関心がある方にとって、興味深い視点を提供する動画です。' where id = 'd-25EMgzDrT64AIJbLF0A';
