update content_bodies set title = '【大自然4K】「仙酔峡」高画質 癒し映像', description = '『SCENE of the ASO』シリーズの第9巻は「仙酔峡」を特集しています。仙酔峡は、阿蘇中岳と高岳の北麓に位置する標高約900mの渓谷で、自然豊かな阿蘇の風景を4Kカメラで撮影しています。涼しげな水の映像を楽しむことができる癒しの映像です。' where id = 'Lf8VK-BCdp1I6RLX7Zrv-';
update content_bodies set title = 'Nature in 4K: ''Sensuikyo'' High-Quality Healing Footage', description = 'This is the ninth volume of the series ''SCENE of the ASO,'' showcasing the rich natural landscapes of Aso captured in 4K. ''Sensuikyo'' is a gorge located at an elevation of approximately 900 meters, nestled at the northern foot of Mount Nakadake and Mount Takadake. Enjoy the refreshing visuals of flowing water in this serene setting.' where id = 'YLWj7gnn71TCOUiQeq5dM';
update content_bodies set title = '神戸の喜びを見つける', description = 'この文章では、神戸の魅力を体験するためのさまざまな施設や個人に感謝の意を表しています。Bar & Bistro 64、AMPLOP、LIMA COFFEE、六甲牧場カフェ乙仲通り、神戸ベイクルーズロイヤルプリンセスに特別な感謝が述べられています。また、YouTubeやFacebookで活動する蔡祥さんとYujiさんがキャストとして紹介されています。各リンクはそれぞれのウェブサイトやソーシャルメディアのプロフィールに繋がっており、神戸での活気あるコミュニティや体験を示しています。' where id = 'f26_LmSilBDF8SthzmVxF';
update content_bodies set title = 'Find the JOY in KOBE', description = 'This text highlights various establishments and individuals contributing to the joy of experiencing Kobe. It includes special thanks to Bar & Bistro 64, AMPLOP, LIMA COFFEE, and Rokko Farm Café Otsunaka, as well as the Kobe Bay Cruise Royal Princess. Additionally, it features cast members such as 蔡祥, who can be found on YouTube and Facebook, and Yuji, also active on YouTube and Facebook. Each link provided directs to their respective websites or social media profiles, showcasing the vibrant community and experiences available in Kobe.' where id = 'WQ0rBtYcxQDoCBLDd3gVj';
update content_bodies set title = '新魅力新神戶　～一起去看見神戶的「新」～', description = '神戶は伝統と新潮が融合した都市であり、多くの観光スポットが存在します。さらに、新しい施設や店舗が次々と登場しています。神戸の新しい魅力を探し、これまで見たことのない新しい神戸を発見してみましょう。' where id = 'HpXirCGaj2s4I10lIhqEN';
update content_bodies set title = 'New Attractions in Kobe - Discover the ''New'' Kobe', description = 'Kobe is a city that blends tradition with modernity, offering numerous tourist attractions alongside a continuous influx of new facilities and shops. Explore the new charms of Kobe and discover a side of the city you have never seen before.' where id = 'I-YF18v__lYnckox0-WO1';
update content_bodies set title = '新魅力新神戶　～一起去看見神戶的「新」～', description = '神戶は伝統と新潮が融合した都市であり、多くの観光スポットが存在するだけでなく、新しい施設や店舗も次々と登場しています。神戸の新しい魅力を探し、これまで見たことのない新しい神戸を発見してみましょう。' where id = '6m0HlIx0JbH6f5HVbMsmS';
update content_bodies set title = 'New Attractions in Kobe - Discover the ''New'' Kobe', description = 'Kobe is a city that blends tradition with modernity, offering numerous tourist attractions alongside a continuous emergence of new facilities and shops. Explore the new charms of Kobe and discover a side of the city you have never seen before.' where id = '4xDocDUqm_sNgL1Cm9kRH';
update content_bodies set title = '関西日本 ～ 大阪、堺、神戸、姫路、高野山 ～', description = '日本には訪れる価値のある多くの場所があります。この動画では、関西地方の魅力的なスポットをいくつか紹介しています。歴史的な場所や世界遺産、文化的な伝統、食などが含まれています。特に神戸、大阪、堺、姫路、高野山の5つの場所を取り上げており、日本を訪れる際にはこれらの地域を巡ることが必須です。この動画が次回の日本旅行のインスピレーションとなることを願っています。' where id = 'sXA1oElmJRX1_8Lomuo8S';
update content_bodies set title = 'Kansai Japan ~ Osaka, Sakai, Kobe, Himeji, Koyasan ~', description = 'This video showcases some of the most attractive destinations in the Kansai region of Japan, highlighting historic sites, World Heritage locations, cultural traditions, and local cuisine. The featured places include Kobe, Osaka, Sakai, Himeji, and Koyasan, all of which are essential stops for anyone visiting Japan. The video aims to inspire viewers to explore these remarkable areas during their travels.' where id = 'vO-HUv72fXNqmkdtVThCb';
update content_bodies set title = '関西日本 ～ 大阪、堺、高野山 ～', description = 'この動画では、日本の関西地域にある訪れる価値のある魅力的なスポットを紹介しています。歴史的な場所や世界遺産、文化的な伝統、食文化などが取り上げられています。特に、神戸、大阪、堺、姫路、高野山の5つの場所が選ばれており、日本を訪れる際にはこれらの地域を巡ることが必須であることが強調されています。この動画が次回の日本旅行のインスピレーションとなることを願っています。' where id = 'guWyw3eACLM1ci8fcHyPX';
update content_bodies set title = 'Kansai Japan ~ Osaka, Sakai, Koyasan ~', description = 'This video showcases some of the most attractive destinations in the Kansai region of Japan, highlighting historic sites, World Heritage locations, cultural traditions, and local cuisine. It features five key places: Kobe, Osaka, Sakai, Himeji, and Koyasan, emphasizing their significance for travelers. The video aims to inspire viewers to explore these areas during their visit to Japan.' where id = 'eMYB_IaYjnwhpIQbKqflC';
update content_bodies set title = '関西日本 ～ 大阪、神戸、姫路 ～', description = 'この動画では、日本の関西地域にある訪れる価値のある魅力的なスポットを紹介しています。歴史的な場所や世界遺産、文化的な伝統、食文化などが取り上げられています。特に神戸、大阪、堺、姫路、そして高野山の5つの場所が選ばれており、日本を訪れる際にはこれらの地域を巡ることが必須であることが強調されています。この動画が次回の日本旅行のインスピレーションとなることを願っています。' where id = 'bAXUv_kwMSWuv6W7LMxjO';
update content_bodies set title = 'Kansai Japan ~ Osaka, Kobe, Himeji ~', description = 'This video showcases some of the most attractive destinations in the Kansai region of Japan, highlighting historic sites, World Heritage locations, cultural traditions, and local cuisine. It features five key places: Kobe, Osaka, Sakai, Himeji, and Koyasan, emphasizing their significance for travelers. The video aims to inspire viewers to explore these areas during their visit to Japan.' where id = '3zQHQpWl32ORYP2_Y8pms';
update content_bodies set title = '関西日本 ～大阪、堺、神戸、姫路、高野山～［30秒版］', description = 'この動画では、日本の関西地域にある魅力的な観光地を紹介しています。歴史的な場所や世界遺産、文化的な伝統、食文化などが取り上げられています。特に神戸、大阪、堺、姫路、高野山の5つの場所が選ばれており、日本を訪れる際にはこれらの地域を巡ることが必須であると強調されています。この動画が次回の日本旅行のインスピレーションとなることを願っています。' where id = 'BXbOIxAs4i70FLQAfHyXz';
update content_bodies set title = 'Kansai Japan ~Osaka, Sakai, Kobe, Himeji, Koyasan~ [30 seconds ver.]', description = 'This video showcases some of the most attractive destinations in the Kansai region of Japan, highlighting historic sites, World Heritage locations, cultural traditions, and local cuisine. It features five key places: Kobe, Osaka, Sakai, Himeji, and Koyasan, emphasizing that these areas are essential stops for anyone visiting Japan. The video aims to inspire viewers to plan their next trip to Japan.' where id = 'Lzoh3_lBrAtD5veq336Is';
update content_bodies set title = '今だけ！愛媛をお得に旅行できる「ぐるっとえひめ旅」', description = '愛媛県への旅行者を対象にした「ぐるっとえひめ旅」のプロモーション動画です。このプランでは、バスや船、タクシーを利用して、愛媛ならではの周遊プランを楽しむことができます。愛媛の魅力を詰め込んだ様々なコースが用意されており、この機会にぜひ愛媛を満喫してください。担当課は観光国際課です。' where id = 'r78BR2lkadhj-BUVHc2sF';
update content_bodies set title = 'Limited Time! Enjoy Affordable Travel in Ehime with ''Gurutto Ehime Tabi''', description = 'This promotional video introduces ''Gurutto Ehime Tabi,'' a travel plan for visitors to Ehime Prefecture that allows them to enjoy unique tours using buses, boats, and taxis. Various courses packed with the charm of Ehime are available, so take this opportunity to fully experience what Ehime has to offer.' where id = 'lKh8yyCxfH6WHM5ASQQQ3';
update content_bodies set title = '酒の國いわて ～南部杜氏の郷～', description = 'およそ400年前、近江商人が清酒の醸造技術をこの地に持ち込み、本格的な酒造りが始まったと言われています。盛岡地域には昔ながらの趣ある９つの酒蔵が集まり、南部杜氏の伝統の技を活かしながら、新しい酒造りへの努力と挑戦が続けられています。杜氏や蔵人たちの情熱と愛情に溢れる岩手の酒造りを体験し、岩手のお酒で乾杯しましょう。ようこそ、酒の國いわてへ！' where id = 'mBfnhQqQBvEOkSWdfkwfQ';
update content_bodies set title = 'The Land of Sake Iwate - Home of Nanbu Toji', description = 'Approximately 400 years ago, it is said that merchants from Omi brought sake brewing techniques to this region, marking the beginning of authentic sake production. The Morioka area is home to nine traditional sake breweries, where the time-honored skills of Nanbu Toji are preserved. These breweries continue to strive for innovation in sake making while honoring their heritage. Experience the passion and dedication of the brewers and craftsmen in Iwate''s sake production. Let''s raise a glass with Iwate''s sake. Welcome to the Land of Sake Iwate!' where id = 'e31Y4xOm_1bMc5WnCiXVH';
update content_bodies set title = '神戸は、地球だ。～ダイジェスト編～ 【神戸で海外旅行 キャンペーン動画】', description = 'この観光PR動画は、神戸が日本にいながら海外旅行の魅力を体験できる街であることを紹介しています。アメリカの文化の深さ、ヨーロッパの歴史からの学び、アジアの料理の活力など、神戸には多様な文化的影響が詰まっています。動画では、神戸が心の充電器のような存在であることを示唆し、訪れる人々が一つの場所でグローバルな体験を楽しめることを伝えています。また、地域ごとのテーマを探るためのリンク動画や、神戸旅行の計画に役立つリソースも提供されています。' where id = 'SyHIB4y5hSh2D8HEsf-2i';
update content_bodies set title = 'Kobe is the Earth. - Digest Edition - [Kobe Overseas Travel Campaign Video]', description = 'This promotional video showcases Kobe as a city where you can experience the essence of international travel without leaving Japan. It highlights the diverse cultural influences found in Kobe, such as the depth of American culture, the lessons from European history, and the vitality of Asian cuisine. The video suggests that Kobe serves as a ''charger'' for the soul, allowing visitors to enjoy a global experience in one location. It invites viewers to explore various regional themes through linked videos and provides resources for planning a trip to Kobe.' where id = '7lkn-2lSTJKpTD6CflmOr';
update content_bodies set title = '酒の國いわて ～南部杜氏の郷～', description = '約400年前、近江商人が清酒の醸造技術をこの地に持ち込み、本格的な酒造りが始まったとされています。盛岡地域には、昔ながらの趣のある9つの酒蔵が集まり、南部杜氏の伝統技術が受け継がれています。これらの酒蔵は、新しい酒造りへの挑戦を続けており、杜氏や蔵人たちの情熱と愛情が込められた岩手の酒造りを体験できます。岩手のお酒で乾杯しましょう。ようこそ、酒の國いわてへ！' where id = 'v5R5L0CxtgPHFWJ89TsUk';
update content_bodies set title = 'The Land of Sake Iwate - Home of Nanbu Toji', description = 'Approximately 400 years ago, it is said that merchants from Omi brought sake brewing techniques to this region, marking the beginning of authentic sake production. The Morioka area is home to nine traditional sake breweries, where the time-honored skills of Nanbu Toji are preserved. These breweries continue to strive for innovation and excellence in sake making. Experience the passion and dedication of the toji (master brewers) and kurabito (brewery workers) in Iwate''s sake production. Let''s raise a glass with Iwate''s sake. Welcome to the Land of Sake Iwate!' where id = 'CAEVUXT41dXlsckjc_2DG';
update content_bodies set title = '神戸ゴルフ旅 プロモーション動画', description = 'プロゴルファーの竹内美雪さんと共に神戸を巡るゴルフ旅を紹介するプロモーション動画です。神戸の魅力を感じながら、ゴルフを楽しむ様子が描かれています。詳細は神戸公式観光サイト「FeelKOBE」をご覧ください。また、神戸&三木編の動画もYouTubeで視聴できます。' where id = 'qB9KOr67nzIFzTq54AbJY';
update content_bodies set title = 'Kobe Golf Trip Promotional Video', description = 'Join professional golfer Miyuki Takeuchi on a golf journey in Kobe. For more information, visit the official Kobe tourism site ''FeelKOBE'' or check out the Kobe & Miki edition on YouTube.' where id = 'pvdJB4b5bfrOs9dxXJQeU';
update content_bodies set title = '神戸&三木ゴルフ旅', description = '日本のゴルフ発祥の地である神戸と、西日本で最多のゴルフ場を有する三木を巡るゴルフツーリズムのプロモーション動画です。両市はゴルフだけでなく、観光地も豊富に揃っており、訪れる人々に多様な楽しみを提供します。' where id = 'xqiHdXX9GDPFGQd9HtxtY';
update content_bodies set title = 'Kobe Golf Trip', description = 'This promotional video showcases a golf tourism experience in Kobe, the birthplace of golf in Japan, and Miki, a city with the highest number of golf courses in Western Japan. Both cities offer a rich variety of attractions that can be enjoyed alongside golfing.' where id = '7caffN_btTCU4vmV6inCC';
update content_bodies set title = 'KOBE FOR ALL SENSES ~Taste~', description = 'このコンテンツでは、神戸の観光スポットを紹介し、特に食文化に焦点を当てています。訪れる人々は、神戸の文化や伝統を反映した多様な地元の美味しい料理や独特の味を楽しむことができます。食べることと楽しむことが、神戸の活気ある街での旅行体験において重要な要素であることを強調しています。' where id = 'rBchA8r_Vu4KRRP0afZxe';
update content_bodies set title = 'KOBE FOR ALL SENSES ~Taste~', description = 'This content introduces various sightseeing spots in Kobe, focusing on the culinary experiences the city has to offer. Visitors can explore a range of local delicacies and unique flavors that reflect the culture and heritage of Kobe. The emphasis is on tasting and enjoying the diverse food scene, making it an essential part of the travel experience in this vibrant city.' where id = 'izCV4-ImK9ORBeUGCoKMm';
update content_bodies set title = 'KOBE FOR ALL SENSES ~Touch~', description = 'この取り組みは、神戸の観光スポットを紹介し、触覚に焦点を当てています。訪れる人々は、触れることで体験できるユニークな場所を探索し、神戸の魅力をより深く楽しむことができます。' where id = 'jffnGPcvJwT9LWJ7MyDvt';
update content_bodies set title = 'KOBE FOR ALL SENSES ~Touch~', description = 'This initiative introduces various sightseeing spots in Kobe, focusing on the sense of touch. Visitors can explore unique experiences that engage their tactile senses, enhancing their overall enjoyment of the city.' where id = 'IzxLAjF0zlxvxgtSZGl8T';
update content_bodies set title = 'KOBE FOR ALL SENSES ~Sight~', description = 'この文章では、神戸の観光スポットを紹介しています。特に視覚的な体験に焦点を当てており、神戸で見ることができる美しさや魅力を強調しています。訪問者に神戸の景観を探求し、楽しむことを促しています。' where id = 'ULf48ulQJ-2zvSZJGyZFS';
update content_bodies set title = 'KOBE FOR ALL SENSES ~Sight~', description = 'This text introduces various sightseeing spots in Kobe, focusing specifically on visual experiences. It highlights the beauty and attractions that can be seen in the city, encouraging visitors to explore and appreciate the sights that Kobe has to offer.' where id = 'UIcvXvFKBYtgA2GdZ6qEF';
update content_bodies set title = 'KOBE FOR ALL SENSES ~Nature~', description = 'この文章では、神戸の観光スポットを紹介しています。特に自然の美しさに焦点を当てており、訪れる人々が楽しめる独特の風景やアウトドア体験について述べています。' where id = 'ZRI9lKH1xNIQ2EKaOR4ge';
update content_bodies set title = 'KOBE FOR ALL SENSES ~Nature~', description = 'This text introduces various sightseeing spots in Kobe, focusing on the natural beauty of the area. It highlights the unique landscapes and outdoor experiences that visitors can enjoy while exploring the city.' where id = 'DfzWUgPHLpuKGkkpxAkLS';
update content_bodies set title = '酒の國いわて ～南部杜氏の郷～', description = '約400年前、近江商人がこの地に清酒の醸造技術を持ち込み、本格的な酒造りが始まりました。盛岡地域には、昔ながらの趣を持つ9つの酒蔵が集まり、南部杜氏の伝統技術が受け継がれています。これらの酒蔵は、新しい酒造りへの挑戦を続けており、杜氏や蔵人たちの情熱と愛情が込められた岩手の酒造りを体験できます。岩手のお酒で乾杯しましょう。ようこそ、酒の國いわてへ！' where id = 'a5pzdgbVTNKGYEKhXn_Ly';
update content_bodies set title = 'The Land of Sake Iwate - Home of Nanbu Toji', description = 'Approximately 400 years ago, merchants from Omi brought sake brewing techniques to this region, marking the beginning of authentic sake production. The Morioka area is home to nine traditional sake breweries, where the time-honored skills of Nanbu Toji are preserved. These breweries continue to strive for innovation and excellence in sake making. Experience the passion and dedication of the toji (master brewers) and kurabito (brewery workers) in Iwate''s sake production. Let''s raise a glass with Iwate''s sake. Welcome to the Land of Sake Iwate!' where id = 'suiOYPIpu5jucif7Mo_m9';
update content_bodies set title = 'いわて短角牛の郷－夏山の風景－', description = 'いわて短角牛は、国内で流通する牛肉の中でわずか0.4％未満を占める幻の和牛『日本短角種』です。岩手県はこの短角種の発祥地であり、最大の産地とされています。春から秋にかけて、母子ともに放牧地で過ごす「夏山冬里方式」で育てられます。生後約半年間は母牛と共に過ごし、その後は牛舎で肥育され、美味しいお肉として提供されます。雄大な自然に囲まれた夏山の風景をぜひご覧ください。' where id = '5GKSVGt-LQ0jKSg6XCsDs';
update content_bodies set title = 'Iwate Short-Horned Cattle - Summer Mountain Scenery', description = 'Iwate Short-Horned Cattle, known as the elusive Japanese breed ''Nihon Tankaku'', accounts for less than 0.4% of beef distributed in Japan. Iwate Prefecture is recognized as the birthplace and the largest production area of this breed. The ''Summer Mountain and Winter Village'' method allows the cattle to live in pastures with their mothers from spring to autumn. After spending about six months in the pasture, they are raised in barns as beef cattle, ultimately providing delicious meat to consumers. Experience the majestic natural scenery of the summer mountains.' where id = 'bK0swYUywlYjQ8pRZirHS';
update content_bodies set title = '六甲山へ行こう', description = '緑豊かな大自然、美しい夜景、歴史的な旧跡、現代アートの展覧会、トレッキングなどのスポーツを楽しめる六甲山・摩耶山へ出かけてみませんか？自然を愛する人や冒険を求める人にとって、さまざまな体験が待っています。' where id = 'Dqd3h1K5m14GFqJPD6xuA';
update content_bodies set title = 'Let''s go to Mt Rokko', description = 'Visit Mt. Rokko and Mt. Maya to experience the lush greenery of nature, stunning views, historic sites, modern art exhibitions, and activities like trekking. These mountains offer a variety of experiences for nature lovers and adventure seekers alike.' where id = 'f8Rnyt_e408bArJd7ohcH';
update content_bodies set title = '夜たび神戸～六甲山ダイジェスト', description = 'この動画では、神戸の夜の楽しみ方を紹介しています。六甲山は「1000万ドルの夜景」で知られる神戸の代表的な夜景スポットです。ケーブルカーで山頂に登ると、眼下に広がる煌く街の景色を楽しむことができます。' where id = 'uLV9yRtOZn76Y8AJ_3QK0';
update content_bodies set title = 'Night in Kobe - Mt. Rokko Digest', description = 'This video introduces how to enjoy the night in Kobe, featuring Mt. Rokko, a famous night view spot known for its ''ten-million-dollar night view.'' Visitors can take a cable car to the top of the mountain and enjoy the stunning view of the sparkling city below.' where id = 'DEBCcDX2eNLk63Sxo7wca';
update content_bodies set title = '夜たび神戸～有馬温泉ダイジェスト', description = 'この動画では神戸の夜の楽しみ方を紹介しています。特に、日本三古泉の一つである有馬温泉の魅力に焦点を当てています。視聴者は浴衣を着て、風情ある温泉街を散策し、その独特の雰囲気を体験することが奨励されています。' where id = 'MnAZEEWoFM5YTQBstyDLo';
update content_bodies set title = 'Night in Kobe - Arima Onsen Digest', description = 'This video introduces how to enjoy the night in Kobe. It highlights the charm of Arima Onsen, one of Japan''s three oldest and most famous hot springs. Viewers are encouraged to wear Yukata and take evening strolls through the picturesque hot spring town, experiencing its unique atmosphere.' where id = 'TFw35K3eIyWZOrfUy_OgJ';
update content_bodies set title = '夜たび神戸～ハーバーランドダイジェスト', description = 'この動画では、神戸の夜の楽しみ方を紹介しています。ハーバーランドは、食事や買い物など、エンターテインメント要素が豊富に揃ったエリアです。港町神戸を代表する景色を、クルーズ船で海から眺めることができるのも魅力の一つです。' where id = '9Sjk4oYT03xP-WZYbInEa';
update content_bodies set title = 'Night in Kobe - Harborland Digest', description = 'This video introduces how to enjoy the night in Kobe. Harborland is a vibrant area that offers a variety of entertainment options, including dining and shopping. Visitors can experience the iconic scenery of Kobe, a port town, by taking a cruise ship to view the sights from the sea.' where id = 'Pk412mF_6IY5S9Wdlyko4';
update content_bodies set title = '夜たび神戸～メリケンパークダイジェスト', description = 'この動画では神戸の夜の楽しみ方を紹介しています。神戸港開港150年を記念してリニューアルされたメリケンパークが舞台です。特に人気のモニュメント「BE KOBE」は、訪れる人々にフォトジェニックな雰囲気を提供します。神戸の観光情報は公式サイトやFacebookページで確認できます。' where id = 'qcX5TgHESTKcFdDAZEocp';
update content_bodies set title = 'Night in Kobe - Meriken Park Digest', description = 'This video introduces how to enjoy the night in Kobe. It features Meriken Park, which was renovated to celebrate the 150th anniversary of the opening of Kobe Port. The park includes the popular monument ''BE KOBE,'' which creates a photogenic atmosphere for visitors. For more information, you can visit the tourism website of Kobe or check out their Facebook page.' where id = '6S5PHDDfSZ2hedBq9_rcM';
update content_bodies set title = '夜たび神戸～有馬温泉前編', description = 'この動画では神戸の夜の楽しみ方を紹介しています。日本三古泉・三名泉として知られる有馬温泉が登場し、浴衣を着て風情ある温泉街を散策することを勧めています。' where id = 'im82TVFvr0wKmEZbHfCoA';
update content_bodies set title = 'Night Trip in Kobe - Arima Onsen Part 1', description = 'This video introduces how to enjoy the night in Kobe. It features Arima Onsen, one of Japan''s three oldest and most famous hot springs. Viewers are encouraged to wear yukata and take an evening stroll through the charming hot spring town.' where id = 'NhDsCBJTyu2TPBuPiUPtn';
update content_bodies set title = '夜たび神戸～有馬温泉後編', description = '神戸の夜の楽しみ方を紹介する動画です。有馬温泉は日本三古泉・三名泉として知られ、夜には浴衣を着て風情ある温泉街を散策することができます。美しい景色を楽しみながら、リラックスしたひとときを過ごせる場所です。' where id = 'jdiHu84Ti16qO689D2gyD';
update content_bodies set title = 'Night Trip in Kobe - Arima Onsen Part 2', description = 'This video introduces how to enjoy the night in Kobe. Arima Onsen, known as one of Japan''s three oldest and most famous hot springs, offers a charming atmosphere. Visitors can stroll through the picturesque hot spring town wearing Yukata in the evening.' where id = 'qA8PHaARFF_cDJlH7E5Uj';
update content_bodies set title = '夜たび神戸～有馬温泉グルメ編', description = '神戸の夜の楽しみ方を紹介する動画です。有馬温泉は日本三古泉・三名泉として知られ、風情ある温泉街を浴衣を着て散策することができます。夜の雰囲気を楽しみながら、温泉街の魅力を堪能してください。' where id = 'wvY1Ugug6yFsXSJ7N6hDd';
update content_bodies set title = 'Night Trip in Kobe - Arima Onsen Gourmet Edition', description = 'This video introduces how to enjoy the night in Kobe. Arima Onsen, known as one of Japan''s three oldest and most famous hot springs, offers a charming atmosphere. Visitors can stroll through the picturesque hot spring town wearing Yukata in the evening.' where id = 'T7gVA6RF396lX-qfdZsCW';
