update content_bodies set title = 'Night Trip in Kobe - Mt. Rokko Part 1', description = 'This video introduces how to enjoy the night in Kobe. Mt. Rokko, known for its ''ten-million-dollar night view,'' is a representative night view spot in Kobe. After taking the cable car to the top of the mountain, be sure to enjoy the stunning view of the sparkling city below.' where id = 'kLvWrNz-JQ59AnvzFSBq_';
update content_bodies set title = '夜たび神戸～六甲山後編', description = '神戸の夜の楽しみ方を紹介する動画です。六甲山は「1000万ドルの夜景」で有名な神戸の代表的な夜景スポットです。ケーブルカーで山上に登ると、眼下に広がる煌く街の景色を楽しむことができます。' where id = 'rO7LsE436WV5iwGewkdUS';
update content_bodies set title = 'Night Trip in Kobe - Mt. Rokko Part 2', description = 'This video introduces how to enjoy the night in Kobe. Mt. Rokko, known for its ''ten-million-dollar night view,'' is a representative night view spot in Kobe. After taking the cable car to the top of the mountain, be sure to enjoy the stunning view of the sparkling city below.' where id = 'MR6n8CAQfaAsxavRU_7ba';
update content_bodies set title = '夜たび神戸～六甲山風景編', description = '神戸の夜の楽しみ方を紹介する動画です。六甲山は、1000万ドルの夜景で有名な神戸の代表的な夜景スポットです。ケーブルカーで山上に登ると、眼下に広がる煌く街の景色を楽しむことができます。' where id = 'jUpDagHVl4HVnJtd6Sj-Q';
update content_bodies set title = 'Night Trip in Kobe - Mt. Rokko Scenery Edition', description = 'This video introduces how to enjoy the night in Kobe. Mt. Rokko is a representative night view spot in Kobe, famous for its ''ten-million-dollar night view.'' After taking the cable car to the top of the mountain, be sure to enjoy the stunning view of the sparkling city below.' where id = 'h9UmSkOfl0wP0FVvJKLoS';
update content_bodies set title = 'いわて短角牛の郷－平庭闘牛－', description = 'いわて短角牛は、国内で流通する牛肉の中でわずか0.4％未満を占める幻の和牛『日本短角種』であり、岩手県はその発祥地であり最大の産地です。岩手県久慈市では、東北地方唯一の闘牛大会が開催されています。この伝統は江戸時代に遡り、沿岸部で生産された塩を内陸に運ぶ際、先頭の牛を決めるために角突きを行ったことが起源とされています。現在の観光行事としての形態は昭和58年から始まりました。南部牛は明治時代に海外品種との交配が行われ、昭和32年に日本短角種として品種登録されました。' where id = 'qDaM_0aPAX77QrHCW4ozM';
update content_bodies set title = 'Iwate Short-Horned Cattle - Hiraniwa Bullfighting', description = 'Iwate Short-Horned Cattle, known as ''Nihon Tankaku-shu'', is a rare breed of Japanese beef, accounting for less than 0.4% of the beef market in Japan. Iwate Prefecture is recognized as the birthplace and the largest production area of this breed. In Kuji City, Iwate, the only bullfighting event in the Tohoku region is held. The tradition dates back to the Edo period when salt produced in the coastal areas was transported inland using local ''Nanbu Cattle''. Bullfighting began as a way to determine the lead bull in these transport teams. The event was formalized as a tourist attraction in 1983. The Nanbu Cattle breed was crossbred with foreign breeds after Japan opened to the world in the Meiji era, leading to the registration of the Nihon Tankaku-shu as the fourth Japanese beef breed in 1957.' where id = '35SWA2OHXjNydQrjGF79L';
update content_bodies set title = '夜たび神戸～ハーバーランドデート編', description = '神戸の夜の楽しみ方を紹介する動画です。ハーバーランドは、食事や買い物、エンターテインメントが揃ったデートに最適なスポットです。クルーズ船に乗って海から神戸の代表的な景色を楽しむことができます。' where id = 'ipWXkcgl0hFFzuqcVQrjD';
update content_bodies set title = 'Night Trip in Kobe - Harborland Date Edition', description = 'This video introduces how to enjoy the night in Kobe. Harborland is a perfect spot for a date, offering a variety of dining, shopping, and entertainment options. Visitors can experience the iconic scenery of Kobe, a port town, by taking a cruise ship to view the city from the sea.' where id = 'j2YaDlIEwoCymaS5RjdRD';
update content_bodies set title = '夜たび神戸～メリケンパークショート編', description = '神戸の夜の楽しみ方を紹介する動画です。神戸港開港150年を記念してリニューアルされたメリケンパークでは、大人気のモニュメント「BE KOBE」があり、夜のフォトジェニックな雰囲気を演出しています。' where id = 'm6Y0V73HlxeFZ_ep0olqQ';
update content_bodies set title = 'Night Trip in Kobe - Meriken Park Short Edition', description = 'This video introduces how to enjoy the night in Kobe. Meriken Park, renovated for the 150th anniversary of the opening of Kobe Port, features the popular monument ''BE KOBE,'' which creates a photogenic atmosphere at night.' where id = 'KeQ-KwFpJZuYWL-v0hgn1';
update content_bodies set title = '夜たび神戸～メリケンパークデート編', description = 'この動画では神戸の夜の楽しみ方を紹介しています。メリケンパークは神戸港開港150年を記念してリニューアルされ、人気のモニュメント「BE KOBE」があり、ロマンチックな夜を演出するフォトジェニックなスポットとなっています。' where id = 'JI2eH2LzhmzKn2ApMl-aW';
update content_bodies set title = 'Night Trip in Kobe - Meriken Park Date Edition', description = 'This video introduces how to enjoy the night in Kobe. It features Meriken Park, which was renovated to celebrate the 150th anniversary of the opening of Kobe Port. The park is home to the popular monument ''BE KOBE,'' which provides a photogenic backdrop for a romantic evening.' where id = '90T_uo2mZn3oGiU1UryGY';
update content_bodies set title = '夜たび神戸～神戸夜グルメ編', description = 'この動画では、神戸の夜の楽しみ方を紹介しています。神戸ビーフ、神戸スイーツ、灘の酒など、世界を魅了する神戸のグルメが登場します。夜の神戸で、心もお腹も満たされる美味しい体験をお楽しみください。' where id = 'bG5Nr3WXeK7M5egkUvYGj';
update content_bodies set title = 'Night Trip in Kobe - Night Gourmet Edition', description = 'This video introduces how to enjoy the night in Kobe. It showcases the captivating food scene, including Kobe Beef, Kobe Sweets, and Nada Sake, which enchant the world. Experience the culinary delights of Kobe at night, satisfying both your stomach and heart.' where id = 'y-wEy_hI9lm5aUHv79keL';
update content_bodies set title = '神戸夜探検 DAY3 短縮版', description = 'フランスと台湾からのカップルが神戸のユニークなスポットを探訪します。2日目は有馬温泉を特集し、伝統的な旅館で本物のホスピタリティを体験しながらリラックスします。この旅は神戸の夜の独特な魅力を紹介します。' where id = '9tuaKx37D2cpgqlGJ3A06';
update content_bodies set title = 'Night Exploring in KOBE DAY3 Short Version', description = 'Join a couple from France and Taiwan as they explore unique spots in KOBE. Day 2 highlights include a visit to Arima Onsen, where they experience the traditional hospitality of a ryokan. This journey showcases the distinctive charm of KOBE at night.' where id = 'QGPz692ASvcTCwxylQMaz';
update content_bodies set title = '神戸の夜探検 DAY2 短縮版', description = 'フランスと台湾からのカップルが神戸のユニークなスポットを探訪する様子をお楽しみください。2日目のハイライトは、レジャースポットとして有名な六甲山です。六甲ケーブルカーに乗って絶景を楽しみ、カフェでコーヒーを一杯味わうことができます。その後、カジュアルな立ち飲みバーに立ち寄って地元の日本酒を試すことをお勧めします。神戸での特別な夜をお楽しみください。' where id = 'x0U-jTWI95qtKSWzRH1vQ';
update content_bodies set title = 'Night Exploring in KOBE DAY2 Short Version', description = 'Join a couple from France and Taiwan as they explore unique spots in KOBE on Day 2. The highlight is Mt. Rokko, a popular leisure destination. Visitors can take the Rokko Cable Car to enjoy stunning views and relax with a cup of coffee at a café. Afterward, it''s recommended to visit a casual standing bar to sample local sake, making for a memorable night in KOBE.' where id = 'KGIz7xluG0InYxYYiEEl6';
update content_bodies set title = '一生モノのおいしいに出会う「肉旅」へ！', description = '三重県松阪市が誇る「お肉」の魅力を詰め込んだ短編動画です。松阪牛の焼肉やすき焼き、ステーキ、ホルモン、最近人気の松阪鶏焼き肉など、どれも絶品です。「お肉のまち松阪」での肉旅を楽しんでみませんか？' where id = '6J0fRI3Vcmmn9Y5BdGkFo';
update content_bodies set title = 'Discover Deliciousness for a Lifetime: ''Meat Journey'' in Matsusaka!', description = 'This short promotional video showcases the allure of Matsusaka''s renowned ''meat'' in Mie Prefecture. Featuring mouthwatering Matsusaka beef in various forms such as grilled, sukiyaki, steak, and the increasingly popular Matsusaka chicken barbecue, each dish is a delight! Join us on a ''meat journey'' in ''the meat town of Matsusaka''!' where id = 'wLZRkezRYOyA8ARj3CJiz';
update content_bodies set title = 'いざ肉旅へ！Let’s Meat at Matsusaka!「お肉のまち松阪」プロモーション動画', description = '松阪は、松阪牛の焼肉やすき焼き、ステーキ、最近人気の松阪鶏焼き肉など、美味しいお肉で知られています。このプロモーション動画では、松阪の食の魅力を体験するよう呼びかけています。見ることで、訪れることで、味わうことで、その肉の質を理解できるでしょう。「お肉のまち松阪」での肉旅に参加しましょう！' where id = 'DRXQk6fv5KXUGuvESspmU';
update content_bodies set title = 'Let''s Meat at Matsusaka! Promotional Video for ''Meat Town Matsusaka''', description = 'Matsusaka is renowned for its delicious meats, including Matsusaka beef''s yakiniku, sukiyaki, steak, and the increasingly popular Matsusaka chicken BBQ. This promotional video invites you to experience the culinary delights of Matsusaka, where you will understand the quality of the meat through sight, visit, and taste. Join us on a meat journey in ''Meat Town Matsusaka''!' where id = 'wSeWOZowwwbendO_yJrO1';
update content_bodies set title = 'ニンニン！忍者のまち探索～伊賀市で伊賀忍者修行道場をレポート～', description = 'この動画では、伊賀市にある忍者のまちを探索し、伊賀忍者修行道場についてレポートしています。' where id = '5PEQIiJ8B6Ry4wEFpu329';
update content_bodies set title = 'Exploring Ninja Town: A Report on Iga Ninja Training Dojo', description = 'This video introduces the exploration of Ninja Town, focusing on the Iga Ninja Training Dojo.' where id = 'AjS3rxg1NUZj4Z0NhQ6G-';
update content_bodies set title = '日本一海女さんが多いまちを散策 (三重県鳥羽市)', description = 'この動画では、日本一海女さんが多いまちを散策する様子を紹介しています。' where id = 'cSZi8cRHdpe-3CPu2pN0V';
update content_bodies set title = 'Exploring the Town with the Most Ama Divers in Japan (Toba City, Mie Prefecture)', description = 'This video introduces a stroll through the town that has the highest number of ama divers in Japan.' where id = 'rQl_98Tdnubcj0WlpwDBs';
update content_bodies set title = '神戸の夜探検 DAY1 短縮版', description = 'フランスと台湾からのカップルが神戸のユニークな夜のスポットを探訪します。初日は神戸のランドマークとして知られるハーバーランドを訪れます。神戸海バスでのクイックツアーでは、海からの独特な景色を楽しみながら、神戸港の発展について知ることができます。この冒険は、Feel KOBE観光振興協会によって提供されています。' where id = 'dmZojaEfJ2YjlKTToJspQ';
update content_bodies set title = 'Night Exploring in KOBE DAY1 Short Version', description = 'Join a couple from France and Taiwan as they explore the unique night scene in KOBE. On Day 1, they visit Harborland, a well-known landmark of the city. The experience includes a quick tour on the KOBE Sea Bus, which offers a unique perspective of the city from the water, showcasing the development of KOBE port. This adventure is provided by the Feel KOBE Tourism Promotion League.' where id = 'pFHLl007sKLoJi8ugTdYN';
update content_bodies set title = '見逃せない夜景！ - 神戸の夜の探検', description = '神戸は日本の夜景スポットの一つに選ばれています。六甲山の天覧台からは、変わりゆく景色を観察することができます。目の前の美しい景色に、いつまでも見入ってしまうことでしょう。' where id = '4yR3sZxjCn_8M-JFj8z2I';
update content_bodies set title = 'Don’t miss it, Night View! - Night Exploring in KOBE', description = 'KOBE is recognized as one of Japan''s premier night view destinations. The Tenran Observatory at Mt. Rokko offers a stunning perspective of the changing scenery. Visitors can enjoy the captivating views that never cease to amaze.' where id = 'BPA03SXIeD0B44VVF8BQN';
update content_bodies set title = '時間が飛ぶ！神戸の夜の探検', description = '神戸のユニークな夜を楽しむイベントです。神戸ポートタワーからの港の景色を一望でき、いつ見ても飽きることがありません。このイベントは、Feel KOBE観光振興協会によって提供されています。' where id = '9n-RqQxZLLn4qkZzJW7Mg';
update content_bodies set title = 'Time flies! in Harbor - Night Exploring in KOBE', description = 'Experience the unique night atmosphere of KOBE. Enjoy a stunning view of the harbor from the KOBE Port Tower, where the scenery is always captivating. This event is organized by the Feel KOBE Tourism Promotion League.' where id = 'mYtUyzsb6eiY-5YPq3RSP';
update content_bodies set title = '360°シティビュー！ - 神戸の夜の探検', description = '神戸のユニークな夜を体験しませんか？ハーバーランドを短時間で巡り、町の美しい夜景を楽しむことができます。このイベントは、Feel KOBE観光振興協会が提供しています。' where id = 'uSEXlxmfZlTIzya-BzRFN';
update content_bodies set title = '360°City View! - Night Exploring in KOBE', description = 'Experience the unique night atmosphere of KOBE with a quick tour in Harborland, where you can enjoy stunning views of the city at night. This event is organized by the Feel KOBE Tourism Promotion League.' where id = '5tTGb14O5lVpUWp_ZJ2dP';
update content_bodies set title = '懐かしい町を歩く - 神戸の夜の探検', description = '神戸の歴史的な町を歩きながら、ユニークな夜の雰囲気を楽しんでみませんか？有名な炭酸せんべいを味わい、旅の最後には美味しい神戸牛が待っています。' where id = 'YpEUdWshjaJoLq6GpiulJ';
update content_bodies set title = 'Going down the nostalgic town - Night Exploring in KOBE', description = 'Experience the unique night atmosphere of KOBE by walking through its historic town. Enjoy the famous Tansan senbei crackers and indulge in delicious Kobe beef at the end of your journey.' where id = '3H__gBFHjxbH0xE7zSsJ-';
update content_bodies set title = 'なぜスピンと温泉？ - 神戸の夜の探検', description = '神戸のユニークな夜を体験してみませんか？有馬温泉は日本最古の温泉地の一つで、肌を滑らかにする効果のある7つの成分を含んでいます。また、心と体をリフレッシュするために、旅館に宿泊することをお勧めします。' where id = 'gWoOm62vV6HY3zpKYM7f0';
update content_bodies set title = 'Why spin and into Hot Spring? - Night Exploring in KOBE', description = 'Discover the unique night experience in KOBE! Arima Onsen, one of Japan''s oldest hot spring resorts, offers seven elements beneficial for skin smoothing. We also recommend staying in a Ryokan to rejuvenate both body and soul.' where id = 'SQBvjk8fsxS-Z_mEy3yzd';
update content_bodies set title = '驚くべき夜景 - 神戸の夜の探検', description = '神戸は大阪からわずか30分の距離にあり、日本の夜景スポットの一つとして選ばれています。神戸を訪れて、街の周りに広がる美しい夜景を探検してみませんか？きらめく夜景に魅了されることでしょう。神戸のユニークな夜を体験してください！' where id = 'xiuXc8wfsGCO7x5R7Q7f0';
update content_bodies set title = 'STUNNING Night Views - Night Exploring in KOBE', description = 'KOBE, located just 30 minutes from Osaka, is recognized as one of Japan''s premier night view destinations. Visitors are invited to explore the captivating night scenery that the city has to offer. The sparkling views are sure to leave a lasting impression. Experience the unique charm of KOBE at night!' where id = 'hcEK8zkSxjbSZlwZLOYpq';
update content_bodies set title = '神戸の夜の探検 - あなたのお気に入りはどれですか？', description = '神戸のユニークな夜を楽しむことができます。神戸発のスイーツや地元の日本酒、そして有名な神戸牛を堪能できる魅力的な体験です。神戸の味と文化を通じて、思い出に残る夜を過ごすことができるでしょう。' where id = 'TkptbyZ-clD41HaGTBr7R';
update content_bodies set title = 'Night Exploring in KOBE - Which one is your favorite?', description = 'Experience the unique nightlife of KOBE, where you can indulge in local delicacies such as KOBE sweets, local sake (rice wine), and the renowned KOBE beef. This exploration promises to be a delightful journey through the flavors and culture of KOBE, making it a memorable night out.' where id = 'gFWjFLRHObtL-QnhwSDEx';
update content_bodies set title = 'STOPMOTION!! 神戸の夜を探検', description = '最新の映画技術を使って、神戸のユニークな夜を楽しむことができます。主要な観光スポットを探索し、お気に入りを見つけてください。' where id = 'wKRgsc6HYc42WAAxn-r9g';
update content_bodies set title = 'STOPMOTION!! NIGHT EXPLORING IN KOBE', description = 'Experience the unique nightlife of Kobe through the latest movie technology. Explore major tourist attractions and discover your favorites in this vibrant city.' where id = 'AviQHTkaj7GnPGiCIAtnr';
update content_bodies set title = '神戸の夜の探検 - 3日目', description = '洗練された温泉町で新しい食べ物を試してみましょう！日本の旅館で「おもてなし」を体験し、最高の和食を楽しむことができます。大阪からわずか1時間の距離です。豊臣秀吉が愛した温泉で、ゆったりとしたお風呂に浸かり、リラックスしてみませんか？' where id = 'srTxV67quRebhVGkV1Qwg';
update content_bodies set title = 'NIGHT EXPLORING IN KOBE - DAY3', description = 'Experience the charm of a refined hot spring town in Kobe, just an hour from Osaka. Indulge in exquisite Japanese cuisine at a traditional inn, where the spirit of ''Omotenashi''—Japanese hospitality—shines through. Enjoy a relaxing hot bath in a hot spring that was favored by the famous Japanese warrior, Hideyoshi Toyotomi.' where id = 'RjoURt-71J6028ZolnEGs';
update content_bodies set title = '神戸の夜の探検 - 1日目', description = '特別な日を神戸で過ごし、クルーズや美しい夜景、そして神戸牛の風味豊かな味を楽しむことができます。神戸は活気ある港町で、大阪から電車でわずか25分の距離にあり、さまざまなアクティビティや観光スポットがあります。' where id = 'h7ey-32_C69ZIRe5aH58X';
update content_bodies set title = 'NIGHT EXPLORING IN KOBE - DAY1', description = 'Experience a special occasion in Kobe with a cruise, stunning night views, and the delicious taste of Kobe Beef. Kobe, a vibrant port town, is just a 25-minute train ride from Osaka, offering a variety of activities and attractions.' where id = 'UUnlDBBx0bUiTjrxfATpX';
update content_bodies set title = '神戸の夜の探検 - 2日目', description = '神戸の夜の探検2日目では、ケーブルカーに乗って山頂エリアに向かうことができます。この場所は「ミシュラン グリーンガイド 日本」で高く評価されています。夜景は素晴らしく、日本の夜景トップ3に登録されています。美しい景色を楽しんだ後は、懐かしいお土産を見つけたり、カフェで休憩したりできます。このエリアは大阪の梅田から1時間の距離にあり、アクセスも良好です。帰り道には、三宮で日本酒を買うこともおすすめです。' where id = 'KLTC-CysFFUeqrNQaJfGp';
update content_bodies set title = 'NIGHT EXPLORING IN KOBE - DAY2', description = 'On the second day of exploring Kobe at night, visitors can take a cable car to the mountaintop area, which is highly recommended in the Michelin Green Guide Japan. The night view from this location is spectacular, ranking among the Top 3 Night Views in Japan. After enjoying the view, guests can find nostalgic souvenirs and relax at a café. The area is just an hour away from Umeda in Osaka, making it an accessible destination. On the way back, visitors are encouraged to stop by Mikage to grab some Sake.' where id = 'vJN6TYRblmPno8ZW6XgSi';
update content_bodies set title = '【紹介動画】奈良へのお出かけや旅行をサポートする新しいウェブサービス「Nara iko」', description = '「Nara iko」は、AIを活用してユーザーの興味に基づいた観光スポットを提案し、個別の旅行プランを作成する新しいウェブサービスです。このプラットフォームは、旅行計画を簡素化し、ユーザーが楽に旅行体験を楽しめるように設計されています。「Nara iko」を利用することで、奈良の隠れた美しさや有名な鹿公園、文化的な名所を発見することができます。詳細は公式ウェブサイト（https://naraiko.pref.nara.jp/en）をご覧ください。' where id = 'mxxCYGG6ZUny-XT_xEAxm';
update content_bodies set title = 'Introduction Video: The new web service ''Nara iko'' designed to support outings and trips to Nara.', description = 'Nara iko is an innovative web service that utilizes AI to suggest tourist spots tailored to your interests and helps create a personalized itinerary for your trip to Nara. The platform aims to simplify the trip planning process, allowing users to enjoy their travel experience with ease. With Nara iko, you can uncover the hidden beauty of Nara, including its famous deer parks and cultural sites. For more information, visit the official website at https://naraiko.pref.nara.jp/en.' where id = 'uqlZRXNDEatUHlssmwhdT';
update content_bodies set title = '【紹介動画】「ならいこ」あなたにピッタリのなら旅を提案する新サービス', description = '「ならいこ」は、AIを活用してユーザーの興味に合った観光スポットを提案し、自動で旅程を作成する新しいサービスです。簡単な画面操作で、手軽に楽しく旅行を計画できます。ぜひ、#ならいこ で新たな奈良の魅力を探してみてください。サービスサイトはこちらからご覧いただけます: https://naraiko.pref.nara.jp' where id = '9rMf_exhZLxHYDvRIZPQw';
update content_bodies set title = 'Introduction Video: ''Naraiko'' - A New Service Proposing Perfect Nara Trips for You', description = 'Naraiko is an innovative service that uses AI to suggest tourist spots tailored to users'' interests and automatically creates travel itineraries. With simple screen operations, planning a fun and enjoyable trip has never been easier! Discover the new charms of Nara with #Naraiko. Check out the service site here: https://naraiko.pref.nara.jp' where id = 'XtSwQII_C3PXVHjHSMlEj';
update content_bodies set title = '奈良県MICE誘致PR動画（日本語フルバージョン）', description = 'この動画は、奈良県におけるMICE誘致の取り組みを紹介しています。MICEは、会議、インセンティブ、展示会などを含むビジネスイベントの総称であり、奈良県の魅力を伝える内容となっています。' where id = 'HPeXCimEZeJzKuHrDtQ1X';
update content_bodies set title = 'Nara Prefecture MICE Promotion Video (Full Japanese Version)', description = 'This video introduces the MICE (Meetings, Incentives, Conventions, and Exhibitions) promotion efforts in Nara Prefecture.' where id = 'nxv4z5PHoYDLOVGQrslsJ';
update content_bodies set title = '奈良県MICE誘致PR動画（日本語ショートバージョン）', description = 'この動画は、奈良県におけるMICE誘致の取り組みを紹介しています。MICEとは、会議、インセンティブ旅行、展示会などを指し、奈良県がこれらのイベントを誘致するための活動を行っていることを伝えています。' where id = 'NDiLAkHULCqXuSMx6dI1J';
update content_bodies set title = 'Nara Prefecture MICE Promotion PR Video (Japanese Short Version)', description = 'This video introduces the MICE (Meetings, Incentives, Conventions, and Exhibitions) promotion efforts in Nara Prefecture.' where id = 'Arkr_9Fkf5nJrBmxP2nXA';
update content_bodies set title = 'NARA MICEのプロモーションビデオ（英語フルバージョン）', description = 'このビデオは、NARA MICEに関するプロモーションを英語で紹介しています。' where id = 'cbfuS2JHXNMcEChAryiyz';
update content_bodies set title = 'Promotion video about NARA MICE (English full version)', description = 'This video presents a promotional overview of NARA MICE, showcasing its features and offerings in the full English version.' where id = 'mABIVg0ucZnEJdd_sXeth';
update content_bodies set title = 'NARA MICEのプロモーションビデオ', description = 'このビデオは、NARA MICEのプロモーションについての英語の短いバージョンを紹介しています。' where id = 'LS4g7EU6Pfe_8lwR6vV-O';
update content_bodies set title = 'Promotion video about NARA MICE', description = 'This video provides a brief introduction to the promotion of NARA MICE, highlighting its key features and offerings.' where id = 'WB3-iztPahN4pQydhcX87';
update content_bodies set title = '写真で楽しむ「紀伊山地の霊場と参詣道」 奈良県編', description = '「写真で楽しむ」をテーマに、フォトグラファーの鎌田風花さんが現地を訪れました。「紀伊山地の霊場と参詣道」の壮大な自然や歴史、美しい風景をお楽しみください。' where id = 'JDiVLr_cauDxh-0zkm0ji';
update content_bodies set title = 'Enjoying the ''Sacred Sites and Pilgrimage Routes of the Kii Mountain Range'' through Photography - Nara Prefecture Edition', description = 'This project features photographer Fuka Kamada visiting the site with the theme of ''enjoying through photography.'' Experience the grandeur of nature and history, as well as the beautiful landscapes of the ''Sacred Sites and Pilgrimage Routes of the Kii Mountain Range.''' where id = 'TK4HQ3qqdWXn2D7xaEtUk';
update content_bodies set title = 'ナラ・ニ・トマッテ卿のひとりごと　ホテルいろいろ篇', description = 'この動画では、ナラ・ニ・トマッテ卿のひとりごとを紹介しています。テーマは「ホテルいろいろ」で、さまざまなホテルに関する彼の考えや感想が語られています。' where id = 'x7zj0Me5g5VQm2-fM1XLH';
update content_bodies set title = 'Lord Nara ni Tomatte''s Monologue: Various Hotels', description = 'This video introduces Lord Nara ni Tomatte''s monologue, focusing on various hotels.' where id = 'JnyM94ynWn5wWQfrzJtrs';
update content_bodies set title = 'ナラ・ニ・トマッテ卿のひとりごと　大阪近い篇', description = 'この動画では、ナラ・ニ・トマッテ卿のひとりごとを紹介しています。内容は、彼の独特な視点や思考が反映されたもので、大阪に関連するテーマが取り上げられています。視聴者は、彼のユニークな表現や考え方を楽しむことができるでしょう。' where id = 'GcUo5FyNrI5BCs40lzSJB';
update content_bodies set title = 'Nara Ni Tomatte''s Monologue: Osaka Close Edition', description = 'This video introduces the monologue of Nara Ni Tomatte.' where id = 'idBGsZh5S28XCcJXfoF1p';
update content_bodies set title = 'ナラ・ニ・トマッテ卿のひとりごと　中南部旅篇', description = 'この動画では、ナラ・ニ・トマッテ卿のひとりごとを紹介しています。内容は中南部の旅に関するもので、彼の独自の視点や感想が語られています。' where id = 'IWLNDa1Y4l1gTWFTK1_Lg';
update content_bodies set title = 'Lord Nara ni Tomatte''s Monologue: Central and Southern Region Travel', description = 'This video introduces the monologue of Lord Nara ni Tomatte.' where id = '3VL1NSrYqLQl73CZmzPXq';
update content_bodies set title = 'ナラ・ニ・トマッテ卿のひとりごと　私の名前篇', description = 'この動画では、ナラ・ニ・トマッテ卿のひとりごとが紹介されており、彼の名前に関する考えや思いについて語られています。' where id = 'R-lWT72KINuwAQJDYzFvI';
update content_bodies set title = 'Lord Nara ni Tomatte''s Monologue: My Name', description = 'This video introduces Lord Nara ni Tomatte''s monologue, focusing on his thoughts and reflections regarding his name.' where id = 'm6uO2tx9D2SLKnKzpCIYZ';
update content_bodies set title = '聖林寺　特別法話・写経体験講座「天平の美仏　聖林寺十一面観音の祈り」', description = '1868年5月16日に国宝・十一面観音立像が大御輪寺から聖林寺に移されたエピソードを背景に、奈良県桜井市の古刹・聖林寺から住職の倉本明佳師を招き、国宝・十一面観音立像の魅力をお子様にもわかりやすく心が安らぐ形でお話しします。法話の後には、疫病退散や健康、安寧を願い、写経体験を行います。これは、2022年5月13日から15日に実施されたイベントの特別法話部分の無料配信です。' where id = '932HihWw5bYgHXIPkskuF';
update content_bodies set title = 'Special Dharma Talk and Sutra Copying Experience at Seirinji Temple: ''Prayer to the Eleven-Headed Kannon of Seirinji Temple''', description = 'On May 16, 1868, the National Treasure, the Eleven-Headed Kannon statue, was moved from Omoin Temple to Seirinji Temple. In this event, held at the ancient Seirinji Temple in Sakurai City, Nara Prefecture, the chief priest, Akira Kuramoto, will share the charm of the National Treasure, the Eleven-Headed Kannon statue, in a way that is easy for children to understand and soothing to the heart. Following the talk, participants will engage in a sutra copying experience, wishing for the dispelling of epidemics, health, and peace, especially in these times of anxiety and stagnation. This video is a free distribution of the special Dharma talk portion from the event held from May 13 to 15, 2022.' where id = 'Sy0amNTtKdAsxASfwRCkS';
update content_bodies set title = '奈良から生まれた癒やしのこころ②（出演：植物療法士・漢方養生指導士　橋本真季　氏）', description = '奈良で育まれた仏教や漢方は、変化の激しい現代を生きる私たちに多様な道標を示しています。令和3年には聖徳太子の没後1400年、令和4年には御生誕1450年を迎え、信貴山大本山玉蔵院の貫主や奈良発祥の薬草研究者との対話を通じて、新年に向けて心を豊かにするヒントを探ります。この動画は、令和3年12月19日に実施されたイベントの無料配信です。' where id = 'z7plCx2qV4DxpHmmRBBGk';
update content_bodies set title = 'Healing Spirit Born from Nara② (Featuring: Herbal Therapist and Traditional Chinese Medicine Instructor Maki Hashimoto)', description = 'The Buddhist and herbal traditions nurtured in Nara provide diverse guidance for us living in a rapidly changing modern world. This event marks the 1400th anniversary of the death of Prince Shotoku in 2021 and the 1450th anniversary of his birth in 2022. Through discussions with the head priest of the Tamukozan Daibutsuin, associated with Prince Shotoku, and a researcher of medicinal herbs originating from Nara, we seek hints to enrich our hearts as we approach the new year. This video is a free distribution of the event held on December 19, 2021.' where id = 'nj0K1IQIFPxqapinCtA0z';
update content_bodies set title = '奈良から生まれた癒やしのこころ①（出演：信貴山大本山玉蔵院　貫主　野澤密孝　師）', description = '奈良で育まれた仏教や漢方は、変化の激しい現代を生きる私たちに多様な道標を示しています。令和3年には聖徳太子の没後1400年、令和4年には御生誕1450年を迎え、信貴山大本山玉蔵院の貫主と奈良発祥の薬草研究者の話を通じて、新年に向けて心を豊かにするヒントを探ります。この動画は、令和3年12月19日に実施されたイベントの無料配信です。' where id = 'WAUhE0cTnMWFNlUhJ8gDF';
update content_bodies set title = 'Healing Spirit Born from Nara① (Featuring: Head Priest Mitsutaka Nozawa of Shigisan Daibonzan Gyokuzoin)', description = 'Buddhism and traditional Chinese medicine nurtured in Nara provide diverse guidance for us living in a rapidly changing modern world. In 2021, we marked the 1400th anniversary of the death of Prince Shotoku and in 2022, the 1450th anniversary of his birth. Through discussions with the head priest of Gyokuzoin, associated with Prince Shotoku, and a researcher of medicinal herbs originating from Nara, we seek hints to enrich our hearts as we approach the new year. This video is a free distribution of an event held on December 19, 2021.' where id = 'zSfw51URNbUeCWPQHdOQC';
update content_bodies set title = 'NARA ～自分を贅沢に～', description = '奈良は日本の歴史的かつ精神的な中心地であり、快適な隠れ家や訪れるべき場所が豊富にあります。主な見どころには、贅沢な宿泊施設であるFUFU NARA JAPANや、伝統工芸で知られる中川政七商店があります。訪問者は大仏で有名な東大寺を探索でき、New Light Potteryでは美しい陶器が展示されています。また、NIPPONIA田原本丸冨士醤油では、醤油の醸造や濾過体験が楽しめます。地元の料理を味わえるL’Auberge de Plaisance Sakuraiもユニークな食事体験を提供しています。奈良は探検と贅沢を誘う目的地であり、訪れるすべての人に思い出に残る体験を約束します。' where id = 'bwSIUy6EDdxA7vpWTqZc2';
update content_bodies set title = 'NARA ～Indulge Yourself～', description = 'Nara, the historic and spiritual heart of Japan, offers a variety of comfortable refuges and must-visit places. Key highlights include FUFU NARA JAPAN, a luxurious accommodation option, and Nakagawa Masashichi Shoten, known for its traditional crafts. Visitors can explore the iconic Todaiji Temple, famous for its Great Buddha statue. New Light Pottery showcases exquisite ceramics, while NIPPONIA Tawaramoto Maruto Shoyu provides an immersive experience in soy sauce brewing and filtration. For a unique dining experience, L’Auberge de Plaisance Sakurai offers a taste of local cuisine. Nara is a destination that invites exploration and indulgence, promising memorable experiences for all who visit.' where id = '9SUkDZrEhq0stJzlQbDa1';
update content_bodies set title = '奈良まほろば（ダイジェスト版）', description = '奈良まほろばは、東京新橋に位置する奈良県のブランドショップで、気軽に奈良の魅力を体験できる場所です。1階には観光案内コーナーがあり、観光コンシェルジュが旬の情報を提供し、より良い奈良の旅を提案します。ショップでは、奈良で生まれた魅力的な商品を紹介し、日常生活を豊かにする良いものを取り揃えています。カフェ＆バーでは、奈良の食材を使ったかき氷や、日本酒、クラフトビールを楽しむことができ、気軽に奈良の味を堪能できます。2階のTOKiでは、地元の生産者と連携し、季節の素材や奈良の風土、歴史を感じられるメニューを提供しており、レストランではコース、バルエリアでは単品で楽しめます。' where id = '2rXFxFB3PwDPVnC5BzXlJ';
update content_bodies set title = 'Nara Mahoroba (Digest Version)', description = 'Nara Mahoroba is a brand shop located in Shinbashi, Tokyo, where visitors can easily experience the essence of Nara. The first floor features a tourist information corner with a concierge providing up-to-date travel tips for an enhanced visit to Nara. The shop offers a variety of attractive products from Nara, each with its own story, enriching daily life with quality items. The café and bar serve Nara''s famous kakigori (shaved ice) made with local ingredients, alongside traditional sake and craft beers that reflect the new Nara. The second floor, TOKi, collaborates with local producers to create seasonal menus that highlight Nara''s culture and history, available as courses in the restaurant or à la carte in the bar area, complemented by wine and local sake.' where id = 'IO8ZQntv2UDogix2MRDEe';
update content_bodies set title = '奈良まほろば（英語字幕版）', description = '奈良まほろばは、東京・新橋にあるブランドショップで、奈良の魅力を気軽に体験できる場所です。1階には観光情報コーナーがあり、観光コンシェルジュが季節ごとの情報や奈良への最適な旅行提案を行っています。ショップでは、奈良の特産品や魅力的なアイテムが紹介され、日常生活を豊かにする商品が揃っています。1階のカフェ＆バーでは、奈良の特産食材を使ったスノーボールや、奈良の歴史に深く関わる日本酒、クラフトビールが楽しめます。2階のTOKiでは、奈良の生産者と提携し、季節の食材や文化、歴史を感じる料理を提供しています。レストランエリアでのコース料理や、バーエリアでのアラカルトメニューが楽しめ、季節の料理とワイン、奈良の特産酒やフルーツ飲料が揃っています。' where id = 'tbqVEjLzOjkZWcVgB-qUt';
update content_bodies set title = 'nara mahoroba (English subtitled version)', description = 'Nara Mahoroba is a brand shop located in Shimbashi, Tokyo, where visitors can experience the essence of Nara. The first floor features a tourist information corner staffed by concierges who provide seasonal insights and travel suggestions for Nara. The shop showcases unique items from Nara, enriching daily life with local specialties. The café and bar on the first floor serve ''snowballs'' made with Nara''s specialty ingredients, alongside Japanese sake and craft beer that reflect Nara''s history. The second floor, TOKi, is a restaurant and bar that collaborates with local producers to offer a menu highlighting seasonal ingredients and Nara''s culture through its dishes. Guests can enjoy a full course meal or a la carte options, including seasonal dishes paired with wines and local sake.' where id = 'stSIPoVbMz7srjvIFbIP5';
update content_bodies set title = '【MIYAZAKI🌊SURFTRIP🌴】日帰り編☀️', description = '長男と次男と一緒に宮﨑で日帰りのサーフィンを楽しみました。久しぶりに宮﨑の幼馴染と会うことができ、次男はとても喜んでいました。' where id = '6TIgUw7ojk9he2gWSS5Ia';
update content_bodies set title = 'Day Trip Surfing in Miyazaki', description = 'A day trip to Miyazaki for surfing with my two sons. My younger son was delighted to meet an old childhood friend after a long time.' where id = 'vsU_Q3sfUzBcfl-jgJoyh';
update content_bodies set title = '奈良秘食旅～夏～', description = '奈良県の食の魅力を季節ごとに紹介するこの動画では、三輪そうめんや大和野菜（大和丸なすなど）、鮎、ハウス柿、イチジク、かき氷といった食材が登場します。奈良秘食旅は、お茶やうどん、豆腐など、日本人の生活に欠かせない食材のルーツを探るもので、飛鳥・奈良時代の奈良にその起源があります。この地はシルクロードの終着点として栄え、多くの文化や技術が渡来人によってもたらされ、現在に至るまで受け継がれる食文化が育まれました。伝統を守りつつ進化を続ける大和肉鶏や大和野菜など、これらの食材は大切に育てられ、未来を見据えて進化し続けています。' where id = 'P1X2Bl36nIp6XIzNMLoGP';
update content_bodies set title = 'Nara Secret Food Journey - Summer', description = 'This video introduces the culinary attractions of Nara Prefecture, highlighting seasonal ingredients such as Miwa somen, Yamato vegetables (including Yamato maru eggplant), sweetfish, house persimmons, figs, and shaved ice. The Nara Secret Food Journey explores essential Japanese ingredients like tea, udon, and tofu, tracing their roots back to Nara during the Asuka and Nara periods. This region flourished as the terminus of the Silk Road, where many cultures and techniques were introduced by immigrants, leading to the development of a rich food culture that continues to thrive today. The video features the ''Yamato chicken,'' inspired by the traditional Yamato kashiwa, and the evolution of Yamato vegetables, which are carefully cultivated and continue to evolve while honoring tradition.' where id = 'AtiWYPH8fEQR9sNTNiXEN';
update content_bodies set title = '奈良の自然 2', description = 'この動画では、奈良の豊かな自然を紹介しています。最初に若草山が登場し、その緑豊かな風景が広がります。次に、自然の中に位置する芸術的な空間である室生山上公園芸術の森が紹介されます。その後、鹿寄せのイベントが続き、鹿が集まる様子が映し出されます。次に、壮大な風景で知られる瀞峡が紹介され、最後に多様な生態系で知られる大台ヶ原が登場します。視聴者はこの美しい映像を楽しみ、提供されたリンクを通じて奈良についてさらに探求することが奨励されています。' where id = 'omkMrWlHnKeGPPO5ZQkcV';
update content_bodies set title = 'Nara’s Nature 2', description = 'This video showcases the rich natural beauty of Nara, featuring various scenic locations. It begins with Wakakusayama, a prominent hill known for its lush greenery. Next, it highlights the Murou Art Forest, an artistic space set in nature. The video then presents Shikayose, an event where deer are attracted, followed by the stunning Dorokyo Gorge, known for its dramatic landscapes. Finally, it concludes with Odaigahara, a mountainous area celebrated for its diverse ecosystems. Viewers are encouraged to enjoy the visuals and explore more about Nara through the provided link.' where id = 'woHgPjrJOlRr7x9tx7y8K';
update content_bodies set title = '奈良の自然 1', description = 'この動画では、奈良の豊かな自然を紹介しています。最初に鹿寄せの場所が登場し、次に若草山という美しい山が紹介されます。また、室生山上公園芸術の森というアートパークや、大台ヶ原という素晴らしい自然エリアも取り上げられています。視聴者は映像を楽しみ、提供されたリンクを通じて奈良についてさらに探求することが奨励されています。' where id = 'eVbQT2zZSZXXp6QtwCO1N';
update content_bodies set title = 'Nara''s Nature 1', description = 'This video showcases the rich natural beauty of Nara, featuring various locations. It begins with Shikayose, a site known for its deer gathering, followed by Wakakusayama, a scenic mountain. The video also highlights the Murou Art Forest, an artistic park, and concludes with Odaigahara, a stunning natural area. Viewers are encouraged to enjoy the visuals and explore more about Nara through the provided link.' where id = 'UxPPT32_UuKynvFY2n5_b';
update content_bodies set title = 'せんとくんがご案内！withコロナのなら観光　南部編　ダイジェスト版', description = 'この動画では、せんとくんが奈良県内の観光施設を巡り、コロナ禍における安全・安心の取り組みを紹介しています。撮影は令和2年9月から12月にかけて行われました。観光客が安心して訪れることができるよう、各施設の対策や工夫が詳しく説明されています。' where id = 'YX7pr8O2BsJ8a6at_NElN';
update content_bodies set title = 'Sento-kun''s Guide! With Corona Nara Tourism - Southern Edition Digest', description = 'Sento-kun tours various tourist facilities in Nara Prefecture, introducing safety and security measures. This video was filmed between September and December 2020.' where id = '67V2Zt2CtBIZEtTbPEpcI';
update content_bodies set title = '乗り越えて千三百年～PRAY, PLAY, NARA～', description = 'この動画では、奈良の神社や寺院を紹介し、疫病の撲滅を祈る歴史的背景について触れています。奈良の豊かな文化遺産を楽しんでいただければと思います。' where id = '69ZUO3aesEEgrQkg4l5qq';
update content_bodies set title = 'Transcending Thirteen Centuries~PRAY,PLAY,NARA~', description = 'This video showcases the shrines and temples of Nara, highlighting their historical significance, including the prayers for the eradication of epidemics. It invites viewers to enjoy the rich cultural heritage of Nara.' where id = '9sn5v5Hlhnm6kVqSGRVX0';
update content_bodies set title = '乗り越えて千三百年~PRAY,PLAY,NARA~', description = 'この文章では、奈良県にある疫病退散に関連する歴史的な社寺を紹介しています。無病息災や国家平安の祈りの歴史に触れることを通じて、奈良の文化的背景を知ることができます。' where id = 'DLXVA7KZFsVvCDS5C20w_';
update content_bodies set title = 'Overcoming 1300 Years ~PRAY, PLAY, NARA~', description = 'This text introduces historical temples and shrines in Nara Prefecture that are associated with the dispelling of epidemics. It invites readers to explore the history of prayers for health and national peace.' where id = 'mj-yU9zQXnnlVMfDSQEM9';
