update content_bodies set title = '周防大島、山口県', description = '周防大島は日本の山口県に位置する島で、美しい風景と豊かな文化遺産で知られています。この島は周防大島町の一部であり、訪れる人々にさまざまな観光名所やアクティビティを提供しています。' where id = 'aOQkVkF2AUUw2HnXSmebE';
update content_bodies set title = 'Suō Ōshima, Yamaguchi Prefecture', description = 'Suō Ōshima is an island located in Yamaguchi Prefecture, Japan. It is known for its beautiful landscapes and rich cultural heritage. The island is part of Suō Ōshima Town, which offers various attractions and activities for visitors.' where id = '7LqVUNT913lv3wnImpRkU';
update content_bodies set title = '「奈良テロワール」フランス語字幕付き', description = '「奈良テロワール」というテーマのこの動画では、奈良の豊かな自然、歴史、文化によって育まれた食文化を紹介しています。また、奈良の生産者やレストランへのインタビューも収録されています。奈良の詳細については、「https://www.visitnara.jp/」を訪れてください。' where id = '0AXNHBDDJwPkZpN1YTr86';
update content_bodies set title = 'Nara Terroir with French subtitles', description = 'The video titled ''Nara Terroir'' explores the rich gastronomic culture of Nara, shaped by its abundant nature, history, and culture. It features interviews with local producers and restaurants, highlighting the unique culinary offerings of the region. For more information about Nara, viewers are encouraged to visit the website ''https://www.visitnara.jp/''.' where id = 'rnVYFZipedIwBlQQ0BF1_';
