update content_bodies set title = '奈良の食文化', description = 'この動画は「奈良の食文化」をテーマに、奈良の豊かで多様な食文化を紹介しています。地元の生産者やレストランへのインタビューを通じて、地域のユニークな料理の魅力を伝えています。詳細については「https://www.visitnara.jp/」をご覧ください。' where id = 'WWHO_DmvIqMgfjNdZPpOZ';
