update content_bodies set title = '湯の児海水浴場 SUP TRIP', description = 'このイベントは熊本の湯の児海水浴場で行われ、スタンドアップパドルボード（SUP）アクティビティが楽しめます。参加者はこの人気のあるウォータースポーツを通じて、美しい海岸の景色を満喫することができます。' where id = 'CduKa5Zeau_gT4bi0u_PX';
update content_bodies set title = 'Yunoko Beach SUP Trip', description = 'This event takes place at Yunoko Beach in Kumamoto, featuring stand-up paddleboarding (SUP) activities. Participants can enjoy the beautiful coastal scenery while engaging in this popular water sport.' where id = 'f5CVLaFrCtCwUcL4Mjsar';
update content_bodies set title = '五島列島の色 - サーフィン', description = '長男と次男と一緒に五島列島の福江島でのんびりとした旅を楽しみました。' where id = 'gMj_WGPYCam7dhW05qhXB';
