update content_bodies set title = '宮古島trip VO.3: 海亀と泳いで感動', description = 'このエントリーでは、宮古島旅行の中での特別な体験、特に海亀と泳ぐ感動を紹介しています。宮古島の美しさや、自然の中でこれらの素晴らしい生き物と触れ合うユニークな機会について描写されています。' where id = 'S389diMKkZIm4QXcK_J2Y';
update content_bodies set title = 'Miyako Island Trip VO.3: Swimming with Sea Turtles', description = 'This entry highlights a memorable experience during a trip to Miyako Island, focusing on the joy of swimming with sea turtles. The post captures the beauty of the island and the unique opportunity to interact with these magnificent creatures in their natural habitat.' where id = 'lUK3sHO4r7HxIO3dwnuxY';
update content_bodies set title = '【ASO MTB PARK】 🚲SOU & MASAKI❤️', description = '阿蘇MTBパークは、日本の阿蘇に位置するマウンテンバイキングのスポットです。自転車愛好者のために様々なトレイルや体験を提供しています。' where id = 'rHJqYDJyvjwp66PIcIMyJ';
