update content_bodies set title = '乗り越えて千三百年～PRAY,PLAY, NARA～ダイジェスト版', description = 'このダイジェスト版では、奈良県にある疫病退散に関連する歴史的な社寺を紹介しています。無病息災や国家平安の祈りの歴史に触れながら、奈良の文化と信仰の深さを感じることができます。' where id = 'jtfoJO13_gicz9uXiVJ_x';
update content_bodies set title = 'Overcoming 1300 Years - PRAY, PLAY, NARA - Digest Version', description = 'This digest introduces historical temples and shrines in Nara Prefecture that are associated with the eradication of epidemics. It invites viewers to explore the history of prayers for health and national peace.' where id = '3SVGpS2vxOSZIryZq_1xM';
update content_bodies set title = '奈良の口福～PRAY,PLAY, NARA～ダイジェスト版', description = 'この30秒のダイジェスト版では、奈良県の食の魅力を紹介しています。心を躍らせる奈良の個性豊かな食を楽しむことを提案しています。' where id = 'z22JB6vagqKLCsr3xIMzG';
