update content_bodies set title = '大和の祈り～PRAY,PLAY,NARA～　ダイジェスト版', description = 'このダイジェスト版では、奈良県の歴史文化、自然、食、そして安心安全に関する取り組みを紹介しています。また、一日でも早く平穏な世界が戻ることを願っています。' where id = '7XtFWvxmrOd56qOgHuwnf';
update content_bodies set title = 'Prayer of Yamato - PRAY, PLAY, NARA - Digest Version', description = 'This digest introduces the historical culture, nature, food, and safety initiatives of Nara Prefecture. It expresses a hope for the swift return of a peaceful world.' where id = 'cC-8KRf4UA0icBalD-pKK';
update content_bodies set title = '大和の祈り～PRAY,PLAY,NARA～', description = '「大和の祈り～PRAY,PLAY,NARA～」は、ウィズコロナ時代の観光ニーズを考慮して、奈良県観光プロモーション課が制作した動画です。この動画では、奈良県の歴史文化や自然、食、そして安心安全に関する取り組みを紹介しています。奈良の魅力を多角的に伝える内容となっており、観光客にとっての新たな訪問のきっかけを提供することを目的としています。' where id = 'tYuLFXpjEt30ae9KjsR15';
update content_bodies set title = 'Yamato''s Prayer - PRAY, PLAY, NARA', description = 'The video ''Yamato''s Prayer - PRAY, PLAY, NARA'' was produced by the Nara Prefecture Tourism Promotion Division to showcase the attractions of Nara in light of tourism needs in the post-COVID era. It highlights Nara''s historical culture, nature, food, and initiatives for safety and security.' where id = 'tgnbTEpVX1QszM4Ec0USQ';
update content_bodies set title = '松山市 グリーンツーリズムPR動画「松山あそびをたのしもう」【15秒Ver.】', description = '愛媛県の県庁所在地である松山市は、海や里山、瀬戸内の島々に囲まれています。ガイドのサポートや道具のレンタルが整っており、誰でも楽しめるグリーンツーリズム体験が充実しています。海釣りやBBQ、キャンプ、かんきつ狩り、動物との触れ合いなど、気軽にアクティビティを楽しむことができます。北条、日浦、中島でアウトドアな一日を過ごしてみませんか？' where id = 'sVrlUBJ9IK6zYXKVye-IT';
update content_bodies set title = 'Matsuyama City Green Tourism PR Video ''Let''s Enjoy Matsuyama'' [15-second Version]', description = 'Matsuyama, the capital of Ehime Prefecture, is surrounded by the sea, rural mountains, and the islands of the Seto Inland Sea. The city offers a variety of green tourism experiences supported by guides and equipment rentals, making it accessible for everyone. Visitors can enjoy activities such as sea fishing, BBQ, camping, citrus fruit picking, and interacting with animals. Why not spend an outdoor day in Hojo, Hiura, or Nakajima?' where id = '6vIPZtUAZYL7Doh7fvGBi';
update content_bodies set title = '深呼吸～PRAY,PLAY, NARA～', description = 'この文章は、奈良県の豊かな自然と野外アクティビティを紹介しています。自然に囲まれた環境の中で心を解き放つことを促しています。' where id = 'RDgFtcv5sT7rWpSwwguFj';
update content_bodies set title = 'Deep Breathing - PRAY, PLAY, NARA', description = 'This text introduces the rich nature and outdoor activities of Nara Prefecture. It encourages individuals to release their minds in the abundant natural surroundings.' where id = 'kL-T9VKlB7Wn-5qOSS90p';
update content_bodies set title = '【長崎ランタンフェスティバル】PV夜編EP1 　鮮やかな長崎の街に心躍る❤️', description = '今回は長崎ランタンフェスティバルの短めのPV風動画をお届けします。次の夜編EP2の方がクオリティが高いと感じていますが、タイトルの順番でEP1を先にアップしました。EP1も良い出来なので、ぜひご覧ください。動画制作に関しては独学で学びながら、撮影と編集の難しさを実感しています。撮影中に編集を意識することが重要だと感じており、次回の撮影ではその点を考慮したいと思っています。2020年の長崎ランタンフェスティバルは次のEP2で締めくくりますので、よろしくお願いします。' where id = '-TBpdFjFGdTlObCM2BD7Z';
update content_bodies set title = 'Nagasaki Lantern Festival PV Night Edition EP1: A Vibrant Night in Nagasaki', description = 'This is a short promotional video for the Nagasaki Lantern Festival, featuring the beautiful night scenery of Nagasaki. The creator, Kame TV, acknowledges that the upcoming EP2 will be even better, but has chosen to release EP1 first due to the title sequence. The creator shares their journey of learning video shooting and editing techniques through self-study and watching creative YouTube content. They emphasize the importance of envisioning the editing process while filming. This video serves as an introduction to the festival, with EP2 set to conclude the 2020 Nagasaki Lantern Festival series. The creator expresses gratitude for the viewers'' support and encourages them to watch the video.' where id = 'f0In3JslniONISkCd39Yw';
update content_bodies set title = '松山市 グリーンツーリズムPR動画「松山あそびをたのしもう」【60秒Ver.】', description = '愛媛県の県庁所在地である松山市は、海や里山、瀬戸内の島々に囲まれています。ガイドのサポートや道具のレンタルが整っており、誰でも楽しめるグリーンツーリズム体験が充実しています。海釣りやBBQ、キャンプ、かんきつ狩り、動物との触れ合いなど、気軽にアクティビティを楽しむことができます。北条、日浦、中島でアウトドアな一日を過ごしてみませんか？' where id = 'u93ZoEwpH1v_BllqKIHq7';
update content_bodies set title = 'Matsuyama City Green Tourism PR Video ''Let''s Enjoy Matsuyama'' [60-second Version]', description = 'Matsuyama, the capital of Ehime Prefecture, is surrounded by the sea, rural mountains, and the islands of the Seto Inland Sea. The city offers a variety of green tourism experiences supported by guides and equipment rentals, making it accessible for everyone. Visitors can enjoy activities such as sea fishing, BBQ, camping, citrus fruit picking, and interacting with animals. Why not spend an outdoor day in Hojo, Hiura, or Nakajima?' where id = '0-3lYWCbp0otPE-96WGA8';
update content_bodies set title = 'きゅんです。松山旅【60秒Ver.】｜松山市公式観光プロモーション動画', description = '愛媛県松山市は、日本最古の名湯とされる道後温泉や松山城など、多くの魅力的な観光地があります。広島県からのアクセスも良好で、瀬戸内・しまなみ街道が推奨されています。地元の名物には、坊っちゃんや坂の上の雲、タルト、みかん、鯛めし、俳句甲子園などがあり、四季折々の見どころが満載です。詳細は公式サイトをご覧ください。' where id = 'EtJWdG1ofA3euvlUEdNHK';
update content_bodies set title = 'Kyun desu. Matsuyama Trip [60 seconds version] | Official Tourism Promotion Video of Matsuyama City', description = 'Matsuyama City, located in Ehime Prefecture, is home to many attractive tourist destinations, including Dogo Onsen, known as Japan''s oldest hot spring, and Matsuyama Castle. The Setouchi and Shimanami Kaido routes from Hiroshima Prefecture are also recommended. Visitors can enjoy local specialties such as Botchan, Saka no Ue no Kumo, tart, citrus fruits, Tai-meshi, and the Haiku Koshien, along with seasonal highlights throughout the year. For more information, visit the official site at https://matsuyama-sightseeing.com/' where id = 'C1M6jPvWDQlhc2-2BR808';
update content_bodies set title = 'きゅんです。松山旅【30秒Ver.】｜松山市公式観光プロモーション動画', description = '愛媛県松山市の観光情報サイト「四国松山 瀬戸内松山」では、松山市の魅力的な観光地を紹介しています。日本最古の名湯とされる道後温泉や松山城などがあり、広島県からのアクセスも良好な瀬戸内・しまなみ街道もおすすめです。地元の名物として、坊っちゃんや坂の上の雲、タルト、みかん、鯛めし、俳句甲子園などが楽しめ、四季折々の見どころが満載です。詳細は公式サイトをご覧ください。' where id = 'uzFZltrR_cqG7WqKJEWXi';
update content_bodies set title = 'Kyun desu. Matsuyama Trip [30-second Version] | Official Tourism Promotion Video of Matsuyama City', description = 'The tourism information site for Matsuyama City in Ehime Prefecture, ''Shikoku Matsuyama Setouchi Matsuyama,'' highlights various attractive tourist spots. Notable locations include Dogo Onsen, considered Japan''s oldest hot spring, and Matsuyama Castle. The Setouchi and Shimanami Kaido routes from Hiroshima Prefecture are also recommended. Visitors can enjoy local specialties such as Botchan, Saka no Ue no Kumo, tart, citrus fruits, Tai-meshi, and the Haiku Koshien, along with seasonal attractions throughout the year. For more information, visit the official site: https://matsuyama-sightseeing.com/' where id = 'lZhPzOq59t0z08qpgWoeF';
update content_bodies set title = '【志摩地中海村】英虞湾アドベンチャークルーズ　2022年3月7日よりスタート！', description = '日本のマリンリゾート、志摩地中海村に新たなアクティビティが登場します。機動性と旋回性に優れ、弾丸のようなスピードで快走するこのアドベンチャークルーズは、映画007や海上保安庁でも使用されており、高い浮力と柔軟性を誇ります。雄大な英虞湾の自然を存分に楽しむことができます。開催期間は2022年3月7日から5月8日までで、出航時間は10:35、11:35、13:35、14:35、15:35、16:35の6回、所要時間は約15分です。営業時間は9:00から16:30までで、エントラーダ賢島での不定休です。料金は大人2,200円、小学生1,600円（身長130㎝以上または9歳以上）です。集合場所は志摩地中海村の桟橋で、問い合わせは0599-52-0888（エントラーダ賢島）まで。' where id = 'MX33CPmSBo_M0_Pxdw68O';
update content_bodies set title = 'Shima Mediterranean Village: Adventure Cruise in Ago Bay Starts March 7, 2022!', description = 'A unique new activity has launched at Shima Mediterranean Village, a marine resort in Japan! Experience high mobility and agility with a thrilling speed. This adventure cruise is used in films like 007 and by the Japan Coast Guard, boasting excellent buoyancy, flexibility, and safety. Enjoy the magnificent nature of Ago Bay to your heart''s content. The cruise runs from March 7, 2022, to May 8, 2022, with departures at 10:35, 11:35, 13:35, 14:35, 15:35, and 16:35, lasting approximately 15 minutes. Operating hours are from 9:00 to 16:30 at Entrada Kashikojima, with irregular holidays. Prices are 2,200 yen for adults and 1,600 yen for elementary school students (over 130 cm tall or 9 years old). The meeting point is at the pier of Shima Mediterranean Village. For inquiries, call 0599-52-0888 at Entrada Kashikojima.' where id = 'MPV9AYMmSkNbkTZSdDq1H';
update content_bodies set title = '【長崎ランタンフェスティバル】2020 想像以上の異国をご覧あれ❗️', description = '著者は20年ぶりに長崎ランタンフェスティバルを訪れ、学生時代に仲間と国家試験前に行ったことを思い出しています。祭りの規模とライトアップの素晴らしさに驚きを感じています。コロナウイルスやインフルエンザの心配から、動画ではマスクを着用しています。今後もランタンの様子をアップする予定で、視聴者に前作や次回の動画も楽しんでもらいたいと願っています。美しいランタンをぜひご覧ください。' where id = 'PzkY1FMAmMTEnYAUNtCr_';
update content_bodies set title = 'Nagasaki Lantern Festival 2020: Experience an Unexpected Foreign Atmosphere!', description = 'The author reflects on their visit to the Nagasaki Lantern Festival after 20 years, recalling their student days when they attended with friends before a national exam. They express surprise at the impressive scale and lighting of the festival. Due to concerns about COVID-19 and influenza, the author wears a mask in the video. They plan to share more videos showcasing the lanterns and hope viewers will enjoy both the current and previous content. The author invites everyone to experience the beauty of the lanterns.' where id = 'MFf-VJlA8pHWIg8_xpUny';
update content_bodies set title = 'きゅんです。松山旅【15秒Ver.】｜松山市公式観光プロモーション動画', description = '愛媛県松山市の観光情報サイト「四国松山 瀬戸内松山」では、道後温泉や松山城などの魅力的な観光地を紹介しています。広島県からのアクセスも良好な瀬戸内・しまなみ街道もおすすめです。松山の名物には、坊っちゃんや坂の上の雲、タルト、みかん、鯛めし、俳句甲子園などがあり、四季折々の見どころが満載です。公式サイトはこちらです： https://matsuyama-sightseeing.com/' where id = 'll9--UtV9LWROFhPjrvlp';
update content_bodies set title = 'Kyun desu. Matsuyama Trip [15-second Version] | Official Matsuyama City Tourism Promotion Video', description = 'The Matsuyama City tourism information site ''Shikoku Matsuyama Setouchi Matsuyama'' highlights the city''s attractions, including Dogo Onsen, known as Japan''s oldest hot spring, and Matsuyama Castle. The Setouchi and Shimanami Kaido routes from Hiroshima Prefecture are also recommended. Visitors can enjoy local specialties such as Botchan, Saka no Ue no Kumo, tart, citrus fruits, Tai-meshi, and the Haiku Koshien, along with seasonal highlights throughout the year. Official site: https://matsuyama-sightseeing.com/' where id = 'VLOpND-dHRWMlNeY-ARf8';
update content_bodies set title = '【松山市公式観光PR動画】松山・砥部・東温 New ツーリズム', description = '松山市・東温市・砥部町を巡る一泊二日の周遊コースを紹介しています。家族や女子、男子、大人向けに考えられた4つのモデルコースを通じて、魅力あふれる松山エリアを存分に楽しむことができます。' where id = '9S576EO7WcNPIul85CD4h';
update content_bodies set title = 'Matsuyama Official Tourism PR Video: New Tourism in Matsuyama, Tobe, and Toon', description = 'This video introduces a two-day, one-night tour course around Matsuyama City, Toon City, and Tobe Town. It features four model courses designed for families, women, men, and adults, encouraging visitors to fully enjoy the attractions of the Matsuyama area.' where id = '27WeFMNh-DjwxqBk32V_S';
update content_bodies set title = '松山観光 - 四国松山の旅', description = '愛媛県に位置する松山市は、美しい瀬戸内海に面しています。日本最古の温泉である道後温泉を楽しんだり、国宝の松山城を訪れたり、アートやグルメを心ゆくまで堪能することができます。' where id = 'w10KF0YuXqgsCU8hPSvB6';
update content_bodies set title = 'Matsuyama Sightseeing-Travel of Shikoku Matsuyama', description = 'Matsuyama City, located in Ehime Prefecture, offers stunning views of the Seto Inland Sea. Visitors can enjoy Japan''s oldest hot spring, Dōgo Onsen, explore the nationally treasured Matsuyama Castle, and indulge in a variety of art and gourmet experiences.' where id = 'QKW4qETAR9FQCpXhxSnoj';
update content_bodies set title = 'SADO NO KIWAMI Vol. 3: 究極の街歩き - 港町小木の町並みと歴史 -', description = '「SADO NO KIWAMI」、すなわち究極の佐渡は、佐渡に住み、愛し、佐渡を極めた人々を通じて、佐渡の冒険観光を紹介します。第3巻では、街歩きガイドの笠井が、佐渡でしか味わえない究極の体験として、港町小木の魅力と歴史的な町並みを案内します。冒険観光は、自然、アクティビティ、文化の3つの要素のうち少なくとも2つを組み合わせた体験を通じて、場所の魅力をより深く楽しむ観光の形です。' where id = 'SE-IBcir2T5pbvVNItCgj';
update content_bodies set title = 'SADO NO KIWAMI Vol. 3: Ultimate City Walking -The Townscape and History of the Port Town Ogimachi-', description = 'SADO NO KIWAMI, or Ultimate Sado, highlights adventure tourism on Sado through the experiences of its residents. In volume 3, city walking guide Kasai takes us on a journey to explore the unique charms and historical townscape of Ogi, a port town that offers an unparalleled experience on Sado. Adventure tourism here emphasizes a deeper appreciation of the area through a combination of nature, activity, and culture.' where id = 'NviZesgiiU8L_uKTbvFZ_';
update content_bodies set title = '松山市公式観光ムービー [英語]', description = '松山は日本の四つの主要な島の中で最も小さい四国に位置し、美しい瀬戸内海に面しています。この地域は、年間を通じて穏やかな気候で降水量が少なく、快適です。西には海、東には山があり、都市の便利さと田舎のゆったりとしたペースの両方を提供する場所です。' where id = '5TQ7AGJcRHXDmd2LyDfal';
update content_bodies set title = 'Matsuyama City Official Tourism MOVIE [English]', description = 'Matsuyama is situated in Shikoku, Japan''s smallest main island, and overlooks the serene Seto Inland Sea. The region enjoys a mild climate year-round with minimal rainfall. It features a unique blend of urban conveniences and the tranquil pace of rural life, with the sea to the west and mountains to the east.' where id = 'WeNUUnAeQGF8xWVzPLTA4';
update content_bodies set title = '松山市公式観光ムービー', description = '松山市は日本の四つの主要な島の中で最も小さい四国に位置しています。穏やかで美しい瀬戸内海に面し、年間を通じて温暖で降水量が少ない快適な気候を持っています。西には海、東には山が広がり、都市の便利さと田舎のゆったりとしたペースを兼ね備えた場所です。' where id = 'OYyWR6P7cAKq4VdM9PJS5';
update content_bodies set title = 'Matsuyama City Official Tourism MOVIE', description = 'Matsuyama, located in Shikoku, Japan''s smallest main island, offers a unique blend of urban convenience and rural tranquility. The city faces the serene Seto Inland Sea and enjoys a mild climate with minimal rainfall throughout the year. Surrounded by mountains to the east and the sea to the west, Matsuyama is an ideal destination for those seeking both natural beauty and city amenities.' where id = 'ALS5MwwsA8pD-c-ZFO7sR';
update content_bodies set title = 'きゅんです。松山旅｜四国松山 瀬戸内松山【松山市公式】', description = '愛媛県松山市は、穏やかで美しい瀬戸内海に面し、温暖で雨の少ない気候が特徴の地域です。道後温泉などの温泉や、近代俳句の礎を築いた正岡子規の存在から、「いで湯と城と文学のまち」として文化的魅力が豊富です。市の中心には、江戸時代から残る貴重な天守を有する松山城があり、その周辺には城下町の文化が息づいています。また、四国遍路の旅人を温かく迎える「おもてなし」の精神も根付いています。' where id = 'I_olpuu8T1sXjJ964S55t';
update content_bodies set title = 'Kyun desu. Matsuyama Trip | Shikoku Matsuyama Setouchi Matsuyama Official', description = 'Matsuyama City in Ehime Prefecture faces the calm and beautiful Seto Inland Sea, enjoying a mild climate with little rainfall throughout the year. Known for its hot springs, including the famous Dogo Onsen, and the literary legacy of Masaoka Shiki, Matsuyama is rich in cultural attractions, often referred to as the ''town of hot springs, castles, and literature.'' At the city''s center stands Matsuyama Castle, which features a rare Edo-period keep, surrounded by a town that preserves the culture of a castle town. The city is also known for its warm hospitality, welcoming travelers, especially those on the Shikoku pilgrimage.' where id = 'QWUTZ4_8P2Bj1i8ulY7KG';
update content_bodies set title = '大佐渡石名天然杉遊歩道【夏編】', description = '大佐渡山脈の北部に位置する県有林石名団地には、特異な形状の巨杉が生育しています。新潟県では、この雄大な天然杉を安全に観賞できるように遊歩道を整備しました。コースは起伏が少なく、子どもの自然学習の場としても安心して利用できるため、お薦めです。' where id = '6gijFa0OLGDA8ADxqxia5';
update content_bodies set title = 'Ogasawara Shina Natural Cedar Walking Path (Summer Edition)', description = 'In the northern part of the Ogasawara Mountain Range, there are uniquely shaped giant cedars growing in the Shina district of the prefectural forest. Niigata Prefecture has developed a walking path to allow visitors to safely view these magnificent natural cedars. The course has minimal elevation changes, making it a safe and recommended place for children''s nature learning.' where id = '_xvoS0tzAP0cjCIwUfJZH';
update content_bodies set title = '青森県「深」探求プログラムPR動画', description = '教育現場では、問いを解く力だけでなく、問いを立てる力を身につける学習機会が求められています。このプログラムは「課題設定能力」と「合意形成能力」を育成することを目的としています。プログラムはスタディツアーとワークショップで構成されており、スタディツアーでは社会問題が発生している現場を訪れ、地域の課題に触れるための施設や工場の見学、工芸品製作の体験、地域課題に関する講演を通じて、生徒たちが見て・聞いて・考える時間を持ちます。スタディツアーの後は、少人数グループでの議論を行うワークショップがあり、これらを合わせて約6時間の学習が行われます。このプログラムは、2泊3日や3泊4日の修学旅行の中で1日を費やす形で実施され、生徒にとって価値ある時間を提供することを目指しています。' where id = '6Cp2fPIkBMGj4XQ0PbQvA';
update content_bodies set title = 'Aomori Prefecture ''Deep'' Exploration Program PR Video', description = 'In the educational field, there is a growing need for learning opportunities that develop the ability to pose questions, in addition to solving them. This program focuses on cultivating ''problem-setting abilities'' and ''consensus-building skills.'' It consists of study tours and workshops. The study tours, lasting about three hours, involve visiting sites where social issues are present, guided tours of facilities and factories, hands-on experiences in craft-making, and lectures from stakeholders discussing local challenges. Following the tours, students engage in discussions in small groups during a three-hour workshop, making for a full day of learning. The program is designed to be integrated into school trips, allowing students to dedicate one day of their two or three-night trips to this valuable experience.' where id = 'zaMQQBZJ2rAd_Ks84thgI';
update content_bodies set title = '映画「バカ塗りの娘」主演の堀田真由さんからスペシャルメッセージ！', description = 'オール弘前ロケ映画「バカ塗りの娘」が、イオンシネマ弘前での上映の終盤を迎えています。これに伴い、映画鑑賞者や弘前の皆さんへの感謝のメッセージが届きました。まだ映画をご覧になっていない方や、鑑賞券（ムビチケ）をお持ちの方は、ぜひイオンシネマ弘前へ足を運んでください。' where id = '8hF3-bdCkPvQT8reCLBjZ';
update content_bodies set title = 'Special Message from Mayu Hotta, Star of the Movie ''Bakanuri no Musume''', description = 'The movie ''Bakanuri no Musume,'' filmed entirely in Hirosaki, is nearing the end of its screening at Aeon Cinema Hirosaki. A special message of gratitude has been sent to moviegoers in Hirosaki and beyond. If you haven''t seen the film yet or have a movie ticket (Mubichike), please visit Aeon Cinema Hirosaki!' where id = 'mB35GtDeVzMmrMLKcF8Qe';
update content_bodies set title = '弘前さくらまつり2023', description = '弘前さくらまつり2023は、ＮＴＴ東日本青森支店の協力を得て開催されます。' where id = 'SD7Xh3Jz2aeZJK7YG9-TZ';
update content_bodies set title = 'Hirosaki Cherry Blossom Festival 2023', description = 'The Hirosaki Cherry Blossom Festival 2023 is supported by NTT East Japan Aomori Branch.' where id = '84RPT4YhPA_p7Emdd5vSg';
update content_bodies set title = '大佐渡石名天然杉遊歩道【霧編】', description = '大佐渡山脈の北部に位置する県有林石名団地には、特異な形状の巨杉が生育しています。新潟県では、この雄大な天然杉を安全に観賞できるように遊歩道を整備しました。霧に包まれた幻想的な森の中で、じっとりと露に濡れた樹皮をまとった杉の巨木を楽しむことができます。' where id = 'kyHCS0P3V5fqTfYIpuVjs';
update content_bodies set title = 'Ogasawara Shina Natural Cedar Walking Path [Fog Edition]', description = 'In the northern part of the Ogasawara Mountain Range, there are uniquely shaped giant cedars growing in the Shina district of the prefectural forest. To allow visitors to safely enjoy these magnificent natural cedars, Niigata Prefecture has developed a walking path. In this fantastical forest shrouded in mist, you can see the giant cedars adorned with dewy bark.' where id = 'LFj4O5XTaO4wKNh2r0oOz';
update content_bodies set title = '弘前城菊と紅葉まつり【FLOWER ART 2022】メイキング', description = '弘前城菊と紅葉まつりは、1962年に始まり、紅葉と菊を楽しむ祭りとして親しまれています。現在では、弘前公園の約1,000本の楓と約2,600本の桜が美しい紅葉を見せる秋の象徴となっています。2020年からは「花」と「芸術」をテーマに、地域のシンボルであるねぷたやりんごを融合させたフラワーアートが注目されています。2022年のテーマは「四季の華めき」で、弘前の四季の変化を表現した作品が並びます。主な作品には、幸運を象徴する「飛翔花朱雀」や巨大な花輪の「花くぐり」、四季を巡る「四季の回廊」、風車に生まれ変わった「ねぷた風車」、中学生による「音楽が聴こえるひろふ花の動物園」があります。著名なフラワーデザイナー阿部喜恵や地元の職人たちの協力により、弘前の文化遺産が祝われています。' where id = '5O4ZQQwtUGMb-YwlC1Xv-';
update content_bodies set title = 'Hirosaki Castle Chrysanthemum and Autumn Leaves Festival: FLOWER ART 2022 Making', description = 'The Hirosaki Castle Chrysanthemum and Autumn Leaves Festival began in 1962 as a gathering to enjoy autumn foliage and showcase chrysanthemums. Today, it is a beloved festival symbolizing autumn in Hirosaki, featuring around 1,000 maple trees and 2,600 cherry trees. Since 2020, the festival has focused on ''flowers'' and ''art,'' integrating local symbols like Neputa and apples into flower art. The 2022 theme, ''The Splendor of the Four Seasons,'' showcases the vibrant seasonal changes in Hirosaki. Notable artworks include the ''Flower Vermillion Bird,'' symbolizing good fortune, and the ''Flower Arch of Hope,'' a large floral installation. Other highlights include the ''Cloister of The Four Seasons,'' the ''Neputa Pinwheel Wall,'' and the ''Music and Flower Zoo,'' created by local students. The festival features contributions from renowned floral designer Kie Abe and local artisans, celebrating the rich cultural heritage of Hirosaki.' where id = 'n9FTcM2_dFLWbWd6DoVSq';
update content_bodies set title = '弘前城菊と紅葉まつり - FLOWER ART 2022', description = '弘前城菊と紅葉まつりは、1962年に始まり、紅葉と菊を楽しむ祭りとして親しまれています。現在では、約1,000本の楓と約2,600本の桜が美しい紅葉を見せる弘前の秋を象徴する祭りとなっています。2020年からは「花」と「芸術」をテーマに、地域のシンボルであるねぷたやりんごを融合させたフラワーアートが注目されています。2022年のテーマは「四季の華めき」で、春夏秋冬の色彩豊かな変化を表現した作品が展示されました。特に「飛翔花朱雀」は幸運を招く象徴として注目され、また「四季の回廊」ではりんごの収穫の喜びが描かれています。さらに「音楽が聴こえるひろふ花の動物園」では、装飾された動物たちが楽器を演奏し、コロナ禍の学生たちの思いを表現しています。' where id = 'rP2HevG9IGq8a7uebeEiG';
update content_bodies set title = 'Hirosaki Castle Chrysanthemum and Autumn Leaves Festival - FLOWER ART 2022', description = 'The Hirosaki Castle Chrysanthemum and Autumn Leaves Festival began in 1962 as a gathering to enjoy autumn foliage and showcase chrysanthemums. Today, it is a beloved festival symbolizing autumn in Hirosaki, featuring around 1,000 maple trees and 2,600 cherry trees. Since 2020, the festival has focused on ''flowers'' and ''art,'' integrating local symbols like Neputa and apples into flower art. The 2022 theme, ''The Splendor of the Four Seasons,'' showcases the vibrant changes of Hirosaki''s seasons through collaborative works by various artists. Notable installations include the ''Flower Vermillion Bird,'' symbolizing good fortune, and the ''Cloister of The Four Seasons,'' depicting the joy of apple harvest. The festival also features a ''Music and Flower Zoo,'' where decorated animal figures play instruments, reflecting the students'' experiences during the pandemic.' where id = '-sUxFIGYjpsYBNjxfS4f6';
update content_bodies set title = '東京中央区観光紹介ムービー 歩（Walk）バージョン', description = 'このプロモーションビデオは、東京中央区の観光名所を訪問者の視点から紹介しています。「歩」バージョンでは、中央区の一日を描き、代表的なエリアである日本橋、人形町、銀座、築地、佃、月島を歩きながら楽しむ様子を捉えています。街を歩くことで、歴史の伝統を感じ、最新のトレンドに触れることができる多様なシーンを探索することができます。このビデオは、中央区の独自の魅力を紹介する魅力的な導入となっています。' where id = 'ETcm3sDTokGXHMIW_pDxg';
update content_bodies set title = 'Tokyo Chuo City tourism introduction movie - Walk version', description = 'This promotional video showcases the tourist attractions of Tokyo Chuo City from a visitor''s perspective. The ''Walk'' version captures a day in Chuo City, highlighting key areas such as Nihonbashi, Ningyocho, Ginza, Tsukiji, Tsukuda, and Tsukishima. It presents the sights and experiences of walking through the city, allowing viewers to appreciate its historical traditions and modern trends. The video invites viewers to explore the diverse scenes of Chuo City, making it an engaging introduction to the area''s unique charm.' where id = '1z7bOa1WBf8zP8sj3d8s8';
update content_bodies set title = '弘前：城堡、櫻花和蘋果之城', description = '弘前の魅力を感じてください。' where id = 'ow7vqJJ9XjXTZIy_zVZ-z';
update content_bodies set title = 'Hirosaki: The City of Castles, Cherry Blossoms, and Apples', description = 'Experience the charm of Hirosaki.' where id = 'iRdecK-sgp1QHlsJuh_X1';
update content_bodies set title = '弘前：城堡、桜、そしてリンゴの街', description = '弘前の魅力を感じてください。弘前は美しい城、見事な桜、そして美味しいリンゴで知られる街です。歴史的な魅力と自然の美しさが融合した弘前は、文化と自然の両方を求める訪問者にとって理想的な目的地です。' where id = 'Ve6h8vwEBevOavZAye0Pi';
update content_bodies set title = 'Hirosaki: The City of Castles, Cherry Blossoms, and Apples', description = 'Experience the charm of Hirosaki, a city known for its beautiful castle, stunning cherry blossoms, and delicious apples. Hirosaki offers a unique blend of historical and natural attractions, making it a perfect destination for visitors seeking both culture and nature.' where id = 'Divfimt5_D_o7VPob1Ey2';
update content_bodies set title = '桜とリンゴの城下町', description = '弘前の魅力を感じ、楽しんでください。弘前は美しい桜と美味しいリンゴで知られる町で、自然の美しさと文化遺産が融合した訪れるべき素晴らしい場所です。' where id = 'Ywa0Itw6RRHcloXFfoeOR';
update content_bodies set title = 'Castle Town of Cherry Blossoms and Apples', description = 'Experience the unique charm of Hirosaki, a town renowned for its beautiful cherry blossoms and delicious apples. The city offers a blend of natural beauty and cultural heritage, making it a perfect destination for visitors.' where id = 'CsNIzepyfxwD-Xq5obJV4';
update content_bodies set title = '弘前城菊と紅葉まつり：FLOWER ART 2021', description = '青森県弘前市の秋を象徴する「弘前城菊と紅葉まつり」は1962年から続いています。2020年からは「花」と「芸術」をテーマに、ねぷたやりんごといった弘前の文化を融合させた新しい展示企画が始まりました。2020年は新型コロナウイルスの影響で中止となりましたが、その想いを受け継ぎ、2021年はさらに大きな作品制作に取り組みました。今年のテーマは「枯木龍吟」で、復活や発展の願いが込められています。メイン作品の「昇天華龍」は全長100mを超える巨大な龍で、地元のねぷた組師とフラワーアーティストの共演によって制作されました。美しい弘前の紅葉と、様々なアーティストや市民による作品群を楽しむことができます。' where id = 'tlpZsChR2ZBocTC5cpUmV';
update content_bodies set title = 'Hirosaki Castle Chrysanthemum and Autumn Leaves Festival: FLOWER ART 2021', description = 'The Hirosaki Castle Chrysanthemum and Autumn Leaves Festival, a symbol of autumn in Hirosaki City, Aomori Prefecture, has been held since 1962. In 2020, a new exhibition concept began, merging local symbols and culture, such as Nebuta and apples, with the themes of ''flowers'' and ''art.'' Although the festival was canceled in 2020 due to the COVID-19 pandemic, the spirit continued into 2021, with a focus on larger artworks. The theme for 2021 is ''Koboku Ryogin,'' symbolizing revival and further development. The main piece, ''Shotenka Ryuu,'' is a massive dragon over 100 meters long, created through collaboration between local Nebuta artisans and flower artists. Visitors can enjoy the beautiful autumn leaves of Hirosaki and a variety of artworks created by artists and local citizens.' where id = 'lH0Jf9i1av4MNT7Y3dwNd';
update content_bodies set title = '弘前城菊と紅葉まつり：FLOWER ART 2021 メイキング', description = '弘前城菊と紅葉まつりは、青森県弘前市の秋を象徴する祭りで、1962年から続いています。2020年からは「花」と「芸術」をテーマにした新しい展示企画が始まり、弘前のシンボルであるねぷたやりんごと融合したフラワーアートが展開されました。2020年は新型コロナウイルスの影響で中止となりましたが、その想いを受け継ぎ、2021年にはさらに大きな作品制作に取り組みました。今年のテーマは「枯木龍吟」で、復活や発展の願いが込められています。メイン作品の「昇天華龍」は全長100mを超える巨大な龍で、地元のねぷた組師とフラワーアーティストの共演によって制作されました。美しい弘前の紅葉と、様々なアーティストや市民による作品群を楽しむことができます。' where id = 'GBPzgOtnz1XcfREhdx-PG';
update content_bodies set title = 'Hirosaki Castle Chrysanthemum and Autumn Leaves Festival: FLOWER ART 2021 Making', description = 'The Hirosaki Castle Chrysanthemum and Autumn Leaves Festival, a symbol of autumn in Hirosaki City, Aomori Prefecture, has been held since 1962. In 2020, a new exhibition concept began, merging local symbols and culture, such as nebuta and apples, with the themes of ''flowers'' and ''art.'' Although the festival was canceled in 2020 due to the COVID-19 pandemic, the spirit continued into 2021, leading to the creation of larger artworks. The theme for 2021 is ''Koboku Ryogin,'' symbolizing revival and further development. The main piece, ''Shoten Ka Ryuu,'' is a massive dragon over 100 meters long, created through collaboration between local nebuta artisans and flower artists. Visitors can enjoy the beautiful autumn leaves of Hirosaki and a variety of artworks created by artists and local citizens.' where id = 'njuQnX8ipzdpP9hEnX-lE';
update content_bodies set title = '弘前ねぷた３００年祭カレンダー', description = '弘前ねぷたの歴史と伝統を継承し、未来へとつなげることを目的としたカレンダーです。明治期から現代までの各時代に活躍した絵師に焦点を当て、ねぷたの移り変わりを体感できる内容となっています。各月の画像を楽しみながら、ねぷた囃子を聴くことができます。' where id = 'UvIFPVTUrAFkLkY_cCOui';
update content_bodies set title = 'Hirosaki Neputa 300th Anniversary Calendar', description = 'This calendar showcases the evolution of Hirosaki Neputa from the Meiji period to the present, highlighting the artists who contributed to each era. It aims to provide an immersive experience of the history and traditions of Neputa. Enjoy the images for each month while listening to the Neputa music.' where id = '8k2YEdj9eIsAWEd9Qvs9R';
update content_bodies set title = '弘前ねぷた300年祭カレンダー(ダイジェスト版)', description = '弘前ねぷたの歴史と伝統を継承し、未来へとつなげることを目的としたカレンダーです。明治期から現代までの各時代に活躍した絵師に焦点を当て、ねぷたの移り変わりを体感できる内容となっています。各月の画像をねぷた囃子の音色と共に楽しむことができます。' where id = 'c0qG0uNXfAMF6ihwje2G1';
update content_bodies set title = 'Hirosaki Neputa 300th Anniversary Calendar (Digest Version)', description = 'This calendar showcases the evolution of Hirosaki Neputa from the Meiji period to the present, highlighting the artists who contributed to each era. It aims to provide an immersive experience of history and tradition while looking towards the future. Enjoy the images for each month accompanied by the sounds of Neputa music.' where id = '_8ya9q4Dv29T1mu2BY0fV';
update content_bodies set title = '【東京中央区観光紹介ムービー】彩（Colors）版', description = 'このプロモーションビデオは、東京中央区のさまざまな観光名所を紹介しています。「彩」版では、著名なスポットを取り上げ、日本の文化と四季の融合をテーマに、その魅力を最大限に引き出しています。タイムラプスやドローン撮影などの多様な技術を駆使し、各対象の独自の美しさを際立たせています。東京の中心で感じる四季の美しい色合いを、言葉を必要としない壮大な映像で表現しています。' where id = 'ZhplNii4cksq-Q57lPGFp';
update content_bodies set title = 'Tokyo Chuo City tourism introduction movie: Colors version', description = 'This promotional video showcases the various tourist attractions of Tokyo Chuo City. The ''Colors'' version highlights famous locations, emphasizing the blend of Japan''s culture with the changing seasons. It utilizes various filming techniques, including time-lapse and drone photography, to enhance the unique beauty of each site. The video captures the vibrant colors of the seasons in the heart of Tokyo, presenting stunning visuals that speak for themselves without the need for words.' where id = '55JllbnNqHIJ9Zwy6iuZc';
update content_bodies set title = '【東京中央区観光紹介ムービー】人（People）バージョン（3分バージョン）', description = 'このプロモーションビデオは、東京中央区のさまざまな観光名所を紹介しています。「人」バージョンは「日本のおもてなし」をテーマに、中央区で働く職人や専門家とのコラボレーションで撮影されました。彼らの真剣な表情や、顧客を迎える際の自然な笑顔が映し出され、中央区に溢れる人間味を感じることができます。中央区では素晴らしい新しい出会いが待っています。ぜひ私たちの街を訪れ、楽しんでください。' where id = 'P9Y4KcJ4obw7MUCpwdZiv';
update content_bodies set title = 'Tokyo Chuo City tourism introduction movie - People version (3min. version)', description = 'This promotional video showcases the various tourist attractions of Tokyo Chuo City. The ''People'' version emphasizes the concept of ''Japanese welcome,'' featuring craftspeople and professionals from Chuo City. The video captures their serious dedication to their work and the warm smiles they share with customers, highlighting the rich humanity present in Chuo City. Visitors can expect wonderful new encounters and are warmly invited to explore and enjoy the city.' where id = '6q7Ihi-_bAfcO3BuEJGKS';
update content_bodies set title = '【東京中央区観光紹介ムービー】彩（Colors）バージョン', description = 'このプロモーションビデオは、東京中央区のさまざまな観光名所を紹介しています。「彩」バージョンでは、著名なスポットを取り上げ、日本の文化と四季の融合をテーマに、その魅力を最大限に引き出しています。タイムラプスやドローン撮影などの多様な技術を駆使し、各対象の独特な美しさを際立たせています。東京の中心で四季の美しい色彩を感じることができ、言葉を必要としない壮大な映像が描かれています。' where id = 'JTDVYykQjNaoscfsl__2z';
update content_bodies set title = 'Tokyo Chuo City tourism introduction movie: Colors version', description = 'This promotional video showcases the various tourist attractions of Tokyo Chuo City. The ''Colors'' version highlights famous locations, emphasizing the blend of Japan''s culture with the changing seasons. It utilizes various filming techniques, including time-lapse and drone photography, to enhance the unique beauty of each site. The video captures the vibrant colors of the seasons in the heart of Tokyo, presenting stunning visuals that speak for themselves without the need for words. Viewers can experience the awe-inspiring imagery that reflects the essence of Tokyo Chuo City.' where id = 'lCyWBHZsGlC4B8xdEH9bW';
update content_bodies set title = '【東京中央区観光紹介ムービー】人（People）バージョン（1.5分バージョン）', description = 'このプロモーションビデオは、東京中央区のさまざまな観光名所を紹介しています。「人」バージョンは「日本のおもてなし」をテーマに、中央区で働く職人や専門家とのコラボレーションで撮影されました。彼らの真剣な表情や、顧客を迎える自然な笑顔が映し出され、中央区に溢れる人間味を感じることができます。中央区では素晴らしい新しい出会いが待っています。ぜひ、私たちの街を楽しみに来てください。' where id = 'sKdlvXf3B190fBjZXXRyD';
update content_bodies set title = 'Tokyo Chuo City tourism introduction movie - People version (1.5min. version)', description = 'This promotional video showcases the various tourist attractions of Tokyo Chuo City, focusing on the ''People'' version that embodies the concept of ''Japanese welcome.'' It features craftspeople and professionals from Chuo City, capturing their serious dedication to work and their warm smiles as they greet customers. The video highlights the rich humanity present in Chuo City, inviting viewers to experience wonderful new encounters. The city welcomes everyone to come and enjoy its offerings.' where id = 'kfHRL9o5TWZd3vBIdBEL0';
update content_bodies set title = '【東京中央区観光紹介ムービー】ダイジェスト版（15秒版）', description = 'このプロモーションビデオは、東京中央区のさまざまな観光名所を紹介するもので、15秒のダイジェスト版としてまとめられています。ウォーク、アクティビティ、フード、カラー、そして人々の5つのテーマを通じて、中央区の魅力を引き出しています。ウォーク版では街を歩いているかのような視点を提供し、アクティビティ版では特定の瞬間や場所でしか体験できない祭りや体験を紹介します。フード版では、中央区で味わえる日本の美味しい料理を集め、カラー版では言葉を必要としない圧倒的な景色を提供します。そして、人々版では「日本のおもてなし」を基に、地域で働く人々の素敵な笑顔を集めています。このダイジェスト版を観ることで、言葉では表現できない中央区の魅力を発見できるでしょう。' where id = 'mXS4ZEX6AbXN1gxjwmq3A';
update content_bodies set title = 'Tokyo Chuo City tourism introduction movie - Digest version (15sec. version)', description = 'This promotional video showcases the various attractions of Tokyo Chuo City in a concise 15-second format. It highlights the unique aspects of the city through five thematic versions: Walk, Activity, Food, Colors, and People. The Walk version simulates a stroll through the streets, while the Activity version captures the essence of local festivals and experiences. The Food version presents a selection of delectable Japanese cuisine available in the city. The Colors version features stunning visuals that speak for themselves, and the People version showcases the warm smiles of the city''s residents, embodying the spirit of Japanese hospitality. This digest version encapsulates the charm of Chuo Ward, inviting viewers to discover what appeals to them.' where id = '0VVWInewynR3VpC8GMUuN';
update content_bodies set title = '愛媛県北宇和郡松野町 おさかな館・ぽっぽ温泉(2019.10.14)', description = 'この動画では、愛媛県北宇和郡松野町にあるおさかな館とぽっぽ温泉を紹介しています。いくつかの動画が消失したため、内容が薄くなってしまったことをお詫び申し上げます。松野町は西日本豪雨災害で大きな被害を受けましたが、復旧し営業を再開しています。山の中に位置する淡水水族館と、駅舎と一体となったぽっぽ温泉にぜひ遊びに来てください。' where id = '7LyP4laGuM4ePD0I5saeh';
update content_bodies set title = 'Oshakana-kan and Poppo Onsen in Matsuno Town, Ehime Prefecture (2019.10.14)', description = 'This video introduces Oshakana-kan and Poppo Onsen located in Matsuno Town, North Uwajima District, Ehime Prefecture. Some content may be lacking due to the loss of several videos, so please bear with us. The area suffered significant damage from the Western Japan Heavy Rain Disaster but has since recovered and is open for business. We invite you to visit this freshwater aquarium nestled in the mountains and the Poppo Onsen, which is integrated with a train station.' where id = 'XJoYtJvgPKYtO-GL8hf1m';
update content_bodies set title = '長野県 野沢温泉村 野沢温泉 共同湯 全13湯', description = '野沢温泉は長野県に位置する有名な温泉村で、13の公衆浴場があります。それぞれの浴場は独自の体験を提供し、伝統的な日本の入浴文化を楽しむことができます。訪れる人々は、ミネラル豊富な温泉の治癒効果を享受しながら、村の静かな雰囲気に浸ることができます。また、周囲の美しい自然や冬のスポーツでも知られ、年間を通じて人気のある観光地となっています。野沢温泉は、日本の共同浴場の豊かな歴史を垣間見ることができる場所でもあります。' where id = 'Tkse387VNizOkvpQFkfHE';
update content_bodies set title = 'The 13 Public Bathhouses of Nozawa Onsen, Nagano', description = 'Nozawa Onsen is a renowned hot spring village located in Nagano Prefecture, Japan. It features 13 public bathhouses, each offering unique experiences and traditional Japanese bathing culture. Visitors can enjoy the therapeutic benefits of the mineral-rich waters while immersing themselves in the serene atmosphere of the village. The area is also known for its beautiful natural surroundings and winter sports, making it a popular destination year-round. For those interested in local culture, Nozawa Onsen provides a glimpse into Japan''s rich history of communal bathing.' where id = 'XAhZ0JknNZVG_0r6yN494';
update content_bodies set title = '法華津峠 展望台(2020.1.29)', description = '愛媛県西予市にある法華津峠展望台へ行ってきました。前々日が暴風であったため道路状況が心配でしたが、なんとかたどり着きました。思いの外、眺めが良くて沈んでいた気持ちが少し元気になりました。' where id = 'X4uXpib6gyHysDVPDKf19';
update content_bodies set title = 'Hoketsu Pass Observatory (January 29, 2020)', description = 'I visited the Hoketsu Pass Observatory located in Seiyo City, Ehime Prefecture. I was concerned about the road conditions due to strong winds two days prior, but I managed to arrive safely. The view was unexpectedly good, which lifted my spirits a bit.' where id = 'BS9Xoe8rZeOT-A5IdqSeM';
update content_bodies set title = '弘前：桜とリンゴの城下町', description = '弘前の魅力を感じ、楽しんでください。美しい桜と美味しいリンゴで知られるこの町は、自然の美しさと文化的遺産が融合した魅力的な場所です。' where id = 'myL-SfzlG_ToPLBGG9whU';
update content_bodies set title = 'HIROSAKI: Castle Town of Cherry Blossoms and Apples', description = 'Experience the unique charm of Hirosaki, a town renowned for its beautiful cherry blossoms and delicious apples. This picturesque location offers visitors a delightful blend of natural beauty and cultural heritage.' where id = 'K-n2A8g_jxhO34u1XFISB';
update content_bodies set title = '津軽まちあるき 鶴田', description = '「津軽の普段を、ふかぐあさぐ。」をテーマに、地元のガイドと共にまちあるきツアーを楽しむことができます。このツアーは、津軽まちあるき観光推進実行委員会によって企画されており、弘前市や藤崎町、平川市など、青森県の9つの市町村が参加しています。詳細や予約は、津軽まちあるきの予約サイトをご覧ください。また、地域の各町のダイジェスト版や個別の動画リンクも提供されています。' where id = 'EN3C_a6BI_LV4rwPODvaY';
update content_bodies set title = 'Tsuruta Walking Tour', description = 'Experience the everyday life of Tsugaru with a local guide on this walking tour. The tour is organized by the Tsugaru Machiaruki Tourism Promotion Committee, which includes various municipalities such as Hirosaki City, Fujisaki Town, Hirakawa City, and others in the Aomori Prefecture. For more information and to make reservations, visit the Tsugaru Machiaruki reservation site. Additionally, there are several video links provided that showcase highlights from different towns in the region.' where id = 'QeoV66_X2wMIb-46DWSa0';
update content_bodies set title = '【津軽まちあるき】大鰐～Owani～', description = '地元のガイドと共に、津軽の普段の生活を体験できるまちあるきツアーです。この取り組みは、津軽まちあるき観光推進実行委員会によって制作されており、青森県や弘前市、藤崎町、平川市、大鰐町、黒石市、西目屋村、田舎館村、鶴田町、板柳町などの地域が参加しています。詳細や予約は、津軽まちあるき予約サイトをご覧ください。' where id = '2YIsPzBKyoFW-b8oD6Nb4';
update content_bodies set title = 'Tsugaru Town Walk: Owani', description = 'Experience the everyday life of Tsugaru with a local guide on a town walking tour. This initiative is produced by the Tsugaru Town Walking Promotion Committee, involving various local governments including Aomori Prefecture and several towns and cities such as Hirosaki, Fujisaki, Hirakawa, Owani, Kuroishi, Nishimeya, Inakadate, Tsuruta, and Itayanagi. For more information and to make reservations, visit the Tsugaru Town Walking reservation site.' where id = 'X4u1LeLX9pQcJA3RqmM9i';
update content_bodies set title = '津軽まちあるき 西目屋', description = '「津軽の普段を、ふかぐあさぐ。」をテーマに、地元のガイドと共にまちあるきツアーを楽しむことができます。このツアーは、青森県の弘前市や藤崎町、平川市、西目屋村など、津軽地域の観光推進を目的とした実行委員会によって企画されています。詳細や予約は、津軽まちあるきの予約サイトをご覧ください。また、各市町村の特徴を紹介するダイジェスト版の動画も用意されています。' where id = 'GamdGBQ6s2tTOU2aHGdnH';
update content_bodies set title = 'Nishimeya Walking Tour', description = 'Experience the everyday life of Tsugaru with a local guide on a walking tour. The tour is organized by the Tsugaru Machiaruki Tourism Promotion Committee, which includes various municipalities in Aomori Prefecture such as Hirosaki City, Fujisaki Town, Hirakawa City, and Nishimeya Village. For more information and reservations, visit the Tsugaru Machiaruki reservation site. There are also video summaries available for each participating municipality, showcasing the unique aspects of the region.' where id = 'iCQ_Ar4TTIbp18WQ0PGjW';
update content_bodies set title = '黒石～Kuroishi～', description = '「津軽の普段を、ふかぐあさぐ。」地元のガイドと共に行くまちあるきツアーです。このツアーは津軽まちあるき観光推進実行委員会によって企画されており、青森県中南地域県民局、弘前市、藤崎町、平川市、大鰐町、黒石市、西目屋村、田舎館村、鶴田町、板柳町などの市町村が参加しています。詳細や予約は津軽まちあるき予約サイトをご覧ください。' where id = 'O0lXM-LuApwLDIswdLNmm';
update content_bodies set title = 'Kuroishi Walking Tour', description = 'Experience the everyday life of Tsugaru with a local guide on this walking tour. The tour is organized by the Tsugaru Machiaruki Tourism Promotion Committee, which includes various municipalities such as Aomori Prefecture''s Chunan Regional Bureau, Hirosaki City, Fujisaki Town, Hirakawa City, Owani Town, Kuroishi City, Nishimeya Village, Inakadate Village, Tsugaru Town, and Itayanagi Town. For more information and to make reservations, visit the Tsugaru Machiaruki reservation site.' where id = 'x6yrVaLZ3bu8G8KZJuYYV';
update content_bodies set title = '【津軽まちあるき】板柳～Itayanagi～', description = '地元のガイドと共に、津軽の普段の生活を体験できるまちあるきツアーです。このツアーは、津軽まちあるき観光推進実行委員会によって企画されており、青森県中南地域県民局、弘前市、藤崎町、平川市、大鰐町、黒石市、西目屋村、田舎館村、鶴田町、板柳町などの市町村が参加しています。詳細や予約は、津軽まちあるき予約サイトをご覧ください。' where id = 'vRG4ZhNHY9k-6--uSZPyh';
update content_bodies set title = 'Tsugaru Walking Tour: Itayanagi', description = 'Experience the everyday life of Tsugaru with a local guide on this walking tour. The tour is organized by the Tsugaru Walking Tour Promotion Committee, which includes various municipalities such as Aomori Prefecture''s Chunan Regional Bureau, Hirosaki City, Fujisaki Town, Hirakawa City, Owani Town, Kuroishi City, Nishimeya Village, Inakadate Village, Tsugaru Town, and Itayanagi Town. For more information and to make reservations, visit the Tsugaru Walking Tour reservation site.' where id = 'm4sXh-m0ixgjz5R57hqog';
update content_bodies set title = '【津軽まちあるき】田舎館～Inakadate～', description = '「津軽の普段を、ふかぐあさぐ。」をテーマに、地元のガイドと共にまちあるきツアーを楽しむことができます。このツアーは、津軽地域の文化や風景を体験する貴重な機会を提供します。津軽まちあるきは、青森県中南地域県民局や弘前市、藤崎町、平川市、大鰐町、黒石市、西目屋村、田舎館村、鶴田町、板柳町などの地元自治体が参加する津軽まちあるき観光推進実行委員会によって企画されています。詳細や予約は、津軽まちあるきのウェブサイトをご覧ください。' where id = 'NEudEAMXOQ67RjiPe5ecu';
update content_bodies set title = 'Tsugaru Walking Tour: Inakadate', description = 'Experience the everyday life of Tsugaru with a local guide on a walking tour. This tour offers a unique opportunity to explore the culture and scenery of the region. The Tsugaru Walking Tour is organized by the Tsugaru Walking Tour Promotion Committee, which includes various local municipalities such as Aomori Prefecture, Hirosaki City, Fujisaki Town, Hirakawa City, Owani Town, Kuroishi City, Nishimeya Village, Inakadate Village, Tsugaru Town, and Itayanagi Town. For more information and to make reservations, visit the Tsugaru Walking Tour website.' where id = 'tHHm1pvdvr9jwsiCDjvTB';
update content_bodies set title = '津軽まちあるき 弘前', description = '地元のガイドと共に、津軽の普段の生活を体験できるまちあるきツアーです。このツアーは、弘前市や藤崎町、平川市など、青森県内の複数の市町村が参加する「津軽まちあるき観光推進実行委員会」によって企画されています。詳細や予約は、津軽まちあるきの予約サイトをご覧ください。また、参加する9市町村の魅力を紹介するダイジェスト版の動画も用意されています。' where id = 'EMXx-8jUlqcnjdYOE9dXQ';
update content_bodies set title = 'Tsugaru Walking Tour: Hirosaki', description = 'Experience the everyday life of Tsugaru with a local guide on a walking tour. The tour is organized by the Tsugaru Walking Tour Promotion Committee, which includes various municipalities such as Hirosaki City, Fujisaki Town, Hirakawa City, and others in the Aomori Prefecture. For more information and reservations, visit the Tsugaru Walking Tour reservation site. Additionally, there are digest videos available for each of the nine municipalities involved in the tour, showcasing their unique attractions.' where id = 'GqkcCANG1UQxkwsZEljUA';
update content_bodies set title = '【津軽まちあるき】平川～Hirakawa～', description = '地元のガイドと共に、津軽の普段の生活を体験できるまちあるきツアーです。この取り組みは、津軽まちあるき観光推進実行委員会によって制作されており、青森県や弘前市、藤崎町、平川市などの複数の市町村が参加しています。詳細や予約は、津軽まちあるき予約サイトをご覧ください。また、各市町の魅力や体験を紹介するダイジェスト動画も公開されています。' where id = 'XK225-cUDMH66M6NJtmmw';
update content_bodies set title = 'Tsugaru Town Walk: Hirakawa', description = 'Experience the everyday life of Tsugaru with a local guide on a town walking tour. This initiative is produced by the Tsugaru Town Walking Promotion Committee, involving various local governments including Aomori Prefecture and several cities and towns such as Hirosaki, Fujisaki, Hirakawa, and more. For more information and to make reservations, visit the Tsugaru Town Walking reservation site. Additionally, there are digest videos available for each participating city and town, showcasing their unique attractions and experiences.' where id = 'fSI4GzARFZFim1pk9lc8y';
update content_bodies set title = '津軽まちあるき', description = '「津軽の普段を、ふかぐあさぐ。」をテーマに、地元のガイドと共にまちあるきツアーを体験できます。このツアーでは、地域の文化や歴史を深く知ることができる貴重な機会が提供されます。詳細や予約は、津軽まちあるきの予約サイトをご覧ください。この取り組みは、津軽まちあるき観光推進実行委員会によって行われており、青森県のさまざまな自治体が参加しています。また、地域の各町のハイライトを紹介する動画リンクもあり、訪問者が期待できる内容を垣間見ることができます。' where id = 'dK38EzLHeEqrhQ_8cD5KD';
update content_bodies set title = 'Tsugaru Machi Aruki', description = 'Experience the everyday life of Tsugaru through guided walking tours led by local guides. The tours offer a unique opportunity to explore the culture and history of the region. For more information and to make reservations, visit the Tsugaru Machi Aruki reservation site. The initiative is produced by the Tsugaru Machi Aruki Tourism Promotion Committee, which includes various local government bodies from the Aomori Prefecture. Additionally, there are several video links provided that showcase highlights from different towns in the region, allowing potential visitors to get a glimpse of what to expect.' where id = 'HBYadqtZUY6vlWQzDi2AU';
update content_bodies set title = '弘前城菊と紅葉まつり ～その先を、照らす。', description = '1962年に始まった弘前城菊と紅葉まつりは、青森県弘前市の秋を象徴する重要なイベントです。しかし、2020年10月19日、まつりの4日前に新型コロナウイルスの急速な拡大を受けて中止が決定され、弘前の四大まつりの中で春のさくらまつり、夏のねぷたまつりに続く3回目の中止となりました。このまつりは「継往開来／その先を、照らす。」というテーマのもと、弘前の歴史と文化を紹介し、明るい未来を描くことを目的としていました。中止となったものの、2020年の弘前公園は美しい紅葉と花で彩られ、地域の人々は未来に向けた新たな挑戦を続けました。元気を届けるための動画メッセージが作成され、弘前からのエールがより多くの人々に届くことを願っています。' where id = 'phoGHViA6s0DjFNMT80hM';
update content_bodies set title = 'HIROSAKI CASTLE CHRYSANTHEMUM AND AUTUMN FOLIAGE FESTIVAL - Lighting Up the Future', description = 'The HIROSAKI CASTLE CHRYSANTHEMUM AND AUTUMN FOLIAGE FESTIVAL, which began in 1962, is a significant autumn event in Hirosaki City, Aomori Prefecture. However, on October 19, 2020, just four days before the festival, it was canceled due to the rapid spread of Covid-19, marking the third cancellation of Hirosaki''s four major festivals, following the spring cherry blossom festival and the summer Nebuta festival. The festival aimed to celebrate the season with the theme ''Lighting Up the Future,'' showcasing the city''s history and culture while envisioning a brighter future. Despite the cancellation, Hirosaki Park was still adorned with beautiful autumn foliage and flowers, and the community continued to engage in new challenges for the future. A video message was created to uplift spirits and share Hirosaki''s greetings with a wider audience.' where id = 'Z4yp_67oBnGw8CztybEgD';
update content_bodies set title = '熊野古道伊勢路で最古の「波田須の道」は歩きやすくて初心者にもぴったり', description = '「波田須の道」は、鎌倉時代に作られた世界遺産・熊野古道伊勢路の最古の道です。距離は約300メートルで傾斜も緩やかなので、初めて熊野古道を歩く方に最適です。また、波田須エリアには、海が見える秘境駅や、古代の伝説が残る「徐福の宮」、テラスから絶景が楽しめる「徐福茶屋」など、魅力的なスポットがたくさんあります。' where id = '8bj-CG6atKm_NHz5S-Hlq';
update content_bodies set title = 'The Oldest Path of Kumano Kodo Iseji: Hadasu no Michi is Easy to Walk and Perfect for Beginners', description = 'Hadasu no Michi, created during the Kamakura period, is the oldest path of the UNESCO World Heritage site Kumano Kodo Iseji. It is only about 300 meters long with a gentle slope, making it ideal for those walking the Kumano Kodo for the first time. The Hadasu area also features a hidden station with ocean views, the Jofuku Shrine, which is steeped in ancient legends, and the Jofuku Teahouse, where visitors can enjoy breathtaking views from the terrace. This area is filled with wonderful spots to explore.' where id = '_LtJLDYxJnzruosFK28wK';
update content_bodies set title = '弘前城菊と紅葉まつり ～その先を、照らす。', description = '1962年から続く弘前城菊と紅葉まつりは、青森県弘前市の秋を象徴するイベントです。しかし、2020年10月19日、まつりの開催4日前に新型コロナウイルスの急速な拡大を受けて中止が決定されました。これは弘前の四大まつりの中で、春のさくらまつり、夏のねぷたまつりに続く3回目の中止となりました。弘前城菊と紅葉まつりは「継往開来／その先を、照らす。」というテーマのもと、弘前の歴史と文化を紹介し、明るい未来を描くことを目的としていました。まつりは中止となりましたが、2020年の弘前の秋には、弘前公園が美しい紅葉と花で彩られ、未来に向けた新たな挑戦に取り組む人々の姿がありました。この動画メッセージは、視聴者を元気づけるために送られ、弘前からのエールが多くの人に届くことを願っています。' where id = 'gmmVWSX3olVBmt43tPeRF';
update content_bodies set title = 'HIROSAKI CASTLE CHRYSANTHEMUM AND AUTUMN FOLIAGE FESTIVAL - Lighting Up the Future', description = 'The HIROSAKI CASTLE CHRYSANTHEMUM AND AUTUMN FOLIAGE FESTIVAL, which began in 1962, symbolizes the autumn season in Hirosaki City, Aomori Prefecture. However, on October 19, 2020, just four days before the festival, it was canceled due to the rapid spread of Covid-19. This marked the third cancellation of Hirosaki''s four major festivals, following the spring cherry blossom festival and the summer Nebuta festival. The festival aimed to celebrate the season with the theme ''Lighting Up the Future,'' showcasing the city''s history and culture while envisioning a brighter future. Despite the cancellation, Hirosaki Park was still adorned with vibrant autumn colors, and the community continued to engage in new challenges for the future. This video message is intended to uplift viewers, hoping that Hirosaki''s spirit reaches as many people as possible.' where id = 'bDAbbd10UWjBIiuMbj0YQ';
update content_bodies set title = '旧弘前偕行社の紹介', description = '旧弘前偕行社は、ルネサンス風様式を基調とした木造平屋建ての建物で、シンプルな洋風建築ながら大規模で華やかな細部意匠が特徴です。正面中央の屋根窓や装飾的な軒廻り、窓廻りの飾り枠、三角形の破風飾りなどが豊かに施されています。玄関は鋳鉄柱を用いたポーチがあり、唐草模様と陸軍第8師団に因んだ「蜂」のレリーフが印象的です。館内の窓ガラスは気泡や波がありレトロな雰囲気を醸し出し、漆喰天井の中心飾りや外国製タイルの暖炉も当時のまま残っています。旧弘前偕行社は、東北地方の陸軍関係施設の代表的な遺構であり、建築的観点からも保存価値が高いです。終戦後は、地域医療・福祉の先駆者であった故鳴海康仲氏の理念に基づき、弘前厚生学院の校舎として次世代の人材育成に貢献しています。' where id = 'YF-pbMi5_6yezkCGb64oI';
update content_bodies set title = 'Introduction to the Former Hirosaki Kaikosha', description = 'The Former Hirosaki Kaikosha is a building based on Renaissance-style architecture, characterized by its wooden single-story structure and simple Western design. It features a large scale with ornate details strategically placed throughout. Notable decorations include a roof window at the center of the front, decorative eaves, and triangular gable ornaments. The entrance showcases a porch with cast iron columns and impressive reliefs inspired by the 8th Army Division. The interior retains a retro atmosphere with many windows featuring bubbles and waves in the glass, along with delicate plaster ceiling decorations and foreign tile fireplaces. As a representative structure of military facilities in the Tohoku region, it holds significant architectural value, showcasing the design evolution by the Army Ministry''s construction organization. After the war, it became an educational facility under the vision of the late Yasushi Narumi, a pioneer in regional healthcare and welfare, and continues to nurture future generations.' where id = 'ZsQkSWh0MBiGq1Ys9abIR';
update content_bodies set title = '弘前城秋の大祭典', description = '弘前公園がまるごとテーマパークとなる秋の大祭典です。フード、スポーツ、キッズコーナー、クラフト、ステージイベントなど、多彩なアクティビティが用意されており、子どもから大人まで楽しむことができます。' where id = 'oexZrx1jrkX9M8s-X7fIl';
update content_bodies set title = 'Hirosaki Castle Autumn Festival', description = 'The entire Hirosaki Park transforms into a theme park for the Autumn Festival. This event offers a variety of activities including food, sports, a kids'' corner, crafts, and stage events, ensuring enjoyment for both children and adults.' where id = 'B6fooGIaUpu3v49qFGWI8';
