update content_bodies set title = 'パワースポット 逆杖の公孫樹', description = '愛媛県松野町に位置する逆杖の公孫樹は、巨木として知られ、弘法大師にゆかりのあるパワースポットです。この場所は、精神的なエネルギーを求める訪問者にとって重要なスポットとなっています。' where id = 'aRoik-cKubxWmuYnUS0nZ';
update content_bodies set title = 'Power Spot: Ginkgo Tree of Gyakujo', description = 'The Ginkgo tree, a giant tree located in Matsuno Town, Ehime Prefecture, is known as a power spot associated with Kobo Daishi. It is a significant site for visitors seeking spiritual energy.' where id = 'BySFc4JSSAIDXm3Jg-Ay2';
update content_bodies set title = '5/5大洲編 伊予灘ものがたり 車で追いかける(2022.5.5)', description = '2022年5月5日に、大洲編の伊予灘ものがたりを撮影するために並走することを目的としました。360°カメラを車外に配置し、安全第一で他の車の邪魔にならないように走行しました。仕上がりはまぁまぁだと思います。また、2022年5月5日に大洲編に乗っていた方のコメントをお待ちしています。撮影にはInsta360 One X2を使用し、編集はInsta360 Studio 2022とFinal Cut Proで行いました。' where id = 'St43OcPRWpNLYP1pMXbjD';
update content_bodies set title = 'Chasing the Iyo-nada Monogatari in Ozu (May 5, 2022)', description = 'On May 5, 2022, I filmed the Iyo-nada Monogatari in Ozu with the aim of running alongside it. A 360° camera was placed outside the car, and I prioritized safety while ensuring not to obstruct other vehicles. I believe the final result turned out reasonably well. I welcome comments from those who were on the Ozu train on May 5, 2022. The filming was done using the Insta360 One X2, and editing was completed with Insta360 Studio 2022 and Final Cut Pro.' where id = 'I03T0O4RTRtTwUNRyNrrQ';
update content_bodies set title = '伊方町 せと風の丘パーク(2022.4.20)', description = '伊方町のせと風の丘パークに行ってきました。天気が良く、景色は最高でした。パークといっても、トイレと風車、そして美しい景色しかありません。撮影はInsta360 one X2を使用し、360°動画として仕上げました。編集にはInsta360 Studio 2022とFinal Cut PROを使用しました。' where id = '09fj6F73SrAoBVQbLPb5B';
update content_bodies set title = 'Seto Kaze no Oka Park in Ikata Town (April 20, 2022)', description = 'I visited Seto Kaze no Oka Park in Ikata Town. The weather was great, and the scenery was fantastic. Although it is called a park, it only features a restroom, a wind turbine, and beautiful views. The footage was captured using the Insta360 One X2, resulting in a 360° video.' where id = 'aHmgRGvWddMx2jzn_fmfs';
update content_bodies set title = 'ふたみシーサイド公園(2022.4.27)', description = '愛媛県伊予市双海町にある国道378号の道の駅ふたみに併設する「ふたみシーサイド公園」に行ってきました。このロケーションは360°動画にぴったりだと思い、撮影を行いました。画質や編集方法については、現在試行錯誤中であり、申し訳ありません。' where id = 'TUWTckEeqFtKGOSaD9xIB';
update content_bodies set title = 'Futami Seaside Park (April 27, 2022)', description = 'I visited Futami Seaside Park, located in Futami Town, Iyo City, Ehime Prefecture, which is adjacent to the roadside station Futami on National Route 378. I thought this location would be perfect for a 360° video, so I filmed it. I apologize for the current quality and editing methods, as I am still experimenting with them.' where id = 'Dm8KLKS5HhLc4oYec9iAJ';
update content_bodies set title = '四国カルスト 大野ヶ原(2022.5.17)', description = '四国カルストの大野ヶ原に行ってきました。檮原町からの道のりは難所が多く、大量の材木を積んだトラックと遭遇し、100mほどバックする羽目になりました。また、工事中のため山を一つ迂回する必要もあり、大変でした。大野ヶ原は西予市に位置しています。' where id = 'WYxHPUPofL4kKWDFzfYW7';
update content_bodies set title = 'Shikoku Karst Ohnogahara (May 17, 2022)', description = 'I visited Ohnogahara in the Shikoku Karst region. The journey from Tawaramachi was challenging due to difficult roads. I encountered a truck loaded with lumber, which required me to back up for about 100 meters, and I had to detour around a mountain due to construction. It''s worth noting that Ohnogahara is located in Seiyo City.' where id = '_oAo0kAx5OLJqS0TX9mhY';
update content_bodies set title = '雄川の滝', description = 'この動画は雄川の滝について紹介しています。雄川の滝は美しい自然の景観を持ち、多くの観光客を魅了しています。滝の周辺には豊かな緑が広がり、訪れる人々に癒しを与えています。動画では、滝の迫力や周囲の風景が映し出され、雄川の滝の魅力を伝えています。' where id = '2Wrnl8gJY_Fkng4FnCv4u';
update content_bodies set title = 'Yukawa Falls', description = 'This video introduces Yukawa Falls.' where id = 'hu4ypLpOwjlzh2OI8ckmY';
update content_bodies set title = '愛南町 須ノ川海岸をただ、ただ歩く', description = '須ノ川海岸を歩きました。ただ、ただそれだけです。須ノ川海岸は日本の渚百選に選ばれており、玉の浜石が特徴ですが、大きなサイズの石がゴロゴロしているため、正直歩くのは大変です。だから、海岸には降りていません。隣接する須の川公園では、夏になると親子連れがキャンプや海水浴に訪れます。' where id = 'eyKzMkrTvZeqQ2TyIbvgD';
update content_bodies set title = 'Walking Along Sunokawa Beach', description = 'I took a walk along Sunokawa Beach. That''s all there is to it. Sunokawa Beach is selected as one of Japan''s top 100 beaches. It is characterized by large stones known as ''Tama no Hama'' which make walking quite challenging. This is why I didn''t actually go down to the beach. In the adjacent Sunokawa Park, families come for camping and swimming during the summer.' where id = 'hSCvTWqdIlrppL2H2CmTx';
update content_bodies set title = '愛南町 高茂岬をただ、ただ歩く・・・(2022.5.22)', description = '高茂岬を歩きました。ただ、ただそれだけです。高茂岬は愛媛県南宇和郡愛南町にあり、足摺宇和海国立公園に指定されています。また、四国八十八景の43番として「連なる断崖絶壁と太平洋の広大な海原を一望」と選定されています。道中は四国カルストほどではありませんが、少し厳しいです。' where id = 'wHC6CHnVAibiVx2YtgZib';
update content_bodies set title = 'Walking at Takamo Cape...', description = 'I walked at Takamo Cape. That''s all there is to it. Takamo Cape is located in Ainanchō, Minamiuwa District, Ehime Prefecture, and is designated as part of the Ashizuri-Uwakai National Park. It is also selected as the 43rd of the Shikoku 88 Scenic Views, offering a panoramic view of the rugged cliffs and the vast Pacific Ocean. The path is somewhat challenging, though not as difficult as the Shikoku Karst.' where id = 'gPI8UNduVvUIKLHLtJIkV';
